INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_005_calc1','lesson_005','numeric',20,true,1,'{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0795073 kW.","en":"Absolute tolerance ±0.0795073 kW."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
