INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_019_calc1','lesson_019','numeric',20,true,1,'{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0735133 kW.","en":"Absolute tolerance ±0.0735133 kW."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_019_calc1','{"value":24.504422698000386,"unit":"kW","abs_tolerance":0.07351326809400116}'::jsonb,'{}'::jsonb,'{"fr":"1. ω = 2π × 2600/60 rad/s.\n2. P = 90ω/1000 = 24.5044 kW.\n3. Débit = 24.5044 × 245/1000 = 6.0036 kg/h.\n4. Puissance chimique = 76.5763 kW ; pertes totales = 52.0719 kW. Elles ne vont pas toutes au liquide de refroidissement.\n\nLe rendement et la BSFC sont des hypothèses d’exercice ; ni émissions ni cycle complet ne sont calculés.","en":"1. ω = 2π × 2600/60 rad/s.\n2. P = 90ω/1000 = 24.5044 kW.\n3. Flow = 24.5044 × 245/1000 = 6.0036 kg/h.\n4. Chemical power = 76.5763 kW; total losses = 52.0719 kW. These losses do not all enter the coolant.\n\nEfficiency and BSFC are exercise assumptions; emissions and a full cycle are not calculated."}'::jsonb) ON CONFLICT DO NOTHING;
