INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_019_review','lesson_019','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_019_review_c1","position":1,"labels":{"fr":"Présenter directement le débit en kg/h comme une consommation en L/100 km.","en":"Present kg/h directly as L/100 km."}},{"id":"eng_019_review_c2","position":2,"labels":{"fr":"Affecter toutes les pertes à l’échangeur liquide sans autre bilan.","en":"Assign every loss to the coolant heat exchanger without another balance."}},{"id":"eng_019_review_c3","position":3,"labels":{"fr":"Conserver ce point stationnaire et demander carte, transitoires, vitesse véhicule et densité avant de conclure en L/100 km.","en":"Retain this steady operating point and request maps, transients, road speed and density before concluding in L/100 km."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_019_review','{"choice_id":"eng_019_review_c3"}'::jsonb,'{}'::jsonb,'{"fr":"Conserver ce point stationnaire et demander carte, transitoires, vitesse véhicule et densité avant de conclure en L/100 km. Le rendement et la BSFC sont des hypothèses d’exercice ; ni émissions ni cycle complet ne sont calculés.","en":"Retain this steady operating point and request maps, transients, road speed and density before concluding in L/100 km. Efficiency and BSFC are exercise assumptions; emissions and a full cycle are not calculated."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_020_calc1','lesson_020','numeric',20,true,1,'{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.466667 km.","en":"Absolute tolerance ±0.466667 km."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_020_calc1','{"value":155.55555555555557,"unit":"km","abs_tolerance":0.46666666666666673}'::jsonb,'{}'::jsonb,'{"fr":"1. Énergie utile : 28 × 0,80 = 22.4 kWh.\n2. Convertir en Wh : 22400 Wh.\n3. Autonomie nominale : 22400 / 144 = 155.5556 km.\n4. Autonomie dégradée : 22400 / 164 = 136.5854 km.\n5. Besoin utile pour 150 km dégradés : 150 × 164/1000 = 24.6 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 28 × 0.80 = 22.4 kWh.\n2. Convert to Wh: 22400 Wh.\n3. Nominal range: 22400 / 144 = 155.5556 km.\n4. Degraded range: 22400 / 164 = 136.5854 km.\n5. Usable energy for 150 degraded kilometres: 150 × 164/1000 = 24.6 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_020_calc2','lesson_020','numeric',20,true,1,'{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.409756 km.","en":"Absolute tolerance ±0.409756 km."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
