INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_022_review','lesson_022','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_022_review_c1","position":1,"labels":{"fr":"Valider le moteur avec sa puissance crête, même si la durée admissible est inconnue.","en":"Approve using peak power even though its admissible duration is unknown."}},{"id":"eng_022_review_c2","position":2,"labels":{"fr":"Diviser la puissance roues par 0,95 puis par 0,90 avant d’ajouter les auxiliaires.","en":"Divide wheel power by 0.95 and then by 0.90 before adding auxiliaries."}},{"id":"eng_022_review_c3","position":3,"labels":{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_022_review','{"choice_id":"eng_022_review_c3"}'::jsonb,'{}'::jsonb,'{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur. Rendements constants, inerties tournantes et transitoires omis.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection. Constant efficiencies; rotating inertia and transients omitted."}'::jsonb) ON CONFLICT DO NOTHING;
