INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_025_calc1','lesson_025','numeric',20,true,1,'{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0628319 kW.","en":"Absolute tolerance ±0.0628319 kW."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_025_calc1','{"value":20.94395102393195,"unit":"kW","abs_tolerance":0.06283185307179585}'::jsonb,'{}'::jsonb,'{"fr":"1. ω = 2π × 2500/60 rad/s.\n2. P = 80ω/1000 = 20.944 kW.\n3. Débit = 20.944 × 240/1000 = 5.0265 kg/h.\n4. Puissance chimique = 65.4498 kW ; pertes totales = 44.5059 kW. Elles ne vont pas toutes au liquide de refroidissement.\n\nLe rendement et la BSFC sont des hypothèses d’exercice ; ni émissions ni cycle complet ne sont calculés.","en":"1. ω = 2π × 2500/60 rad/s.\n2. P = 80ω/1000 = 20.944 kW.\n3. Flow = 20.944 × 240/1000 = 5.0265 kg/h.\n4. Chemical power = 65.4498 kW; total losses = 44.5059 kW. These losses do not all enter the coolant.\n\nEfficiency and BSFC are exercise assumptions; emissions and a full cycle are not calculated."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_025_calc2','lesson_025','numeric',20,true,1,'{"unit":"kg/h","toleranceLabel":{"fr":"Tolérance absolue ±0.02 kg/h.","en":"Absolute tolerance ±0.02 kg/h."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_025_calc2','{"value":5.026548245743668,"unit":"kg/h","abs_tolerance":0.02}'::jsonb,'{}'::jsonb,'{"fr":"1. ω = 2π × 2500/60 rad/s.\n2. P = 80ω/1000 = 20.944 kW.\n3. Débit = 20.944 × 240/1000 = 5.0265 kg/h.\n4. Puissance chimique = 65.4498 kW ; pertes totales = 44.5059 kW. Elles ne vont pas toutes au liquide de refroidissement.\n\nLe rendement et la BSFC sont des hypothèses d’exercice ; ni émissions ni cycle complet ne sont calculés.","en":"1. ω = 2π × 2500/60 rad/s.\n2. P = 80ω/1000 = 20.944 kW.\n3. Flow = 20.944 × 240/1000 = 5.0265 kg/h.\n4. Chemical power = 65.4498 kW; total losses = 44.5059 kW. These losses do not all enter the coolant.\n\nEfficiency and BSFC are exercise assumptions; emissions and a full cycle are not calculated."}'::jsonb) ON CONFLICT DO NOTHING;
