INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_031_calc1','{"value":121.42857142857143,"unit":"MPa","abs_tolerance":0.3642857142857143}'::jsonb,'{}'::jsonb,'{"fr":"1. Contrainte = 11900/98 = 121.4286 N/mm² = MPa.\n2. Allongement = 11900 × 150/(70000 × 98) = 0.2602 mm.\n3. Volume = 98 × 150 mm³ = 0 m³ ; masse = 0.0397 kg.\n4. Une réduction de 20 % de A multiplie contrainte et allongement par 1/0,8 = 1,25.\n\nTraction uniforme seulement : aucun dimensionnement de structure véhicule réelle.","en":"1. Stress = 11900/98 = 121.4286 N/mm² = MPa.\n2. Extension = 11900 × 150/(70000 × 98) = 0.2602 mm.\n3. Volume = 98 × 150 mm³ = 0 m³; mass = 0.0397 kg.\n4. Reducing A by 20% multiplies stress and extension by 1/0.8 = 1.25.\n\nUniform tension only: not real vehicle structural sizing."}'::jsonb) ON CONFLICT DO NOTHING;
