INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_034_review','lesson_034','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_034_review_c1","position":1,"labels":{"fr":"Valider le crash à partir de la seule contrainte nominale.","en":"Approve crash performance from nominal stress alone."}},{"id":"eng_034_review_c2","position":2,"labels":{"fr":"Affirmer que réduire la section réduit aussi la contrainte parce que la pièce est plus légère.","en":"Claim reducing area also reduces stress because the part is lighter."}},{"id":"eng_034_review_c3","position":3,"labels":{"fr":"Vérifier la limite, les concentrations, la fatigue et les fixations avant d’appliquer cette réduction à un support.","en":"Check limits, concentrations, fatigue and joints before applying this reduction to a bracket."}}]'::jsonb) ON CONFLICT DO NOTHING;
