INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_035_calc1','lesson_035','numeric',20,true,1,'{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.088117 kW.","en":"Absolute tolerance ±0.088117 kW."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_035_calc1','{"value":29.37232160999214,"unit":"kW","abs_tolerance":0.08811696482997643}'::jsonb,'{}'::jsonb,'{"fr":"1. v = 21.1111 m/s ; θ = 0.0798 rad.\n2. Roulement 149.615 N ; aéro 174.7062 N ; pente 997.4333 N.\n3. Total 1321.7545 N ; roues 27.9037 kW.\n4. Machine 29.3723 kW ; batterie 31.8041 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6479.8798 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 21.1111 m/s; θ = 0.0798 rad.\n2. Rolling 149.615 N; drag 174.7062 N; grade 997.4333 N.\n3. Total 1321.7545 N; wheel power 27.9037 kW.\n4. Machine 29.3723 kW; battery 31.8041 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6479.8798 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}'::jsonb) ON CONFLICT DO NOTHING;
