INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_035_review','lesson_035','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_035_review_c1","position":1,"labels":{"fr":"Diviser la puissance roues par 0,95 puis par 0,90 avant d’ajouter les auxiliaires.","en":"Divide wheel power by 0.95 and then by 0.90 before adding auxiliaries."}},{"id":"eng_035_review_c2","position":2,"labels":{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection."}},{"id":"eng_035_review_c3","position":3,"labels":{"fr":"Valider le moteur avec sa puissance crête, même si la durée admissible est inconnue.","en":"Approve using peak power even though its admissible duration is unknown."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_035_review','{"choice_id":"eng_035_review_c2"}'::jsonb,'{}'::jsonb,'{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur. Rendements constants, inerties tournantes et transitoires omis.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection. Constant efficiencies; rotating inertia and transients omitted."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_036_calc1','lesson_036','numeric',20,true,1,'{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.455696 km.","en":"Absolute tolerance ±0.455696 km."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_036_calc1','{"value":151.8987341772152,"unit":"km","abs_tolerance":0.4556962025316456}'::jsonb,'{}'::jsonb,'{"fr":"1. Énergie utile : 30 × 0,80 = 24 kWh.\n2. Convertir en Wh : 24000 Wh.\n3. Autonomie nominale : 24000 / 158 = 151.8987 km.\n4. Autonomie dégradée : 24000 / 178 = 134.8315 km.\n5. Besoin utile pour 150 km dégradés : 150 × 178/1000 = 26.7 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 30 × 0.80 = 24 kWh.\n2. Convert to Wh: 24000 Wh.\n3. Nominal range: 24000 / 158 = 151.8987 km.\n4. Degraded range: 24000 / 178 = 134.8315 km.\n5. Usable energy for 150 degraded kilometres: 150 × 178/1000 = 26.7 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}'::jsonb) ON CONFLICT DO NOTHING;
