INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_038_review','lesson_038','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_038_review_c1","position":1,"labels":{"fr":"Moyenner les deux autonomies pour déclarer la cible satisfaite dans les deux cas.","en":"Average both ranges to declare that both scenarios meet the target."}},{"id":"eng_038_review_c2","position":2,"labels":{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity."}},{"id":"eng_038_review_c3","position":3,"labels":{"fr":"Utiliser l’énergie brute pour tous les scénarios, puisque la fenêtre ne change que la recharge.","en":"Use gross energy in every scenario because the window only affects charging."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_038_review','{"choice_id":"eng_038_review_c2"}'::jsonb,'{}'::jsonb,'{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie. La consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity. Consumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_039_calc1','lesson_039','numeric',20,true,1,'{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.75 ms.","en":"Absolute tolerance ±0.75 ms."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_039_calc1','{"value":250,"unit":"ms","abs_tolerance":0.75}'::jsonb,'{}'::jsonb,'{"fr":"1. Acquisition limitante : max(60,40) = 60 ms.\n2. Chaîne = 60+20+25+15+10+120 = 250 ms.\n3. Marge nominale = 300−250 = 50 ms.\n4. Budget fusion maximal, autres temps inchangés : 75 ms.\n5. Un délai de file ou une donnée déjà âgée exige une extension du modèle.\n\nPas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"1. Limiting acquisition: max(60,40) = 60 ms.\n2. Chain = 60+20+25+15+10+120 = 250 ms.\n3. Nominal margin = 300−250 = 50 ms.\n4. Maximum fusion budget with other times fixed: 75 ms.\n5. Queue delay or already-old data requires extending the model.\n\nNo jitter, queues or asynchronous effects modelled; educational target only."}'::jsonb) ON CONFLICT DO NOTHING;
