INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_065_review','lesson_065','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_065_review_c1","position":1,"labels":{"fr":"Soustraire chaque règle indépendamment même si plusieurs excluent la même combinaison.","en":"Subtract each rule independently even when several exclude the same combination."}},{"id":"eng_065_review_c2","position":2,"labels":{"fr":"Versionner les règles d’effectivité et associer chaque résultat à la combinaison réellement testée.","en":"Version effectivity rules and connect results to the configuration actually tested."}},{"id":"eng_065_review_c3","position":3,"labels":{"fr":"Utiliser seulement la version logicielle comme preuve de configuration complète.","en":"Use software version alone as complete configuration evidence."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_065_review','{"choice_id":"eng_065_review_c2"}'::jsonb,'{}'::jsonb,'{"fr":"Versionner les règles d’effectivité et associer chaque résultat à la combinaison réellement testée. Une couverture combinatoire ne prouve pas que les scénarios de défaillance sont couverts.","en":"Version effectivity rules and connect results to the configuration actually tested. Combinatorial coverage does not establish failure-scenario coverage."}'::jsonb) ON CONFLICT DO NOTHING;
