INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_085_calc3','lesson_085','numeric',20,true,1,'{"unit":"jours","toleranceLabel":{"fr":"Tolérance absolue ±0.045 jours.","en":"Absolute tolerance ±0.045 jours."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_085_calc3','{"value":15,"unit":"jours","abs_tolerance":0.045}'::jsonb,'{}'::jsonb,'{"fr":"1. Fin A = 7.\n2. Fin B = 14, fin C = 13.\n3. D commence à 14 ; fin programme 16 jours.\n4. Marge de C = 1 jours.\n5. B réduit de 2 jours : nouvelle durée 15 jours ; une autre branche peut devenir critique.\n\nNi jours ouvrés ni ressource partagée ne sont modélisés.","en":"1. A finishes at 7.\n2. B finishes at 14, C at 13.\n3. D starts at 14; completion is day 16.\n4. C float = 1 days.\n5. Shortening B by 2 days gives 15 total days; another branch can become critical.\n\nWorking calendars and shared-resource constraints are not modelled."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_085_review','lesson_085','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_085_review_c1","position":1,"labels":{"fr":"Additionner A, B, C et D pour obtenir la durée, même si B et C sont parallèles.","en":"Add A, B, C and D despite parallel B and C."}},{"id":"eng_085_review_c2","position":2,"labels":{"fr":"Promettre deux jours gagnés sur le programme dès que n’importe quelle tâche gagne deux jours.","en":"Promise two programme days saved whenever any task is shortened by two days."}},{"id":"eng_085_review_c3","position":3,"labels":{"fr":"Vérifier chemin critique et capacité avant d’annoncer le gain de rattrapage.","en":"Check critical path and capacity before announcing recovery benefit."}}]'::jsonb) ON CONFLICT DO NOTHING;
