INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_086_calc1','{"value":0.7741935483870968,"unit":"ratio","abs_tolerance":0.00232258064516129}'::jsonb,'{}'::jsonb,'{"fr":"1. CPI = 120000/155000 = 0.7742.\n2. SPI = 120000/145000 = 0.8276.\n3. EAC = 600000/0.7742 ≈ 775000 €.\n4. CPI < 1 indique un coût supérieur au budget de la valeur acquise ; SPI ne prouve pas la date finale.\n\nLe forecast suppose la poursuite de l’efficacité de coût observée.","en":"1. CPI = 120000/155000 = 0.7742.\n2. SPI = 120000/145000 = 0.8276.\n3. EAC = 600000/0.7742 ≈ €775000.\n4. CPI < 1 indicates earned work cost more than its budget; SPI does not establish completion date.\n\nForecast assumes observed cost efficiency continues."}'::jsonb) ON CONFLICT DO NOTHING;
