INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_095_calc1','{"value":12,"unit":"jours","abs_tolerance":0.036000000000000004}'::jsonb,'{}'::jsonb,'{"fr":"1. Fin A = 3.\n2. Fin B = 10, fin C = 8.\n3. D commence à 10 ; fin programme 12 jours.\n4. Marge de C = 2 jours.\n5. B réduit de 2 jours : nouvelle durée 10 jours ; une autre branche peut devenir critique.\n\nNi jours ouvrés ni ressource partagée ne sont modélisés.","en":"1. A finishes at 3.\n2. B finishes at 10, C at 8.\n3. D starts at 10; completion is day 12.\n4. C float = 2 days.\n5. Shortening B by 2 days gives 10 total days; another branch can become critical.\n\nWorking calendars and shared-resource constraints are not modelled."}'::jsonb) ON CONFLICT DO NOTHING;
