INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_095_calc3','{"value":10,"unit":"jours","abs_tolerance":0.03}'::jsonb,'{}'::jsonb,'{"fr":"1. Fin A = 3.\n2. Fin B = 10, fin C = 8.\n3. D commence à 10 ; fin programme 12 jours.\n4. Marge de C = 2 jours.\n5. B réduit de 2 jours : nouvelle durée 10 jours ; une autre branche peut devenir critique.\n\nNi jours ouvrés ni ressource partagée ne sont modélisés.","en":"1. A finishes at 3.\n2. B finishes at 10, C at 8.\n3. D starts at 10; completion is day 12.\n4. C float = 2 days.\n5. Shortening B by 2 days gives 10 total days; another branch can become critical.\n\nWorking calendars and shared-resource constraints are not modelled."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_095_review','lesson_095','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_095_review_c1","position":1,"labels":{"fr":"Promettre deux jours gagnés sur le programme dès que n’importe quelle tâche gagne deux jours.","en":"Promise two programme days saved whenever any task is shortened by two days."}},{"id":"eng_095_review_c2","position":2,"labels":{"fr":"Vérifier chemin critique et capacité avant d’annoncer le gain de rattrapage.","en":"Check critical path and capacity before announcing recovery benefit."}},{"id":"eng_095_review_c3","position":3,"labels":{"fr":"Additionner A, B, C et D pour obtenir la durée, même si B et C sont parallèles.","en":"Add A, B, C and D despite parallel B and C."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_095_review','{"choice_id":"eng_095_review_c2"}'::jsonb,'{}'::jsonb,'{"fr":"Vérifier chemin critique et capacité avant d’annoncer le gain de rattrapage. Ni jours ouvrés ni ressource partagée ne sont modélisés.","en":"Check critical path and capacity before announcing recovery benefit. Working calendars and shared-resource constraints are not modelled."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_096_calc1','lesson_096','numeric',20,true,1,'{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.472993 km.","en":"Absolute tolerance ±0.472993 km."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_096_calc1','{"value":157.66423357664235,"unit":"km","abs_tolerance":0.47299270072992705}'::jsonb,'{}'::jsonb,'{"fr":"1. Énergie utile : 27 × 0,80 = 21.6 kWh.\n2. Convertir en Wh : 21600 Wh.\n3. Autonomie nominale : 21600 / 137 = 157.6642 km.\n4. Autonomie dégradée : 21600 / 157 = 137.5796 km.\n5. Besoin utile pour 150 km dégradés : 150 × 157/1000 = 23.55 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 27 × 0.80 = 21.6 kWh.\n2. Convert to Wh: 21600 Wh.\n3. Nominal range: 21600 / 137 = 157.6642 km.\n4. Degraded range: 21600 / 157 = 137.5796 km.\n5. Usable energy for 150 degraded kilometres: 150 × 157/1000 = 23.55 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_096_calc2','lesson_096','numeric',20,true,1,'{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.412739 km.","en":"Absolute tolerance ±0.412739 km."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
