INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_096_review','lesson_096','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_096_review_c1","position":1,"labels":{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity."}},{"id":"eng_096_review_c2","position":2,"labels":{"fr":"Utiliser l’énergie brute pour tous les scénarios, puisque la fenêtre ne change que la recharge.","en":"Use gross energy in every scenario because the window only affects charging."}},{"id":"eng_096_review_c3","position":3,"labels":{"fr":"Moyenner les deux autonomies pour déclarer la cible satisfaite dans les deux cas.","en":"Average both ranges to declare that both scenarios meet the target."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_096_review','{"choice_id":"eng_096_review_c1"}'::jsonb,'{}'::jsonb,'{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie. La consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity. Consumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_097_calc1','lesson_097','numeric',20,true,1,'{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0837491 kW.","en":"Absolute tolerance ±0.0837491 kW."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_097_calc1','{"value":27.916375698304435,"unit":"kW","abs_tolerance":0.0837491270949133}'::jsonb,'{}'::jsonb,'{"fr":"1. v = 20.5556 m/s ; θ = 0.0798 rad.\n2. Roulement 146.6814 N ; aéro 165.6321 N ; pente 977.8758 N.\n3. Total 1290.1893 N ; roues 26.5206 kW.\n4. Machine 27.9164 kW ; batterie 30.2673 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6309.3567 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 20.5556 m/s; θ = 0.0798 rad.\n2. Rolling 146.6814 N; drag 165.6321 N; grade 977.8758 N.\n3. Total 1290.1893 N; wheel power 26.5206 kW.\n4. Machine 27.9164 kW; battery 30.2673 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6309.3567 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}'::jsonb) ON CONFLICT DO NOTHING;
