INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_097_review','lesson_097','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_097_review_c1","position":1,"labels":{"fr":"Valider le moteur avec sa puissance crête, même si la durée admissible est inconnue.","en":"Approve using peak power even though its admissible duration is unknown."}},{"id":"eng_097_review_c2","position":2,"labels":{"fr":"Diviser la puissance roues par 0,95 puis par 0,90 avant d’ajouter les auxiliaires.","en":"Divide wheel power by 0.95 and then by 0.90 before adding auxiliaries."}},{"id":"eng_097_review_c3","position":3,"labels":{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_097_review','{"choice_id":"eng_097_review_c3"}'::jsonb,'{}'::jsonb,'{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur. Rendements constants, inerties tournantes et transitoires omis.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection. Constant efficiencies; rotating inertia and transients omitted."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_098_calc1','lesson_098','numeric',20,true,1,'{"unit":"kg/s","toleranceLabel":{"fr":"Tolérance absolue ±0.000373206 kg/s.","en":"Absolute tolerance ±0.000373206 kg/s."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_098_calc1','{"value":0.12440191387559808,"unit":"kg/s","abs_tolerance":0.00037320574162679425}'::jsonb,'{}'::jsonb,'{"fr":"1. Débit nominal = 2600/(4180×5) = 0.1244 kg/s.\n2. Pertes +20 % : débit nécessaire 0.1493 kg/s.\n3. Débit −20 % : hausse = 5/0,8 = 6.25 K.\n4. Vérifier ensuite températures d’entrée, pompe, échangeur et perte de charge.\n\nChaleur spécifique constante et régime établi, sans modèle d’échangeur.","en":"1. Nominal flow = 2600/(4180×5) = 0.1244 kg/s.\n2. Heat +20%: required flow 0.1493 kg/s.\n3. Flow −20%: rise = 5/0.8 = 6.25 K.\n4. Then check inlet temperatures, pump, heat exchanger and pressure loss.\n\nConstant heat capacity and steady state, without an exchanger model."}'::jsonb) ON CONFLICT DO NOTHING;
