INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_098_review','lesson_098','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_098_review_c1","position":1,"labels":{"fr":"Réduire le débit de 20 % et annoncer aussi une réduction de ΔT de 20 %.","en":"Reduce flow by 20% and claim ΔT also falls by 20%."}},{"id":"eng_098_review_c2","position":2,"labels":{"fr":"Partager un contrat thermique avec températures, débit, pertes et scénarios, puis vérifier l’échangeur et la pompe.","en":"Share a thermal contract with temperatures, flow, heat and scenarios, then verify exchanger and pump."}},{"id":"eng_098_review_c3","position":3,"labels":{"fr":"Valider le refroidissement sur le seul ΔT sans températures absolues ni échangeur.","en":"Approve cooling from ΔT alone without absolute temperatures or exchanger checks."}}]'::jsonb) ON CONFLICT DO NOTHING;
