INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_099_calc1','lesson_099','numeric',20,true,1,'{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.159 %.","en":"Absolute tolerance ±0.159 %."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_099_calc1','{"value":52.99999999999999,"unit":"%","abs_tolerance":0.15899999999999997}'::jsonb,'{}'::jsonb,'{"fr":"1. Contributions : 28 %, 15 %, 10 %.\n2. Utilisation initiale = 53 %.\n3. Nouvelle tâche = 20 points ; total 73 %.\n4. Réserve moyenne = 27 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 28%, 15%, 10%.\n2. Initial utilisation = 53%.\n3. Extra task adds 20 points; total 73%.\n4. Average reserve = 27%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_099_calc2','lesson_099','numeric',20,true,1,'{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.219 %.","en":"Absolute tolerance ±0.219 %."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_099_calc2','{"value":73.0,"unit":"%","abs_tolerance":0.219}'::jsonb,'{}'::jsonb,'{"fr":"1. Contributions : 28 %, 15 %, 10 %.\n2. Utilisation initiale = 53 %.\n3. Nouvelle tâche = 20 points ; total 73 %.\n4. Réserve moyenne = 27 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 28%, 15%, 10%.\n2. Initial utilisation = 53%.\n3. Extra task adds 20 points; total 73%.\n4. Average reserve = 27%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}'::jsonb) ON CONFLICT DO NOTHING;
