INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_100_calc1','{"value":0.14354066985645933,"unit":"kg/s","abs_tolerance":0.000430622009569378}'::jsonb,'{}'::jsonb,'{"fr":"1. Débit nominal = 3000/(4180×5) = 0.1435 kg/s.\n2. Pertes +20 % : débit nécessaire 0.1722 kg/s.\n3. Débit −20 % : hausse = 5/0,8 = 6.25 K.\n4. Vérifier ensuite températures d’entrée, pompe, échangeur et perte de charge.\n\nChaleur spécifique constante et régime établi, sans modèle d’échangeur.","en":"1. Nominal flow = 3000/(4180×5) = 0.1435 kg/s.\n2. Heat +20%: required flow 0.1722 kg/s.\n3. Flow −20%: rise = 5/0.8 = 6.25 K.\n4. Then check inlet temperatures, pump, heat exchanger and pressure loss.\n\nConstant heat capacity and steady state, without an exchanger model."}'::jsonb) ON CONFLICT DO NOTHING;
