INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_102_calc1','{"value":160.0,"unit":"km","abs_tolerance":0.48}'::jsonb,'{}'::jsonb,'{"fr":"1. Énergie utile : 26 × 0,80 = 20.8 kWh.\n2. Convertir en Wh : 20800 Wh.\n3. Autonomie nominale : 20800 / 130 = 160 km.\n4. Autonomie dégradée : 20800 / 150 = 138.6667 km.\n5. Besoin utile pour 150 km dégradés : 150 × 150/1000 = 22.5 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 26 × 0.80 = 20.8 kWh.\n2. Convert to Wh: 20800 Wh.\n3. Nominal range: 20800 / 130 = 160 km.\n4. Degraded range: 20800 / 150 = 138.6667 km.\n5. Usable energy for 150 degraded kilometres: 150 × 150/1000 = 22.5 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_102_calc2','lesson_102','numeric',20,true,1,'{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.416 km.","en":"Absolute tolerance ±0.416 km."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
