INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_102_review','lesson_102','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_102_review_c1","position":1,"labels":{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity."}},{"id":"eng_102_review_c2","position":2,"labels":{"fr":"Utiliser l’énergie brute pour tous les scénarios, puisque la fenêtre ne change que la recharge.","en":"Use gross energy in every scenario because the window only affects charging."}},{"id":"eng_102_review_c3","position":3,"labels":{"fr":"Moyenner les deux autonomies pour déclarer la cible satisfaite dans les deux cas.","en":"Average both ranges to declare that both scenarios meet the target."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_102_review','{"choice_id":"eng_102_review_c1"}'::jsonb,'{}'::jsonb,'{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie. La consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity. Consumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_103_calc1','lesson_103','numeric',20,true,1,'{"unit":"MPa","toleranceLabel":{"fr":"Tolérance absolue ±0.312651 MPa.","en":"Absolute tolerance ±0.312651 MPa."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_103_calc1','{"value":104.21686746987952,"unit":"MPa","abs_tolerance":0.31265060240963854}'::jsonb,'{}'::jsonb,'{"fr":"1. Contrainte = 8650/83 = 104.2169 N/mm² = MPa.\n2. Allongement = 8650 × 150/(70000 × 83) = 0.2233 mm.\n3. Volume = 83 × 150 mm³ = 0 m³ ; masse = 0.0336 kg.\n4. Une réduction de 20 % de A multiplie contrainte et allongement par 1/0,8 = 1,25.\n\nTraction uniforme seulement : aucun dimensionnement de structure véhicule réelle.","en":"1. Stress = 8650/83 = 104.2169 N/mm² = MPa.\n2. Extension = 8650 × 150/(70000 × 83) = 0.2233 mm.\n3. Volume = 83 × 150 mm³ = 0 m³; mass = 0.0336 kg.\n4. Reducing A by 20% multiplies stress and extension by 1/0.8 = 1.25.\n\nUniform tension only: not real vehicle structural sizing."}'::jsonb) ON CONFLICT DO NOTHING;
