INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_105_calc1','lesson_105','numeric',20,true,1,'{"unit":"€/an","toleranceLabel":{"fr":"Tolérance absolue ±55.2 €/an.","en":"Absolute tolerance ±55.2 €/an."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_105_calc1','{"value":18400.0,"unit":"€/an","abs_tolerance":55.2}'::jsonb,'{}'::jsonb,'{"fr":"1. Exposition avant = 0,08×230000 = 18400 €/an.\n2. Après = 0,03×230000 = 6900 €/an.\n3. Gain net espéré = 18400−6900−5000 = 6500 €/an.\n4. Ce gain dépend d’une réduction de probabilité supposée ; la sécurité exige objectifs, tests et risque résiduel.\n\nLes probabilités d’attaque sont fictives ; aucune décision de conformité réelle n’en découle.","en":"1. Exposure before = 0.08×230000 = €18400/year.\n2. After = 0.03×230000 = €6900/year.\n3. Expected net benefit = 18400−6900−5000 = €6500/year.\n4. Benefit depends on an assumed probability reduction; security needs objectives, tests and residual-risk analysis.\n\nAttack probabilities are fictional; no actual compliance decision follows."}'::jsonb) ON CONFLICT DO NOTHING;
