INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_108_review','lesson_108','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_108_review_c1","position":1,"labels":{"fr":"Garder visibles l’échec critique, les exigences sans preuve et les configurations ; décider un plan de fermeture.","en":"Keep the critical failure, unproven requirements and configurations visible; decide a closure plan."}},{"id":"eng_108_review_c2","position":2,"labels":{"fr":"Moyenner les deux pourcentages pour annoncer une conformité véhicule unique.","en":"Average the percentages to announce a single vehicle-compliance rate."}},{"id":"eng_108_review_c3","position":3,"labels":{"fr":"Reclasser les deux échecs comme non exécutés pour améliorer le taux.","en":"Reclassify failures as not executed to improve the rate."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_108_review','{"choice_id":"eng_108_review_c1"}'::jsonb,'{}'::jsonb,'{"fr":"Garder visibles l’échec critique, les exigences sans preuve et les configurations ; décider un plan de fermeture. Les comptes sont fictifs et n’établissent pas la qualité des méthodes de preuve.","en":"Keep the critical failure, unproven requirements and configurations visible; decide a closure plan. Counts are fictional and do not establish evidence-method quality."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_109_calc1','lesson_109','numeric',20,true,1,'{"unit":"kg/s","toleranceLabel":{"fr":"Tolérance absolue ±0.000287081 kg/s.","en":"Absolute tolerance ±0.000287081 kg/s."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_109_calc1','{"value":0.09569377990430622,"unit":"kg/s","abs_tolerance":0.00028708133971291867}'::jsonb,'{}'::jsonb,'{"fr":"1. Débit nominal = 2000/(4180×5) = 0.0957 kg/s.\n2. Pertes +20 % : débit nécessaire 0.1148 kg/s.\n3. Débit −20 % : hausse = 5/0,8 = 6.25 K.\n4. Vérifier ensuite températures d’entrée, pompe, échangeur et perte de charge.\n\nChaleur spécifique constante et régime établi, sans modèle d’échangeur.","en":"1. Nominal flow = 2000/(4180×5) = 0.0957 kg/s.\n2. Heat +20%: required flow 0.1148 kg/s.\n3. Flow −20%: rise = 5/0.8 = 6.25 K.\n4. Then check inlet temperatures, pump, heat exchanger and pressure loss.\n\nConstant heat capacity and steady state, without an exchanger model."}'::jsonb) ON CONFLICT DO NOTHING;
