INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_111_calc1','lesson_111','numeric',20,true,1,'{"unit":"A","toleranceLabel":{"fr":"Tolérance absolue ±0.036 A.","en":"Absolute tolerance ±0.036 A."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_111_calc1','{"value":12.0,"unit":"A","abs_tolerance":0.036000000000000004}'::jsonb,'{}'::jsonb,'{"fr":"1. I = 144/12 = 12 A.\n2. Chute = 12×0,05 = 0.6 V.\n3. Pertes = 12²×0,05 = 7.2 W.\n4. La tension réelle et le comportement de charge demandent un modèle couplé pour affiner.\n\nLe calcul fixe la tension pour une première estimation ; la charge peut réagir à la chute réelle.","en":"1. I = 144/12 = 12 A.\n2. Drop = 12×0.05 = 0.6 V.\n3. Loss = 12²×0.05 = 7.2 W.\n4. Actual voltage and load behaviour need a coupled model for refinement.\n\nVoltage is fixed for an initial estimate; the load may respond to actual drop."}'::jsonb) ON CONFLICT DO NOTHING;
