INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_131_calc1','{"value":47.0,"unit":"%","abs_tolerance":0.14100000000000001}'::jsonb,'{}'::jsonb,'{"fr":"1. Contributions : 22 %, 15 %, 10 %.\n2. Utilisation initiale = 47 %.\n3. Nouvelle tâche = 20 points ; total 67 %.\n4. Réserve moyenne = 33 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 22%, 15%, 10%.\n2. Initial utilisation = 47%.\n3. Extra task adds 20 points; total 67%.\n4. Average reserve = 33%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}'::jsonb) ON CONFLICT DO NOTHING;
