INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_136_calc1','lesson_136','numeric',20,true,1,'{"unit":"probabilité","toleranceLabel":{"fr":"Tolérance absolue ±3.2e-07 probabilité.","en":"Absolute tolerance ±3.2e-07 probabilité."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_136_calc1','{"value":0.00032,"unit":"probabilité","abs_tolerance":3.2e-07}'::jsonb,'{}'::jsonb,'{"fr":"1. AND indépendant = 0.0003.\n2. OR indépendant = 0.0357.\n3. Avec cause commune = 0.0053.\n4. Une cause commune rend trompeur le seul produit pA×pB ; les événements et durées doivent rester cohérents. Ces probabilités ne donnent aucun ASIL.\n\nModèle probabiliste fictif ; ni taux matériel réel ni preuve de sécurité.","en":"1. Independent AND = 0.0003.\n2. Independent OR = 0.0357.\n3. Including common cause = 0.0053.\n4. A common cause makes the bare pA×pB product misleading; event definitions and durations must match. These probabilities do not assign ASIL.\n\nFictional probability model; neither real hardware failure rates nor safety evidence."}'::jsonb) ON CONFLICT DO NOTHING;
