INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_165_calc1','lesson_165','numeric',20,true,1,'{"unit":"Wh/km","toleranceLabel":{"fr":"Tolérance absolue ±0.432 Wh/km.","en":"Absolute tolerance ±0.432 Wh/km."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_165_calc1','{"value":144.0,"unit":"Wh/km","abs_tolerance":0.432}'::jsonb,'{}'::jsonb,'{"fr":"1. Somme pondérée = 20×120+80×150 = 14400.\n2. Moyenne globale = 144 Wh/km.\n3. Moyenne non pondérée = 135 Wh/km : elle donnerait le même poids à des groupes de tailles différentes.\n4. Complétude configuration = 95 %.\n5. Ne pas remplacer les identifiants absents par une conformité supposée.\n\nLa moyenne ne prouve ni dispersion, ni maximum, ni causalité.","en":"1. Weighted sum = 20×120+80×150 = 14400.\n2. Combined mean = 144 Wh/km.\n3. Unweighted mean = 135 Wh/km: it would give equal weights to unequal-size groups.\n4. Configuration completeness = 95%.\n5. Missing IDs cannot be replaced by assumed compliance.\n\nThe mean establishes neither spread, maximum nor causality."}'::jsonb) ON CONFLICT DO NOTHING;
