INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_172_review','lesson_172','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_172_review_c1","position":1,"labels":{"fr":"Additionner caméra et radar même si les acquisitions sont parallèles dans le modèle donné.","en":"Add camera and radar times even though acquisition is parallel in this model."}},{"id":"eng_172_review_c2","position":2,"labels":{"fr":"Utiliser seulement le maximum de tous les temps, y compris ceux en série.","en":"Use only the maximum of all delays, including sequential stages."}},{"id":"eng_172_review_c3","position":3,"labels":{"fr":"Définir endpoints et pire cas avant de considérer la marge nominale comme une preuve de deadline.","en":"Define endpoints and worst case before treating nominal margin as deadline evidence."}}]'::jsonb) ON CONFLICT DO NOTHING;
