INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_173_calc1','lesson_173','numeric',20,true,1,'{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0795073 kW.","en":"Absolute tolerance ±0.0795073 kW."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_173_calc1','{"value":26.502442386335133,"unit":"kW","abs_tolerance":0.0795073271590054}'::jsonb,'{}'::jsonb,'{"fr":"1. v = 20 m/s ; θ = 0.0798 rad.\n2. Roulement 143.7477 N ; aéro 156.8 N ; pente 958.3183 N.\n3. Total 1258.866 N ; roues 25.1773 kW.\n4. Machine 26.5024 kW ; batterie 28.7748 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6138.8335 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 20 m/s; θ = 0.0798 rad.\n2. Rolling 143.7477 N; drag 156.8 N; grade 958.3183 N.\n3. Total 1258.866 N; wheel power 25.1773 kW.\n4. Machine 26.5024 kW; battery 28.7748 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6138.8335 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}'::jsonb) ON CONFLICT DO NOTHING;
