INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_174_calc1','{"value":108.13953488372093,"unit":"MPa","abs_tolerance":0.3244186046511628}'::jsonb,'{}'::jsonb,'{"fr":"1. Contrainte = 9300/86 = 108.1395 N/mm² = MPa.\n2. Allongement = 9300 × 150/(70000 × 86) = 0.2317 mm.\n3. Volume = 86 × 150 mm³ = 0 m³ ; masse = 0.0348 kg.\n4. Une réduction de 20 % de A multiplie contrainte et allongement par 1/0,8 = 1,25.\n\nTraction uniforme seulement : aucun dimensionnement de structure véhicule réelle.","en":"1. Stress = 9300/86 = 108.1395 N/mm² = MPa.\n2. Extension = 9300 × 150/(70000 × 86) = 0.2317 mm.\n3. Volume = 86 × 150 mm³ = 0 m³; mass = 0.0348 kg.\n4. Reducing A by 20% multiplies stress and extension by 1/0.8 = 1.25.\n\nUniform tension only: not real vehicle structural sizing."}'::jsonb) ON CONFLICT DO NOTHING;
