INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_177_calc1','lesson_177','numeric',20,true,1,'{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.284 %.","en":"Absolute tolerance ±0.284 %."}}'::jsonb,'[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_177_calc1','{"value":94.66666666666667,"unit":"%","abs_tolerance":0.28400000000000003}'::jsonb,'{}'::jsonb,'{"fr":"1. FPY = 1420/1500×100 = 94.6667 %.\n2. Rendement final = (1420+50)/1500×100 = 98 %.\n3. Rebuts = 1500−1420−50 = 30.\n4. Les 50 reprises coûtent du temps et des ressources, même si elles sont finalement bonnes.\n\nLe rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"1. FPY = 1420/1500×100 = 94.6667%.\n2. Final yield = (1420+50)/1500×100 = 98%.\n3. Scrap = 1500−1420−50 = 30.\n4. Rework consumes time and resources even when the units ultimately pass.\n\nYield alone establishes neither capability nor process stability."}'::jsonb) ON CONFLICT DO NOTHING;
