INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_178_calc1','{"value":0.775,"unit":"ratio","abs_tolerance":0.0023250000000000002}'::jsonb,'{}'::jsonb,'{"fr":"1. CPI = 124000/160000 = 0.775.\n2. SPI = 124000/150000 = 0.8267.\n3. EAC = 600000/0.775 ≈ 774193.5484 €.\n4. CPI < 1 indique un coût supérieur au budget de la valeur acquise ; SPI ne prouve pas la date finale.\n\nLe forecast suppose la poursuite de l’efficacité de coût observée.","en":"1. CPI = 124000/160000 = 0.775.\n2. SPI = 124000/150000 = 0.8267.\n3. EAC = 600000/0.775 ≈ €774193.5484.\n4. CPI < 1 indicates earned work cost more than its budget; SPI does not establish completion date.\n\nForecast assumes observed cost efficiency continues."}'::jsonb) ON CONFLICT DO NOTHING;
