INSERT INTO public.activities (id,lesson_id,kind,points,required,revision,settings,choices) VALUES ('eng_178_review','lesson_178','single_choice',15,true,1,'{}'::jsonb,'[{"id":"eng_178_review_c1","position":1,"labels":{"fr":"Déclarer le programme techniquement validé parce que EV est positif.","en":"Declare technical validation because EV is positive."}},{"id":"eng_178_review_c2","position":2,"labels":{"fr":"Utiliser SPI comme facteur de conversion certain vers une date de fin.","en":"Use SPI as a certain conversion factor to a completion date."}},{"id":"eng_178_review_c3","position":3,"labels":{"fr":"Analyser les livrables acquis, le chemin critique et l’hypothèse de forecast avant de décider.","en":"Examine earned deliverables, critical path and forecast assumptions before deciding."}}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.activity_solutions (activity_id,answer,rubric,explanation) VALUES ('eng_178_review','{"choice_id":"eng_178_review_c3"}'::jsonb,'{}'::jsonb,'{"fr":"Analyser les livrables acquis, le chemin critique et l’hypothèse de forecast avant de décider. Le forecast suppose la poursuite de l’efficacité de coût observée.","en":"Examine earned deliverables, critical path and forecast assumptions before deciding. Forecast assumes observed cost efficiency continues."}'::jsonb) ON CONFLICT DO NOTHING;
