INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_01','A','[{"id":"exam_01_A_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1250 kg ; vitesse 74 km/h ; pente 8 % ; Crr 0,012 ; ρ 1,225 kg/m³ ; CdA 0,64 m² ; rayon 0,28 m ; rapport 9 ; ηréducteur 0,95 ; ηglobal batterie-roues 0,90 ; auxiliaires 0,8 kW ; a = 0 ; sans vent.\n\nCalcule la puissance mécanique machine.","en":"Mass 1250 kg; speed 74 km/h; grade 8%; Crr 0.012; ρ 1.225 kg/m³; CdA 0.64 m²; radius 0.28 m; ratio 9; gear efficiency 0.95; overall battery-wheel efficiency 0.90; auxiliaries 0.8 kW; a = 0; still air.\n\nCalculate machine mechanical power."},"choices":[],"settings":{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0837491 kW.","en":"Absolute tolerance ±0.0837491 kW."}},"blockId":"exam_01_A_case1"},{"id":"exam_01_A_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1250 kg ; vitesse 74 km/h ; pente 8 % ; Crr 0,012 ; ρ 1,225 kg/m³ ; CdA 0,64 m² ; rayon 0,28 m ; rapport 9 ; ηréducteur 0,95 ; ηglobal batterie-roues 0,90 ; auxiliaires 0,8 kW ; a = 0 ; sans vent.\n\nCalcule la puissance électrique batterie, auxiliaires compris.","en":"Mass 1250 kg; speed 74 km/h; grade 8%; Crr 0.012; ρ 1.225 kg/m³; CdA 0.64 m²; radius 0.28 m; ratio 9; gear efficiency 0.95; overall battery-wheel efficiency 0.90; auxiliaries 0.8 kW; a = 0; still air.\n\nCalculate battery electrical power including auxiliaries."},"choices":[],"settings":{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0908019 kW.","en":"Absolute tolerance ±0.0908019 kW."}},"blockId":"exam_01_A_case1"},{"id":"exam_01_A_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1250 kg ; vitesse 74 km/h ; pente 8 % ; Crr 0,012 ; ρ 1,225 kg/m³ ; CdA 0,64 m² ; rayon 0,28 m ; rapport 9 ; ηréducteur 0,95 ; ηglobal batterie-roues 0,90 ; auxiliaires 0,8 kW ; a = 0 ; sans vent.\n\nCalcule le régime machine.","en":"Mass 1250 kg; speed 74 km/h; grade 8%; Crr 0.012; ρ 1.225 kg/m³; CdA 0.64 m²; radius 0.28 m; ratio 9; gear efficiency 0.95; overall battery-wheel efficiency 0.90; auxiliaries 0.8 kW; a = 0; still air.\n\nCalculate machine speed."},"choices":[],"settings":{"unit":"tr/min","toleranceLabel":{"fr":"Tolérance absolue ±18.9281 tr/min.","en":"Absolute tolerance ±18.9281 tr/min."}},"blockId":"exam_01_A_case1"},{"id":"exam_01_A_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1250 kg ; vitesse 74 km/h ; pente 8 % ; Crr 0,012 ; ρ 1,225 kg/m³ ; CdA 0,64 m² ; rayon 0,28 m ; rapport 9 ; ηréducteur 0,95 ; ηglobal batterie-roues 0,90 ; auxiliaires 0,8 kW ; a = 0 ; sans vent.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Mass 1250 kg; speed 74 km/h; grade 8%; Crr 0.012; ρ 1.225 kg/m³; CdA 0.64 m²; radius 0.28 m; ratio 9; gear efficiency 0.95; overall battery-wheel efficiency 0.90; auxiliaries 0.8 kW; a = 0; still air.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_01_A_case1_decision_c1","position":1,"labels":{"fr":"Valider le moteur avec sa puissance crête, même si la durée admissible est inconnue.","en":"Approve using peak power even though its admissible duration is unknown."}},{"id":"exam_01_A_case1_decision_c2","position":2,"labels":{"fr":"Diviser la puissance roues par 0,95 puis par 0,90 avant d’ajouter les auxiliaires.","en":"Divide wheel power by 0.95 and then by 0.90 before adding auxiliaries."}},{"id":"exam_01_A_case1_decision_c3","position":3,"labels":{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection."}}],"settings":{},"blockId":"exam_01_A_case1"},{"id":"exam_01_A_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 31 kWh ; fenêtre utile 80 % ; consommation nominale 165 Wh/km, scénario dégradé 185 Wh/km ; cible 150 km.\n\nCalcule l’autonomie nominale.","en":"Gross battery 31 kWh; usable window 80%; nominal consumption 165 Wh/km, degraded case 185 Wh/km; target 150 km.\n\nCalculate nominal range."},"choices":[],"settings":{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.450909 km.","en":"Absolute tolerance ±0.450909 km."}},"blockId":"exam_01_A_case2"},{"id":"exam_01_A_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 31 kWh ; fenêtre utile 80 % ; consommation nominale 165 Wh/km, scénario dégradé 185 Wh/km ; cible 150 km.\n\nCalcule l’autonomie dans le scénario dégradé.","en":"Gross battery 31 kWh; usable window 80%; nominal consumption 165 Wh/km, degraded case 185 Wh/km; target 150 km.\n\nCalculate degraded-case range."},"choices":[],"settings":{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.402162 km.","en":"Absolute tolerance ±0.402162 km."}},"blockId":"exam_01_A_case2"},{"id":"exam_01_A_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 31 kWh ; fenêtre utile 80 % ; consommation nominale 165 Wh/km, scénario dégradé 185 Wh/km ; cible 150 km.\n\nCalcule l’énergie utile nécessaire pour 150 km dégradés.","en":"Gross battery 31 kWh; usable window 80%; nominal consumption 165 Wh/km, degraded case 185 Wh/km; target 150 km.\n\nCalculate usable energy needed for 150 degraded kilometres."},"choices":[],"settings":{"unit":"kWh","toleranceLabel":{"fr":"Tolérance absolue ±0.08325 kWh.","en":"Absolute tolerance ±0.08325 kWh."}},"blockId":"exam_01_A_case2"},{"id":"exam_01_A_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 31 kWh ; fenêtre utile 80 % ; consommation nominale 165 Wh/km, scénario dégradé 185 Wh/km ; cible 150 km.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Gross battery 31 kWh; usable window 80%; nominal consumption 165 Wh/km, degraded case 185 Wh/km; target 150 km.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_01_A_case2_decision_c1","position":1,"labels":{"fr":"Moyenner les deux autonomies pour déclarer la cible satisfaite dans les deux cas.","en":"Average both ranges to declare that both scenarios meet the target."}},{"id":"exam_01_A_case2_decision_c2","position":2,"labels":{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity."}},{"id":"exam_01_A_case2_decision_c3","position":3,"labels":{"fr":"Utiliser l’énergie brute pour tous les scénarios, puisque la fenêtre ne change que la recharge.","en":"Use gross energy in every scenario because the window only affects charging."}}],"settings":{},"blockId":"exam_01_A_case2"},{"id":"exam_01_A_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1225 kg ; vitesse 52 km/h ; délai 0,30 s ; décélération demandée 5 m/s² ; cas sec μ = 0,80 ; cas faible adhérence μ = 0,35 ; h = 0,50 m ; L = 2,50 m ; route plane.\n\nCalcule la distance d’arrêt à sec.","en":"Mass 1225 kg; speed 52 km/h; delay 0.30 s; requested deceleration 5 m/s²; dry μ = 0.80; low-grip μ = 0.35; h = 0.50 m; L = 2.50 m; level road.\n\nCalculate dry stopping distance."},"choices":[],"settings":{"unit":"m","toleranceLabel":{"fr":"Tolérance absolue ±0.0755926 m.","en":"Absolute tolerance ±0.0755926 m."}},"blockId":"exam_01_A_case3"},{"id":"exam_01_A_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1225 kg ; vitesse 52 km/h ; délai 0,30 s ; décélération demandée 5 m/s² ; cas sec μ = 0,80 ; cas faible adhérence μ = 0,35 ; h = 0,50 m ; L = 2,50 m ; route plane.\n\nCalcule la distance en faible adhérence.","en":"Mass 1225 kg; speed 52 km/h; delay 0.30 s; requested deceleration 5 m/s²; dry μ = 0.80; low-grip μ = 0.35; h = 0.50 m; L = 2.50 m; level road.\n\nCalculate low-grip stopping distance."},"choices":[],"settings":{"unit":"m","toleranceLabel":{"fr":"Tolérance absolue ±0.10415 m.","en":"Absolute tolerance ±0.10415 m."}},"blockId":"exam_01_A_case3"},{"id":"exam_01_A_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1225 kg ; vitesse 52 km/h ; délai 0,30 s ; décélération demandée 5 m/s² ; cas sec μ = 0,80 ; cas faible adhérence μ = 0,35 ; h = 0,50 m ; L = 2,50 m ; route plane.\n\nCalcule le transfert de charge à 5 m/s².","en":"Mass 1225 kg; speed 52 km/h; delay 0.30 s; requested deceleration 5 m/s²; dry μ = 0.80; low-grip μ = 0.35; h = 0.50 m; L = 2.50 m; level road.\n\nCalculate load transfer at 5 m/s²."},"choices":[],"settings":{"unit":"N","toleranceLabel":{"fr":"Tolérance absolue ±3.675 N.","en":"Absolute tolerance ±3.675 N."}},"blockId":"exam_01_A_case3"},{"id":"exam_01_A_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1225 kg ; vitesse 52 km/h ; délai 0,30 s ; décélération demandée 5 m/s² ; cas sec μ = 0,80 ; cas faible adhérence μ = 0,35 ; h = 0,50 m ; L = 2,50 m ; route plane.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Mass 1225 kg; speed 52 km/h; delay 0.30 s; requested deceleration 5 m/s²; dry μ = 0.80; low-grip μ = 0.35; h = 0.50 m; L = 2.50 m; level road.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_01_A_case3_decision_c1","position":1,"labels":{"fr":"Borner la décélération par l’adhérence et garder deux scénarios, puis examiner la rampe de freinage.","en":"Bound deceleration by adhesion, retain both scenarios and examine brake build-up."}},{"id":"exam_01_A_case3_decision_c2","position":2,"labels":{"fr":"Conserver 5 m/s² sur faible adhérence parce que le calculateur le demande.","en":"Keep 5 m/s² on low grip because the controller requests it."}},{"id":"exam_01_A_case3_decision_c3","position":3,"labels":{"fr":"Retirer la distance de délai parce que le véhicule est déjà équipé de freins.","en":"Remove delay distance because brakes are installed."}}],"settings":{},"blockId":"exam_01_A_case3"}]'::jsonb,'{"exam_01_A_case1_q1":{"answer":{"value":27.916375698304435,"unit":"kW","abs_tolerance":0.0837491270949133},"rubric":{},"explanation":{"fr":"1. v = 20.5556 m/s ; θ = 0.0798 rad.\n2. Roulement 146.6814 N ; aéro 165.6321 N ; pente 977.8758 N.\n3. Total 1290.1893 N ; roues 26.5206 kW.\n4. Machine 27.9164 kW ; batterie 30.2673 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6309.3567 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 20.5556 m/s; θ = 0.0798 rad.\n2. Rolling 146.6814 N; drag 165.6321 N; grade 977.8758 N.\n3. Total 1290.1893 N; wheel power 26.5206 kW.\n4. Machine 27.9164 kW; battery 30.2673 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6309.3567 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}},"exam_01_A_case1_q2":{"answer":{"value":30.267285459321347,"unit":"kW","abs_tolerance":0.09080185637796404},"rubric":{},"explanation":{"fr":"1. v = 20.5556 m/s ; θ = 0.0798 rad.\n2. Roulement 146.6814 N ; aéro 165.6321 N ; pente 977.8758 N.\n3. Total 1290.1893 N ; roues 26.5206 kW.\n4. Machine 27.9164 kW ; batterie 30.2673 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6309.3567 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 20.5556 m/s; θ = 0.0798 rad.\n2. Rolling 146.6814 N; drag 165.6321 N; grade 977.8758 N.\n3. Total 1290.1893 N; wheel power 26.5206 kW.\n4. Machine 27.9164 kW; battery 30.2673 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6309.3567 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}},"exam_01_A_case1_q3":{"answer":{"value":6309.356672571565,"unit":"tr/min","abs_tolerance":18.928070017714695},"rubric":{},"explanation":{"fr":"1. v = 20.5556 m/s ; θ = 0.0798 rad.\n2. Roulement 146.6814 N ; aéro 165.6321 N ; pente 977.8758 N.\n3. Total 1290.1893 N ; roues 26.5206 kW.\n4. Machine 27.9164 kW ; batterie 30.2673 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6309.3567 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 20.5556 m/s; θ = 0.0798 rad.\n2. Rolling 146.6814 N; drag 165.6321 N; grade 977.8758 N.\n3. Total 1290.1893 N; wheel power 26.5206 kW.\n4. Machine 27.9164 kW; battery 30.2673 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6309.3567 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}},"exam_01_A_case1_decision":{"answer":{"choice_id":"exam_01_A_case1_decision_c3"},"rubric":{},"explanation":{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur. Rendements constants, inerties tournantes et transitoires omis.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection. Constant efficiencies; rotating inertia and transients omitted."}},"exam_01_A_case2_q1":{"answer":{"value":150.3030303030303,"unit":"km","abs_tolerance":0.4509090909090909},"rubric":{},"explanation":{"fr":"1. Énergie utile : 31 × 0,80 = 24.8 kWh.\n2. Convertir en Wh : 24800 Wh.\n3. Autonomie nominale : 24800 / 165 = 150.303 km.\n4. Autonomie dégradée : 24800 / 185 = 134.0541 km.\n5. Besoin utile pour 150 km dégradés : 150 × 185/1000 = 27.75 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 31 × 0.80 = 24.8 kWh.\n2. Convert to Wh: 24800 Wh.\n3. Nominal range: 24800 / 165 = 150.303 km.\n4. Degraded range: 24800 / 185 = 134.0541 km.\n5. Usable energy for 150 degraded kilometres: 150 × 185/1000 = 27.75 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}},"exam_01_A_case2_q2":{"answer":{"value":134.05405405405406,"unit":"km","abs_tolerance":0.4021621621621622},"rubric":{},"explanation":{"fr":"1. Énergie utile : 31 × 0,80 = 24.8 kWh.\n2. Convertir en Wh : 24800 Wh.\n3. Autonomie nominale : 24800 / 165 = 150.303 km.\n4. Autonomie dégradée : 24800 / 185 = 134.0541 km.\n5. Besoin utile pour 150 km dégradés : 150 × 185/1000 = 27.75 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 31 × 0.80 = 24.8 kWh.\n2. Convert to Wh: 24800 Wh.\n3. Nominal range: 24800 / 165 = 150.303 km.\n4. Degraded range: 24800 / 185 = 134.0541 km.\n5. Usable energy for 150 degraded kilometres: 150 × 185/1000 = 27.75 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}},"exam_01_A_case2_q3":{"answer":{"value":27.75,"unit":"kWh","abs_tolerance":0.08325},"rubric":{},"explanation":{"fr":"1. Énergie utile : 31 × 0,80 = 24.8 kWh.\n2. Convertir en Wh : 24800 Wh.\n3. Autonomie nominale : 24800 / 165 = 150.303 km.\n4. Autonomie dégradée : 24800 / 185 = 134.0541 km.\n5. Besoin utile pour 150 km dégradés : 150 × 185/1000 = 27.75 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 31 × 0.80 = 24.8 kWh.\n2. Convert to Wh: 24800 Wh.\n3. Nominal range: 24800 / 165 = 150.303 km.\n4. Degraded range: 24800 / 185 = 134.0541 km.\n5. Usable energy for 150 degraded kilometres: 150 × 185/1000 = 27.75 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}},"exam_01_A_case2_decision":{"answer":{"choice_id":"exam_01_A_case2_decision_c2"},"rubric":{},"explanation":{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie. La consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity. Consumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}},"exam_01_A_case3_q1":{"answer":{"value":25.197530864197528,"unit":"m","abs_tolerance":0.07559259259259259},"rubric":{},"explanation":{"fr":"1. v = 14.4444 m/s.\n2. À sec μg = 7,848 m/s² : a = 5 ; d = 25.1975 m.\n3. Faible adhérence μg = 3,4335 m/s² : d = 34.7166 m.\n4. Transfert à a = 5 : 1225 N de l’arrière vers l’avant.\n5. Le verdict de chaque cible reste lié à son coefficient μ et à sa vitesse.\n\nDécélération constante après délai, sans pente ni variation de μ.","en":"1. v = 14.4444 m/s.\n2. Dry μg = 7.848 m/s²: a = 5; d = 25.1975 m.\n3. Low-grip μg = 3.4335 m/s²: d = 34.7166 m.\n4. Load transfer at a = 5: 1225 N rear to front.\n5. Each target verdict retains its own μ and speed conditions.\n\nConstant deceleration after delay, no grade or varying μ."}},"exam_01_A_case3_q2":{"answer":{"value":34.716612102612785,"unit":"m","abs_tolerance":0.10414983630783836},"rubric":{},"explanation":{"fr":"1. v = 14.4444 m/s.\n2. À sec μg = 7,848 m/s² : a = 5 ; d = 25.1975 m.\n3. Faible adhérence μg = 3,4335 m/s² : d = 34.7166 m.\n4. Transfert à a = 5 : 1225 N de l’arrière vers l’avant.\n5. Le verdict de chaque cible reste lié à son coefficient μ et à sa vitesse.\n\nDécélération constante après délai, sans pente ni variation de μ.","en":"1. v = 14.4444 m/s.\n2. Dry μg = 7.848 m/s²: a = 5; d = 25.1975 m.\n3. Low-grip μg = 3.4335 m/s²: d = 34.7166 m.\n4. Load transfer at a = 5: 1225 N rear to front.\n5. Each target verdict retains its own μ and speed conditions.\n\nConstant deceleration after delay, no grade or varying μ."}},"exam_01_A_case3_q3":{"answer":{"value":1225.0,"unit":"N","abs_tolerance":3.6750000000000003},"rubric":{},"explanation":{"fr":"1. v = 14.4444 m/s.\n2. À sec μg = 7,848 m/s² : a = 5 ; d = 25.1975 m.\n3. Faible adhérence μg = 3,4335 m/s² : d = 34.7166 m.\n4. Transfert à a = 5 : 1225 N de l’arrière vers l’avant.\n5. Le verdict de chaque cible reste lié à son coefficient μ et à sa vitesse.\n\nDécélération constante après délai, sans pente ni variation de μ.","en":"1. v = 14.4444 m/s.\n2. Dry μg = 7.848 m/s²: a = 5; d = 25.1975 m.\n3. Low-grip μg = 3.4335 m/s²: d = 34.7166 m.\n4. Load transfer at a = 5: 1225 N rear to front.\n5. Each target verdict retains its own μ and speed conditions.\n\nConstant deceleration after delay, no grade or varying μ."}},"exam_01_A_case3_decision":{"answer":{"choice_id":"exam_01_A_case3_decision_c1"},"rubric":{},"explanation":{"fr":"Borner la décélération par l’adhérence et garder deux scénarios, puis examiner la rampe de freinage. Décélération constante après délai, sans pente ni variation de μ.","en":"Bound deceleration by adhesion, retain both scenarios and examine brake build-up. Constant deceleration after delay, no grade or varying μ."}}}'::jsonb) ON CONFLICT DO NOTHING;
