INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_02','A','[{"id":"exam_02_A_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 85 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule le délai de chaîne.","en":"Camera 85 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate chain delay."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.825 ms.","en":"Absolute tolerance ±0.825 ms."}},"blockId":"exam_02_A_case1"},{"id":"exam_02_A_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 85 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule la marge nominale.","en":"Camera 85 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate nominal margin."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.075 ms.","en":"Absolute tolerance ±0.075 ms."}},"blockId":"exam_02_A_case1"},{"id":"exam_02_A_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 85 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule le budget fusion maximal.","en":"Camera 85 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate maximum fusion budget."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.15 ms.","en":"Absolute tolerance ±0.15 ms."}},"blockId":"exam_02_A_case1"},{"id":"exam_02_A_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 85 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Camera 85 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_02_A_case1_decision_c1","position":1,"labels":{"fr":"Utiliser seulement le maximum de tous les temps, y compris ceux en série.","en":"Use only the maximum of all delays, including sequential stages."}},{"id":"exam_02_A_case1_decision_c2","position":2,"labels":{"fr":"Définir endpoints et pire cas avant de considérer la marge nominale comme une preuve de deadline.","en":"Define endpoints and worst case before treating nominal margin as deadline evidence."}},{"id":"exam_02_A_case1_decision_c3","position":3,"labels":{"fr":"Additionner caméra et radar même si les acquisitions sont parallèles dans le modèle donné.","en":"Add camera and radar times even though acquisition is parallel in this model."}}],"settings":{},"blockId":"exam_02_A_case1"},{"id":"exam_02_A_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Demande de couple 12 N·m ; codage entier non signé uint16, résolution 0,1 N·m/bit, offset zéro, little-endian. Le décodage inversé utilise aussi uint16.\n\nCalcule la valeur entière brute.","en":"Torque demand 12 N·m; unsigned uint16 integer, resolution 0.1 N·m/bit, zero offset, little-endian. Reversed decoding also uses uint16.\n\nCalculate raw integer value."},"choices":[],"settings":{"unit":"code","toleranceLabel":{"fr":"Tolérance absolue ±0.01 code.","en":"Absolute tolerance ±0.01 code."}},"blockId":"exam_02_A_case2"},{"id":"exam_02_A_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Demande de couple 12 N·m ; codage entier non signé uint16, résolution 0,1 N·m/bit, offset zéro, little-endian. Le décodage inversé utilise aussi uint16.\n\nCalcule le couple obtenu par lecture inversée.","en":"Torque demand 12 N·m; unsigned uint16 integer, resolution 0.1 N·m/bit, zero offset, little-endian. Reversed decoding also uses uint16.\n\nCalculate torque after reversed-byte decoding."},"choices":[],"settings":{"unit":"N·m","toleranceLabel":{"fr":"Tolérance absolue ±9.216 N·m.","en":"Absolute tolerance ±9.216 N·m."}},"blockId":"exam_02_A_case2"},{"id":"exam_02_A_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Demande de couple 12 N·m ; codage entier non signé uint16, résolution 0,1 N·m/bit, offset zéro, little-endian. Le décodage inversé utilise aussi uint16.\n\nDonne la valeur décimale du premier octet transmis.","en":"Torque demand 12 N·m; unsigned uint16 integer, resolution 0.1 N·m/bit, zero offset, little-endian. Reversed decoding also uses uint16.\n\nGive the decimal value of the first transmitted byte."},"choices":[],"settings":{"unit":"octet","toleranceLabel":{"fr":"Tolérance absolue ±0.01 octet.","en":"Absolute tolerance ±0.01 octet."}},"blockId":"exam_02_A_case2"},{"id":"exam_02_A_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Demande de couple 12 N·m ; codage entier non signé uint16, résolution 0,1 N·m/bit, offset zéro, little-endian. Le décodage inversé utilise aussi uint16.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Torque demand 12 N·m; unsigned uint16 integer, resolution 0.1 N·m/bit, zero offset, little-endian. Reversed decoding also uses uint16.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_02_A_case2_decision_c1","position":1,"labels":{"fr":"Fixer et tester unité, signe, ordre des octets, domaine et réaction au défaut dans l’ICD.","en":"Specify and test unit, sign, byte order, range and fault response in the ICD."}},{"id":"exam_02_A_case2_decision_c2","position":2,"labels":{"fr":"Corriger par un gain de calibration sans modifier le contrat d’interface ni tester les limites.","en":"Apply a calibration gain without fixing the interface contract or testing limits."}},{"id":"exam_02_A_case2_decision_c3","position":3,"labels":{"fr":"Accepter l’échange parce que les deux équipements sont conformes à leurs spécifications locales.","en":"Accept the exchange because both devices meet their local specifications."}}],"settings":{},"blockId":"exam_02_A_case2"},{"id":"exam_02_A_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"38 exigences applicables ; 35 ont une preuve approuvée ; 28 essais exécutés, dont 26 réussis et 2 échoués. Un échec est critique. Les deux populations sont distinctes.\n\nCalcule la couverture des exigences.","en":"38 applicable requirements; 35 have approved evidence; 28 tests executed, 26 passed and 2 failed. One failure is critical. The populations are distinct.\n\nCalculate requirement coverage."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.276316 %.","en":"Absolute tolerance ±0.276316 %."}},"blockId":"exam_02_A_case3"},{"id":"exam_02_A_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"38 exigences applicables ; 35 ont une preuve approuvée ; 28 essais exécutés, dont 26 réussis et 2 échoués. Un échec est critique. Les deux populations sont distinctes.\n\nCalcule le taux de réussite des essais exécutés.","en":"38 applicable requirements; 35 have approved evidence; 28 tests executed, 26 passed and 2 failed. One failure is critical. The populations are distinct.\n\nCalculate executed-test pass rate."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.278571 %.","en":"Absolute tolerance ±0.278571 %."}},"blockId":"exam_02_A_case3"},{"id":"exam_02_A_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"38 exigences applicables ; 35 ont une preuve approuvée ; 28 essais exécutés, dont 26 réussis et 2 échoués. Un échec est critique. Les deux populations sont distinctes.\n\nCompte les exigences sans preuve approuvée.","en":"38 applicable requirements; 35 have approved evidence; 28 tests executed, 26 passed and 2 failed. One failure is critical. The populations are distinct.\n\nCount requirements without approved evidence."},"choices":[],"settings":{"unit":"exigences","toleranceLabel":{"fr":"Tolérance absolue ±0.01 exigences.","en":"Absolute tolerance ±0.01 exigences."}},"blockId":"exam_02_A_case3"},{"id":"exam_02_A_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"38 exigences applicables ; 35 ont une preuve approuvée ; 28 essais exécutés, dont 26 réussis et 2 échoués. Un échec est critique. Les deux populations sont distinctes.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"38 applicable requirements; 35 have approved evidence; 28 tests executed, 26 passed and 2 failed. One failure is critical. The populations are distinct.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_02_A_case3_decision_c1","position":1,"labels":{"fr":"Moyenner les deux pourcentages pour annoncer une conformité véhicule unique.","en":"Average the percentages to announce a single vehicle-compliance rate."}},{"id":"exam_02_A_case3_decision_c2","position":2,"labels":{"fr":"Reclasser les deux échecs comme non exécutés pour améliorer le taux.","en":"Reclassify failures as not executed to improve the rate."}},{"id":"exam_02_A_case3_decision_c3","position":3,"labels":{"fr":"Garder visibles l’échec critique, les exigences sans preuve et les configurations ; décider un plan de fermeture.","en":"Keep the critical failure, unproven requirements and configurations visible; decide a closure plan."}}],"settings":{},"blockId":"exam_02_A_case3"}]'::jsonb,'{"exam_02_A_case1_q1":{"answer":{"value":275,"unit":"ms","abs_tolerance":0.8250000000000001},"rubric":{},"explanation":{"fr":"1. Acquisition limitante : max(85,40) = 85 ms.\n2. Chaîne = 85+20+25+15+10+120 = 275 ms.\n3. Marge nominale = 300−275 = 25 ms.\n4. Budget fusion maximal, autres temps inchangés : 50 ms.\n5. Un délai de file ou une donnée déjà âgée exige une extension du modèle.\n\nPas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"1. Limiting acquisition: max(85,40) = 85 ms.\n2. Chain = 85+20+25+15+10+120 = 275 ms.\n3. Nominal margin = 300−275 = 25 ms.\n4. Maximum fusion budget with other times fixed: 50 ms.\n5. Queue delay or already-old data requires extending the model.\n\nNo jitter, queues or asynchronous effects modelled; educational target only."}},"exam_02_A_case1_q2":{"answer":{"value":25,"unit":"ms","abs_tolerance":0.075},"rubric":{},"explanation":{"fr":"1. Acquisition limitante : max(85,40) = 85 ms.\n2. Chaîne = 85+20+25+15+10+120 = 275 ms.\n3. Marge nominale = 300−275 = 25 ms.\n4. Budget fusion maximal, autres temps inchangés : 50 ms.\n5. Un délai de file ou une donnée déjà âgée exige une extension du modèle.\n\nPas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"1. Limiting acquisition: max(85,40) = 85 ms.\n2. Chain = 85+20+25+15+10+120 = 275 ms.\n3. Nominal margin = 300−275 = 25 ms.\n4. Maximum fusion budget with other times fixed: 50 ms.\n5. Queue delay or already-old data requires extending the model.\n\nNo jitter, queues or asynchronous effects modelled; educational target only."}},"exam_02_A_case1_q3":{"answer":{"value":50,"unit":"ms","abs_tolerance":0.15},"rubric":{},"explanation":{"fr":"1. Acquisition limitante : max(85,40) = 85 ms.\n2. Chaîne = 85+20+25+15+10+120 = 275 ms.\n3. Marge nominale = 300−275 = 25 ms.\n4. Budget fusion maximal, autres temps inchangés : 50 ms.\n5. Un délai de file ou une donnée déjà âgée exige une extension du modèle.\n\nPas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"1. Limiting acquisition: max(85,40) = 85 ms.\n2. Chain = 85+20+25+15+10+120 = 275 ms.\n3. Nominal margin = 300−275 = 25 ms.\n4. Maximum fusion budget with other times fixed: 50 ms.\n5. Queue delay or already-old data requires extending the model.\n\nNo jitter, queues or asynchronous effects modelled; educational target only."}},"exam_02_A_case1_decision":{"answer":{"choice_id":"exam_02_A_case1_decision_c2"},"rubric":{},"explanation":{"fr":"Définir endpoints et pire cas avant de considérer la marge nominale comme une preuve de deadline. Pas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"Define endpoints and worst case before treating nominal margin as deadline evidence. No jitter, queues or asynchronous effects modelled; educational target only."}},"exam_02_A_case2_q1":{"answer":{"value":120,"unit":"code","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Valeur entière = 12/0,1 = 120.\n2. Octets décimaux little-endian : [120, 0] ; hex : [78, 00].\n3. Lecture inversée : 256×120+0 = 30720 pas ; couple apparent 3072 N·m.\n4. Un aller-retour indépendant vérifie le codage ; domaine, validité et timeout demandent d’autres tests.\n\nLe contrat de cet exercice est uint16. Domaine, saturation et validité demandent des tests supplémentaires.","en":"1. Integer = 12/0.1 = 120.\n2. Little-endian decimal bytes: [120, 0]; hex: [78, 00].\n3. Reversed decoding: 256×120+0 = 30720 counts; apparent torque 3072 N·m.\n4. An independent round trip checks encoding; range, validity and timeout require additional tests.\n\nThis exercise uses uint16. Range, saturation and validity need additional tests."}},"exam_02_A_case2_q2":{"answer":{"value":3072.0,"unit":"N·m","abs_tolerance":9.216000000000001},"rubric":{},"explanation":{"fr":"1. Valeur entière = 12/0,1 = 120.\n2. Octets décimaux little-endian : [120, 0] ; hex : [78, 00].\n3. Lecture inversée : 256×120+0 = 30720 pas ; couple apparent 3072 N·m.\n4. Un aller-retour indépendant vérifie le codage ; domaine, validité et timeout demandent d’autres tests.\n\nLe contrat de cet exercice est uint16. Domaine, saturation et validité demandent des tests supplémentaires.","en":"1. Integer = 12/0.1 = 120.\n2. Little-endian decimal bytes: [120, 0]; hex: [78, 00].\n3. Reversed decoding: 256×120+0 = 30720 counts; apparent torque 3072 N·m.\n4. An independent round trip checks encoding; range, validity and timeout require additional tests.\n\nThis exercise uses uint16. Range, saturation and validity need additional tests."}},"exam_02_A_case2_q3":{"answer":{"value":120,"unit":"octet","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Valeur entière = 12/0,1 = 120.\n2. Octets décimaux little-endian : [120, 0] ; hex : [78, 00].\n3. Lecture inversée : 256×120+0 = 30720 pas ; couple apparent 3072 N·m.\n4. Un aller-retour indépendant vérifie le codage ; domaine, validité et timeout demandent d’autres tests.\n\nLe contrat de cet exercice est uint16. Domaine, saturation et validité demandent des tests supplémentaires.","en":"1. Integer = 12/0.1 = 120.\n2. Little-endian decimal bytes: [120, 0]; hex: [78, 00].\n3. Reversed decoding: 256×120+0 = 30720 counts; apparent torque 3072 N·m.\n4. An independent round trip checks encoding; range, validity and timeout require additional tests.\n\nThis exercise uses uint16. Range, saturation and validity need additional tests."}},"exam_02_A_case2_decision":{"answer":{"choice_id":"exam_02_A_case2_decision_c1"},"rubric":{},"explanation":{"fr":"Fixer et tester unité, signe, ordre des octets, domaine et réaction au défaut dans l’ICD. Le contrat de cet exercice est uint16. Domaine, saturation et validité demandent des tests supplémentaires.","en":"Specify and test unit, sign, byte order, range and fault response in the ICD. This exercise uses uint16. Range, saturation and validity need additional tests."}},"exam_02_A_case3_q1":{"answer":{"value":92.10526315789474,"unit":"%","abs_tolerance":0.27631578947368424},"rubric":{},"explanation":{"fr":"1. Couverture exigences = 35/38×100 = 92.1053 %.\n2. Réussite essais = 26/28×100 = 92.8571 %.\n3. Exigences sans preuve approuvée = 3.\n4. Le dénominateur des essais ne remplace pas celui des exigences. L’échec critique doit être traité explicitement, quel que soit le pourcentage.\n\nLes comptes sont fictifs et n’établissent pas la qualité des méthodes de preuve.","en":"1. Requirement coverage = 35/38×100 = 92.1053%.\n2. Test pass rate = 26/28×100 = 92.8571%.\n3. Requirements without approved evidence = 3.\n4. Test and requirement denominators are not interchangeable. Address the critical failure explicitly regardless of percentage.\n\nCounts are fictional and do not establish evidence-method quality."}},"exam_02_A_case3_q2":{"answer":{"value":92.85714285714286,"unit":"%","abs_tolerance":0.2785714285714286},"rubric":{},"explanation":{"fr":"1. Couverture exigences = 35/38×100 = 92.1053 %.\n2. Réussite essais = 26/28×100 = 92.8571 %.\n3. Exigences sans preuve approuvée = 3.\n4. Le dénominateur des essais ne remplace pas celui des exigences. L’échec critique doit être traité explicitement, quel que soit le pourcentage.\n\nLes comptes sont fictifs et n’établissent pas la qualité des méthodes de preuve.","en":"1. Requirement coverage = 35/38×100 = 92.1053%.\n2. Test pass rate = 26/28×100 = 92.8571%.\n3. Requirements without approved evidence = 3.\n4. Test and requirement denominators are not interchangeable. Address the critical failure explicitly regardless of percentage.\n\nCounts are fictional and do not establish evidence-method quality."}},"exam_02_A_case3_q3":{"answer":{"value":3,"unit":"exigences","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Couverture exigences = 35/38×100 = 92.1053 %.\n2. Réussite essais = 26/28×100 = 92.8571 %.\n3. Exigences sans preuve approuvée = 3.\n4. Le dénominateur des essais ne remplace pas celui des exigences. L’échec critique doit être traité explicitement, quel que soit le pourcentage.\n\nLes comptes sont fictifs et n’établissent pas la qualité des méthodes de preuve.","en":"1. Requirement coverage = 35/38×100 = 92.1053%.\n2. Test pass rate = 26/28×100 = 92.8571%.\n3. Requirements without approved evidence = 3.\n4. Test and requirement denominators are not interchangeable. Address the critical failure explicitly regardless of percentage.\n\nCounts are fictional and do not establish evidence-method quality."}},"exam_02_A_case3_decision":{"answer":{"choice_id":"exam_02_A_case3_decision_c3"},"rubric":{},"explanation":{"fr":"Garder visibles l’échec critique, les exigences sans preuve et les configurations ; décider un plan de fermeture. Les comptes sont fictifs et n’établissent pas la qualité des méthodes de preuve.","en":"Keep the critical failure, unproven requirements and configurations visible; decide a closure plan. Counts are fictional and do not establish evidence-method quality."}}}'::jsonb) ON CONFLICT DO NOTHING;
