INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_03','A','[{"id":"exam_03_A_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Choix indépendants avant règles : batteries 2, logiciels 3, marchés 3, options de capteur 2. Les règles excluent 3 combinaisons distinctes. 30 configurations admissibles ont été testées.\n\nCompte les combinaisons candidates.","en":"Independent choices before rules: batteries 2, software versions 3, markets 3, sensor options 2. Rules exclude 3 distinct combinations. 30 admissible configurations have been tested.\n\nCount candidate combinations."},"choices":[],"settings":{"unit":"configurations","toleranceLabel":{"fr":"Tolérance absolue ±0.01 configurations.","en":"Absolute tolerance ±0.01 configurations."}},"blockId":"exam_03_A_case1"},{"id":"exam_03_A_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Choix indépendants avant règles : batteries 2, logiciels 3, marchés 3, options de capteur 2. Les règles excluent 3 combinaisons distinctes. 30 configurations admissibles ont été testées.\n\nCompte les configurations admissibles.","en":"Independent choices before rules: batteries 2, software versions 3, markets 3, sensor options 2. Rules exclude 3 distinct combinations. 30 admissible configurations have been tested.\n\nCount admissible configurations."},"choices":[],"settings":{"unit":"configurations","toleranceLabel":{"fr":"Tolérance absolue ±0.01 configurations.","en":"Absolute tolerance ±0.01 configurations."}},"blockId":"exam_03_A_case1"},{"id":"exam_03_A_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Choix indépendants avant règles : batteries 2, logiciels 3, marchés 3, options de capteur 2. Les règles excluent 3 combinaisons distinctes. 30 configurations admissibles ont été testées.\n\nCalcule la couverture des configurations.","en":"Independent choices before rules: batteries 2, software versions 3, markets 3, sensor options 2. Rules exclude 3 distinct combinations. 30 admissible configurations have been tested.\n\nCalculate configuration coverage."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.272727 %.","en":"Absolute tolerance ±0.272727 %."}},"blockId":"exam_03_A_case1"},{"id":"exam_03_A_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Choix indépendants avant règles : batteries 2, logiciels 3, marchés 3, options de capteur 2. Les règles excluent 3 combinaisons distinctes. 30 configurations admissibles ont été testées.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Independent choices before rules: batteries 2, software versions 3, markets 3, sensor options 2. Rules exclude 3 distinct combinations. 30 admissible configurations have been tested.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_03_A_case1_decision_c1","position":1,"labels":{"fr":"Versionner les règles d’effectivité et associer chaque résultat à la combinaison réellement testée.","en":"Version effectivity rules and connect results to the configuration actually tested."}},{"id":"exam_03_A_case1_decision_c2","position":2,"labels":{"fr":"Utiliser seulement la version logicielle comme preuve de configuration complète.","en":"Use software version alone as complete configuration evidence."}},{"id":"exam_03_A_case1_decision_c3","position":3,"labels":{"fr":"Soustraire chaque règle indépendamment même si plusieurs excluent la même combinaison.","en":"Subtract each rule independently even when several exclude the same combination."}}],"settings":{},"blockId":"exam_03_A_case1"},{"id":"exam_03_A_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1200 véhicules ; surcoût récurrent 16 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule le coût total du changement.","en":"Effective population 1200 vehicles; recurring increase €16/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate total change cost."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±141.6 €.","en":"Absolute tolerance ±141.6 €."}},"blockId":"exam_03_A_case2"},{"id":"exam_03_A_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1200 véhicules ; surcoût récurrent 16 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule l’impact moyen par véhicule effectif.","en":"Effective population 1200 vehicles; recurring increase €16/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate average cost per affected vehicle."},"choices":[],"settings":{"unit":"€/véhicule","toleranceLabel":{"fr":"Tolérance absolue ±0.118 €/véhicule.","en":"Absolute tolerance ±0.118 €/véhicule."}},"blockId":"exam_03_A_case2"},{"id":"exam_03_A_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1200 véhicules ; surcoût récurrent 16 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule la seule composante récurrente totale.","en":"Effective population 1200 vehicles; recurring increase €16/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate total recurring component only."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±57.6 €.","en":"Absolute tolerance ±57.6 €."}},"blockId":"exam_03_A_case2"},{"id":"exam_03_A_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1200 véhicules ; surcoût récurrent 16 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Effective population 1200 vehicles; recurring increase €16/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_03_A_case2_decision_c1","position":1,"labels":{"fr":"Clôturer dès que la commande fournisseur est passée, sans vérification.","en":"Close when the supplier order is placed, without verification."}},{"id":"exam_03_A_case2_decision_c2","position":2,"labels":{"fr":"Limiter le coût au surcoût unitaire et ignorer qualification et stock.","en":"Count only unit delta and ignore qualification and inventory."}},{"id":"exam_03_A_case2_decision_c3","position":3,"labels":{"fr":"Décider après analyse technique, puis fixer effectivité, non-régression et fermeture documentée.","en":"Decide after technical analysis, then set effectivity, regression evidence and documented closure."}}],"settings":{},"blockId":"exam_03_A_case2"},{"id":"exam_03_A_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"1000 unités entrantes ; 920 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nCalcule le rendement de premier passage.","en":"1000 incoming units; 920 good without rework; 50 additional units recovered by rework; remainder scrapped. Groups are disjoint.\n\nCalculate first-pass yield."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.276 %.","en":"Absolute tolerance ±0.276 %."}},"blockId":"exam_03_A_case3"},{"id":"exam_03_A_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"1000 unités entrantes ; 920 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nCalcule le rendement final.","en":"1000 incoming units; 920 good without rework; 50 additional units recovered by rework; remainder scrapped. Groups are disjoint.\n\nCalculate final yield."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.291 %.","en":"Absolute tolerance ±0.291 %."}},"blockId":"exam_03_A_case3"},{"id":"exam_03_A_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"1000 unités entrantes ; 920 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nCompte les unités rebutées.","en":"1000 incoming units; 920 good without rework; 50 additional units recovered by rework; remainder scrapped. Groups are disjoint.\n\nCount scrapped units."},"choices":[],"settings":{"unit":"unités","toleranceLabel":{"fr":"Tolérance absolue ±0.01 unités.","en":"Absolute tolerance ±0.01 unités."}},"blockId":"exam_03_A_case3"},{"id":"exam_03_A_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"1000 unités entrantes ; 920 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"1000 incoming units; 920 good without rework; 50 additional units recovered by rework; remainder scrapped. Groups are disjoint.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_03_A_case3_decision_c1","position":1,"labels":{"fr":"Déclarer la production maîtrisée parce qu’une unité prototype a réussi.","en":"Declare production controlled because one prototype passed."}},{"id":"exam_03_A_case3_decision_c2","position":2,"labels":{"fr":"Suivre premier passage, retouches et rebuts séparément, puis démontrer une cause avant correction.","en":"Track first pass, rework and scrap separately, then demonstrate a cause before correcting."}},{"id":"exam_03_A_case3_decision_c3","position":3,"labels":{"fr":"Annoncer le rendement final comme FPY et supprimer les retouches du dashboard.","en":"Call final yield FPY and remove rework from the dashboard."}}],"settings":{},"blockId":"exam_03_A_case3"}]'::jsonb,'{"exam_03_A_case1_q1":{"answer":{"value":36,"unit":"configurations","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Produit cartésien = 2×3×3×2 = 36.\n2. Admissibles = 36−3 = 33.\n3. Couverture configuration = 30/33×100 = 90.9091 %.\n4. Les exclusions sont distinctes ; s’il y avait recouvrement, il faudrait dédupliquer avant soustraction.\n\nUne couverture combinatoire ne prouve pas que les scénarios de défaillance sont couverts.","en":"1. Cartesian product = 2×3×3×2 = 36.\n2. Admissible = 36−3 = 33.\n3. Configuration coverage = 30/33×100 = 90.9091%.\n4. Exclusions are distinct; overlapping exclusions would need deduplication.\n\nCombinatorial coverage does not establish failure-scenario coverage."}},"exam_03_A_case1_q2":{"answer":{"value":33,"unit":"configurations","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Produit cartésien = 2×3×3×2 = 36.\n2. Admissibles = 36−3 = 33.\n3. Couverture configuration = 30/33×100 = 90.9091 %.\n4. Les exclusions sont distinctes ; s’il y avait recouvrement, il faudrait dédupliquer avant soustraction.\n\nUne couverture combinatoire ne prouve pas que les scénarios de défaillance sont couverts.","en":"1. Cartesian product = 2×3×3×2 = 36.\n2. Admissible = 36−3 = 33.\n3. Configuration coverage = 30/33×100 = 90.9091%.\n4. Exclusions are distinct; overlapping exclusions would need deduplication.\n\nCombinatorial coverage does not establish failure-scenario coverage."}},"exam_03_A_case1_q3":{"answer":{"value":90.9090909090909,"unit":"%","abs_tolerance":0.2727272727272727},"rubric":{},"explanation":{"fr":"1. Produit cartésien = 2×3×3×2 = 36.\n2. Admissibles = 36−3 = 33.\n3. Couverture configuration = 30/33×100 = 90.9091 %.\n4. Les exclusions sont distinctes ; s’il y avait recouvrement, il faudrait dédupliquer avant soustraction.\n\nUne couverture combinatoire ne prouve pas que les scénarios de défaillance sont couverts.","en":"1. Cartesian product = 2×3×3×2 = 36.\n2. Admissible = 36−3 = 33.\n3. Configuration coverage = 30/33×100 = 90.9091%.\n4. Exclusions are distinct; overlapping exclusions would need deduplication.\n\nCombinatorial coverage does not establish failure-scenario coverage."}},"exam_03_A_case1_decision":{"answer":{"choice_id":"exam_03_A_case1_decision_c1"},"rubric":{},"explanation":{"fr":"Versionner les règles d’effectivité et associer chaque résultat à la combinaison réellement testée. Une couverture combinatoire ne prouve pas que les scénarios de défaillance sont couverts.","en":"Version effectivity rules and connect results to the configuration actually tested. Combinatorial coverage does not establish failure-scenario coverage."}},"exam_03_A_case2_q1":{"answer":{"value":47200,"unit":"€","abs_tolerance":141.6},"rubric":{},"explanation":{"fr":"1. Récurrent = 1200×16 = 19200 €.\n2. Fixe = 18000+7000+3000 = 28000 €.\n3. Impact total = 47200 €.\n4. Impact moyen sur population = 39.3333 €/véhicule ; ce n’est pas le nouveau coût récurrent.\n5. Impact exigences, interfaces et preuves reste à analyser.\n\nPas de coût délai ni de retour terrain inclus ; annoncer clairement ces exclusions.","en":"1. Recurring = 1200×16 = €19200.\n2. Fixed = 18000+7000+3000 = €28000.\n3. Total impact = €47200.\n4. Average population impact = €39.3333/vehicle, not the new recurring cost.\n5. Requirement, interface and evidence impacts still need analysis.\n\nSchedule and field-return costs are excluded and must be declared."}},"exam_03_A_case2_q2":{"answer":{"value":39.333333333333336,"unit":"€/véhicule","abs_tolerance":0.11800000000000001},"rubric":{},"explanation":{"fr":"1. Récurrent = 1200×16 = 19200 €.\n2. Fixe = 18000+7000+3000 = 28000 €.\n3. Impact total = 47200 €.\n4. Impact moyen sur population = 39.3333 €/véhicule ; ce n’est pas le nouveau coût récurrent.\n5. Impact exigences, interfaces et preuves reste à analyser.\n\nPas de coût délai ni de retour terrain inclus ; annoncer clairement ces exclusions.","en":"1. Recurring = 1200×16 = €19200.\n2. Fixed = 18000+7000+3000 = €28000.\n3. Total impact = €47200.\n4. Average population impact = €39.3333/vehicle, not the new recurring cost.\n5. Requirement, interface and evidence impacts still need analysis.\n\nSchedule and field-return costs are excluded and must be declared."}},"exam_03_A_case2_q3":{"answer":{"value":19200,"unit":"€","abs_tolerance":57.6},"rubric":{},"explanation":{"fr":"1. Récurrent = 1200×16 = 19200 €.\n2. Fixe = 18000+7000+3000 = 28000 €.\n3. Impact total = 47200 €.\n4. Impact moyen sur population = 39.3333 €/véhicule ; ce n’est pas le nouveau coût récurrent.\n5. Impact exigences, interfaces et preuves reste à analyser.\n\nPas de coût délai ni de retour terrain inclus ; annoncer clairement ces exclusions.","en":"1. Recurring = 1200×16 = €19200.\n2. Fixed = 18000+7000+3000 = €28000.\n3. Total impact = €47200.\n4. Average population impact = €39.3333/vehicle, not the new recurring cost.\n5. Requirement, interface and evidence impacts still need analysis.\n\nSchedule and field-return costs are excluded and must be declared."}},"exam_03_A_case2_decision":{"answer":{"choice_id":"exam_03_A_case2_decision_c3"},"rubric":{},"explanation":{"fr":"Décider après analyse technique, puis fixer effectivité, non-régression et fermeture documentée. Pas de coût délai ni de retour terrain inclus ; annoncer clairement ces exclusions.","en":"Decide after technical analysis, then set effectivity, regression evidence and documented closure. Schedule and field-return costs are excluded and must be declared."}},"exam_03_A_case3_q1":{"answer":{"value":92.0,"unit":"%","abs_tolerance":0.276},"rubric":{},"explanation":{"fr":"1. FPY = 920/1000×100 = 92 %.\n2. Rendement final = (920+50)/1000×100 = 97 %.\n3. Rebuts = 1000−920−50 = 30.\n4. Les 50 reprises coûtent du temps et des ressources, même si elles sont finalement bonnes.\n\nLe rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"1. FPY = 920/1000×100 = 92%.\n2. Final yield = (920+50)/1000×100 = 97%.\n3. Scrap = 1000−920−50 = 30.\n4. Rework consumes time and resources even when the units ultimately pass.\n\nYield alone establishes neither capability nor process stability."}},"exam_03_A_case3_q2":{"answer":{"value":97.0,"unit":"%","abs_tolerance":0.291},"rubric":{},"explanation":{"fr":"1. FPY = 920/1000×100 = 92 %.\n2. Rendement final = (920+50)/1000×100 = 97 %.\n3. Rebuts = 1000−920−50 = 30.\n4. Les 50 reprises coûtent du temps et des ressources, même si elles sont finalement bonnes.\n\nLe rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"1. FPY = 920/1000×100 = 92%.\n2. Final yield = (920+50)/1000×100 = 97%.\n3. Scrap = 1000−920−50 = 30.\n4. Rework consumes time and resources even when the units ultimately pass.\n\nYield alone establishes neither capability nor process stability."}},"exam_03_A_case3_q3":{"answer":{"value":30,"unit":"unités","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. FPY = 920/1000×100 = 92 %.\n2. Rendement final = (920+50)/1000×100 = 97 %.\n3. Rebuts = 1000−920−50 = 30.\n4. Les 50 reprises coûtent du temps et des ressources, même si elles sont finalement bonnes.\n\nLe rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"1. FPY = 920/1000×100 = 92%.\n2. Final yield = (920+50)/1000×100 = 97%.\n3. Scrap = 1000−920−50 = 30.\n4. Rework consumes time and resources even when the units ultimately pass.\n\nYield alone establishes neither capability nor process stability."}},"exam_03_A_case3_decision":{"answer":{"choice_id":"exam_03_A_case3_decision_c2"},"rubric":{},"explanation":{"fr":"Suivre premier passage, retouches et rebuts séparément, puis démontrer une cause avant correction. Le rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"Track first pass, rework and scrap separately, then demonstrate a cause before correcting. Yield alone establishes neither capability nor process stability."}}}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_03','B','[{"id":"exam_03_B_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1300 véhicules ; surcoût récurrent 17 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule le coût total du changement.","en":"Effective population 1300 vehicles; recurring increase €17/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate total change cost."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±150.3 €.","en":"Absolute tolerance ±150.3 €."}},"blockId":"exam_03_B_case1"},{"id":"exam_03_B_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1300 véhicules ; surcoût récurrent 17 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule l’impact moyen par véhicule effectif.","en":"Effective population 1300 vehicles; recurring increase €17/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate average cost per affected vehicle."},"choices":[],"settings":{"unit":"€/véhicule","toleranceLabel":{"fr":"Tolérance absolue ±0.115615 €/véhicule.","en":"Absolute tolerance ±0.115615 €/véhicule."}},"blockId":"exam_03_B_case1"},{"id":"exam_03_B_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1300 véhicules ; surcoût récurrent 17 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule la seule composante récurrente totale.","en":"Effective population 1300 vehicles; recurring increase €17/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate total recurring component only."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±66.3 €.","en":"Absolute tolerance ±66.3 €."}},"blockId":"exam_03_B_case1"},{"id":"exam_03_B_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1300 véhicules ; surcoût récurrent 17 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Effective population 1300 vehicles; recurring increase €17/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_03_B_case1_decision_c1","position":1,"labels":{"fr":"Clôturer dès que la commande fournisseur est passée, sans vérification.","en":"Close when the supplier order is placed, without verification."}},{"id":"exam_03_B_case1_decision_c2","position":2,"labels":{"fr":"Limiter le coût au surcoût unitaire et ignorer qualification et stock.","en":"Count only unit delta and ignore qualification and inventory."}},{"id":"exam_03_B_case1_decision_c3","position":3,"labels":{"fr":"Décider après analyse technique, puis fixer effectivité, non-régression et fermeture documentée.","en":"Decide after technical analysis, then set effectivity, regression evidence and documented closure."}}],"settings":{},"blockId":"exam_03_B_case1"},{"id":"exam_03_B_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"1100 unités entrantes ; 1020 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nCalcule le rendement de pr