INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_04','A','[{"id":"exam_04_A_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Réseau fin-début : A dure 7 jours ; après A, B dure 7 jours et C 6 jours en parallèle ; D dure 2 jours et attend B et C. Ressources supposées disponibles, calendrier continu.\n\nCalcule la durée totale.","en":"Finish-to-start network: A takes 7 days; then B 7 days and C 6 days in parallel; D takes 2 days after both. Resources available; continuous calendar.\n\nCalculate total duration."},"choices":[],"settings":{"unit":"jours","toleranceLabel":{"fr":"Tolérance absolue ±0.048 jours.","en":"Absolute tolerance ±0.048 jours."}},"blockId":"exam_04_A_case1"},{"id":"exam_04_A_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Réseau fin-début : A dure 7 jours ; après A, B dure 7 jours et C 6 jours en parallèle ; D dure 2 jours et attend B et C. Ressources supposées disponibles, calendrier continu.\n\nCalcule la marge de C.","en":"Finish-to-start network: A takes 7 days; then B 7 days and C 6 days in parallel; D takes 2 days after both. Resources available; continuous calendar.\n\nCalculate C float."},"choices":[],"settings":{"unit":"jours","toleranceLabel":{"fr":"Tolérance absolue ±0.02 jours.","en":"Absolute tolerance ±0.02 jours."}},"blockId":"exam_04_A_case1"},{"id":"exam_04_A_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Réseau fin-début : A dure 7 jours ; après A, B dure 7 jours et C 6 jours en parallèle ; D dure 2 jours et attend B et C. Ressources supposées disponibles, calendrier continu.\n\nRecalcule la durée si B gagne 2 jours.","en":"Finish-to-start network: A takes 7 days; then B 7 days and C 6 days in parallel; D takes 2 days after both. Resources available; continuous calendar.\n\nRecalculate duration if B is shortened by 2 days."},"choices":[],"settings":{"unit":"jours","toleranceLabel":{"fr":"Tolérance absolue ±0.045 jours.","en":"Absolute tolerance ±0.045 jours."}},"blockId":"exam_04_A_case1"},{"id":"exam_04_A_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Réseau fin-début : A dure 7 jours ; après A, B dure 7 jours et C 6 jours en parallèle ; D dure 2 jours et attend B et C. Ressources supposées disponibles, calendrier continu.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Finish-to-start network: A takes 7 days; then B 7 days and C 6 days in parallel; D takes 2 days after both. Resources available; continuous calendar.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_04_A_case1_decision_c1","position":1,"labels":{"fr":"Additionner A, B, C et D pour obtenir la durée, même si B et C sont parallèles.","en":"Add A, B, C and D despite parallel B and C."}},{"id":"exam_04_A_case1_decision_c2","position":2,"labels":{"fr":"Promettre deux jours gagnés sur le programme dès que n’importe quelle tâche gagne deux jours.","en":"Promise two programme days saved whenever any task is shortened by two days."}},{"id":"exam_04_A_case1_decision_c3","position":3,"labels":{"fr":"Vérifier chemin critique et capacité avant d’annoncer le gain de rattrapage.","en":"Check critical path and capacity before announcing recovery benefit."}}],"settings":{},"blockId":"exam_04_A_case1"},{"id":"exam_04_A_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 120000 €, EV 100000 €, AC 130000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule le CPI.","en":"At status date: PV €120000, EV €100000, AC €130000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate CPI."},"choices":[],"settings":{"unit":"ratio","toleranceLabel":{"fr":"Tolérance absolue ±0.00230769 ratio.","en":"Absolute tolerance ±0.00230769 ratio."}},"blockId":"exam_04_A_case2"},{"id":"exam_04_A_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 120000 €, EV 100000 €, AC 130000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule le SPI.","en":"At status date: PV €120000, EV €100000, AC €130000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate SPI."},"choices":[],"settings":{"unit":"ratio","toleranceLabel":{"fr":"Tolérance absolue ±0.0025 ratio.","en":"Absolute tolerance ±0.0025 ratio."}},"blockId":"exam_04_A_case2"},{"id":"exam_04_A_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 120000 €, EV 100000 €, AC 130000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule EAC avec la méthode imposée.","en":"At status date: PV €120000, EV €100000, AC €130000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate EAC with the stated method."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±2340 €.","en":"Absolute tolerance ±2340 €."}},"blockId":"exam_04_A_case2"},{"id":"exam_04_A_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 120000 €, EV 100000 €, AC 130000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"At status date: PV €120000, EV €100000, AC €130000, BAC €600,000. For EAC assume constant future CPI.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_04_A_case2_decision_c1","position":1,"labels":{"fr":"Utiliser SPI comme facteur de conversion certain vers une date de fin.","en":"Use SPI as a certain conversion factor to a completion date."}},{"id":"exam_04_A_case2_decision_c2","position":2,"labels":{"fr":"Analyser les livrables acquis, le chemin critique et l’hypothèse de forecast avant de décider.","en":"Examine earned deliverables, critical path and forecast assumptions before deciding."}},{"id":"exam_04_A_case2_decision_c3","position":3,"labels":{"fr":"Déclarer le programme techniquement validé parce que EV est positif.","en":"Declare technical validation because EV is positive."}}],"settings":{},"blockId":"exam_04_A_case2"},{"id":"exam_04_A_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1100 véhicules ; surcoût récurrent 15 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule le coût total du changement.","en":"Effective population 1100 vehicles; recurring increase €15/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate total change cost."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±133.5 €.","en":"Absolute tolerance ±133.5 €."}},"blockId":"exam_04_A_case3"},{"id":"exam_04_A_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1100 véhicules ; surcoût récurrent 15 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule l’impact moyen par véhicule effectif.","en":"Effective population 1100 vehicles; recurring increase €15/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate average cost per affected vehicle."},"choices":[],"settings":{"unit":"€/véhicule","toleranceLabel":{"fr":"Tolérance absolue ±0.121364 €/véhicule.","en":"Absolute tolerance ±0.121364 €/véhicule."}},"blockId":"exam_04_A_case3"},{"id":"exam_04_A_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1100 véhicules ; surcoût récurrent 15 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nCalcule la seule composante récurrente totale.","en":"Effective population 1100 vehicles; recurring increase €15/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nCalculate total recurring component only."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±49.5 €.","en":"Absolute tolerance ±49.5 €."}},"blockId":"exam_04_A_case3"},{"id":"exam_04_A_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Population effective 1100 véhicules ; surcoût récurrent 15 €/véhicule ; ingénierie 18 000 €, requalification 7 000 €, stock 3 000 €. Coûts fixes distincts ; pas d’actualisation.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Effective population 1100 vehicles; recurring increase €15/vehicle; engineering €18,000, requalification €7,000, stock €3,000. Distinct fixed costs; no discounting.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_04_A_case3_decision_c1","position":1,"labels":{"fr":"Décider après analyse technique, puis fixer effectivité, non-régression et fermeture documentée.","en":"Decide after technical analysis, then set effectivity, regression evidence and documented closure."}},{"id":"exam_04_A_case3_decision_c2","position":2,"labels":{"fr":"Clôturer dès que la commande fournisseur est passée, sans vérification.","en":"Close when the supplier order is placed, without verification."}},{"id":"exam_04_A_case3_decision_c3","position":3,"labels":{"fr":"Limiter le coût au surcoût unitaire et ignorer qualification et stock.","en":"Count only unit delta and ignore qualification and inventory."}}],"settings":{},"blockId":"exam_04_A_case3"}]'::jsonb,'{"exam_04_A_case1_q1":{"answer":{"value":16,"unit":"jours","abs_tolerance":0.048},"rubric":{},"explanation":{"fr":"1. Fin A = 7.\n2. Fin B = 14, fin C = 13.\n3. D commence à 14 ; fin programme 16 jours.\n4. Marge de C = 1 jours.\n5. B réduit de 2 jours : nouvelle durée 15 jours ; une autre branche peut devenir critique.\n\nNi jours ouvrés ni ressource partagée ne sont modélisés.","en":"1. A finishes at 7.\n2. B finishes at 14, C at 13.\n3. D starts at 14; completion is day 16.\n4. C float = 1 days.\n5. Shortening B by 2 days gives 15 total days; another branch can become critical.\n\nWorking calendars and shared-resource constraints are not modelled."}},"exam_04_A_case1_q2":{"answer":{"value":1,"unit":"jours","abs_tolerance":0.02},"rubric":{},"explanation":{"fr":"1. Fin A = 7.\n2. Fin B = 14, fin C = 13.\n3. D commence à 14 ; fin programme 16 jours.\n4. Marge de C = 1 jours.\n5. B réduit de 2 jours : nouvelle durée 15 jours ; une autre branche peut devenir critique.\n\nNi jours ouvrés ni ressource partagée ne sont modélisés.","en":"1. A finishes at 7.\n2. B finishes at 14, C at 13.\n3. D starts at 14; completion is day 16.\n4. C float = 1 days.\n5. Shortening B by 2 days gives 15 total days; another branch can become critical.\n\nWorking calendars and shared-resource constraints are not modelled."}},"exam_04_A_case1_q3":{"answer":{"value":15,"unit":"jours","abs_tolerance":0.045},"rubric":{},"explanation":{"fr":"1. Fin A = 7.\n2. Fin B = 14, fin C = 13.\n3. D commence à 14 ; fin programme 16 jours.\n4. Marge de C = 1 jours.\n5. B réduit de 2 jours : nouvelle durée 15 jours ; une autre branche peut devenir critique.\n\nNi jours ouvrés ni ressource partagée ne sont modélisés.","en":"1. A finishes at 7.\n2. B finishes at 14, C at 13.\n3. D starts at 14; completion is day 16.\n4. C float = 1 days.\n5. Shortening B by 2 days gives 15 total days; another branch can become critical.\n\nWorking calendars and shared-resource constraints are not modelled."}},"exam_04_A_case1_decision":{"answer":{"choice_id":"exam_04_A_case1_decision_c3"},"rubric":{},"explanation":{"fr":"Vérifier chemin critique et capacité avant d’annoncer le gain de rattrapage. Ni jours ouvrés ni ressource partagée ne sont modélisés.","en":"Check critical path and capacity before announcing recovery benefit. Working calendars and shared-resource constraints are not modelled."}},"exam_04_A_case2_q1":{"answer":{"value":0.7692307692307693,"unit":"ratio","abs_tolerance":0.002307692307692308},"rubric":{},"explanation":{"fr":"1. CPI = 100000/130000 = 0.7692.\n2. SPI = 100000/120000 = 0.8333.\n3. EAC = 600000/0.7692 ≈ 780000 €.\n4. CPI < 1 indique un coût supérieur au budget de la valeur acquise ; SPI ne prouve pas la date finale.\n\nLe forecast suppose la poursuite de l’efficacité de coût observée.","en":"1. CPI = 100000/130000 = 0.7692.\n2. SPI = 100000/120000 = 0.8333.\n3. EAC = 600000/0.7692 ≈ €780000.\n4. CPI < 1 indicates earned work cost more than its budget; SPI does not establish completion date.\n\nForecast assumes observed cost efficiency continues."}},"exam_04_A_case2_q2":{"answer":{"value":0.8333333333333334,"unit":"ratio","abs_tolerance":0.0025},"rubric":{},"explanation":{"fr":"1. CPI = 100000/130000 = 0.7692.\n2. SPI = 100000/120000 = 0.8333.\n3. EAC = 600000/0.7692 ≈ 780000 €.\n4. CPI < 1 indique un coût supérieur au budget de la valeur acquise ; SPI ne prouve pas la date finale.\n\nLe forecast suppose la poursuite de l’efficacité de coût observée.","en":"1. CPI = 100000/130000 = 0.7692.\n2. SPI = 100000/120000 = 0.8333.\n3. EAC = 600000/0.7692 ≈ €780000.\n4. CPI < 1 indicates earned work cost more than its budget; SPI does not establish completion date.\n\nForecast assumes observed cost efficiency continues."}},"exam_04_A_case2_q3":{"answer":{"value":780000.0,"unit":"€","abs_tolerance":2340.0},"rubric":{},"explanation":{"fr":"1. CPI = 100000/130000 = 0.7692.\n2. SPI = 100000/120000 = 0.8333.\n3. EAC = 600000/0.7692 ≈ 780000 €.\n4. CPI < 1 indique un coût supérieur au budget de la valeur acquise ; SPI ne prouve pas la date finale.\n\nLe forecast suppose la poursuite de l’efficacité de coût observée.","en":"1. CPI = 100000/130000 = 0.7692.\n2. SPI = 100000/120000 = 0.8333.\n3. EAC = 600000/0.7692 ≈ €780000.\n4. CPI < 1 indicates earned work cost more than its budget; SPI does not establish completion date.\n\nForecast assumes observed cost efficiency continues."}},"exam_04_A_case2_decision":{"answer":{"choice_id":"exam_04_A_case2_decision_c2"},"rubric":{},"explanation":{"fr":"Analyser les livrables acquis, le chemin critique et l’hypothèse de forecast avant de décider. Le forecast suppose la poursuite de l’efficacité de coût observée.","en":"Examine earned deliverables, critical path and forecast assumptions before deciding. Forecast assumes observed cost efficiency continues."}},"exam_04_A_case3_q1":{"answer":{"value":44500,"unit":"€","abs_tolerance":133.5},"rubric":{},"explanation":{"fr":"1. Récurrent = 1100×15 = 16500 €.\n2. Fixe = 18000+7000+3000 = 28000 €.\n3. Impact total = 44500 €.\n4. Impact moyen sur population = 40.4545 €/véhicule ; ce n’est pas le nouveau coût récurrent.\n5. Impact exigences, interfaces et preuves reste à analyser.\n\nPas de coût délai ni de retour terrain inclus ; annoncer clairement ces exclusions.","en":"1. Recurring = 1100×15 = €16500.\n2. Fixed = 18000+7000+3000 = €28000.\n3. Total impact = €44500.\n4. Average population impact = €40.4545/vehicle, not the new recurring cost.\n5. Requirement, interface and evidence impacts still need analysis.\n\nSchedule and field-return costs are excluded and must be declared."}},"exam_04_A_case3_q2":{"answer":{"value":40.45454545454545,"unit":"€/véhicule","abs_tolerance":0.12136363636363637},"rubric":{},"explanation":{"fr":"1. Récurrent = 1100×15 = 16500 €.\n2. Fixe = 18000+7000+3000 = 28000 €.\n3. Impact total = 44500 €.\n4. Impact moyen sur population = 40.4545 €/véhicule ; ce n’est pas le nouveau coût récurrent.\n5. Impact exigences, interfaces et preuves reste à analyser.\n\nPas de coût délai ni de retour terrain inclus ; annoncer clairement ces exclusions.","en":"1. Recurring = 1100×15 = €16500.\n2. Fixed = 18000+7000+3000 = €28000.\n3. Total impact = €44500.\n4. Average population impact = €40.4545/vehicle, not the new recurring cost.\n5. Requirement, interface and evidence impacts still need analysis.\n\nSchedule and field-return costs are excluded and must be declared."}},"exam_04_A_case3_q3":{"answer":{"value":16500,"unit":"€","abs_tolerance":49.5},"rubric":{},"explanation":{"fr":"1. Récurrent = 1100×15 = 16500 €.\n2. Fixe = 18000+7000+3000 = 28000 €.\n3. Impact total = 44500 €.\n4. Impact moyen sur population = 40.4545 €/véhicule ; ce n’est pas le nouveau coût récurrent.\n5. Impact exigences, interfaces et preuves reste à analyser.\n\nPas de coût délai ni de retour terrain inclus ; annoncer clairement ces exclusions.","en":"1. Recurring = 1100×15 = €16500.\n2. Fixed = 18000+7000+3000 = €28000.\n3. Total impact = €44500.\n4. Average population impact = €40.4545/vehicle, not the new recurring cost.\n5. Requirement, interface and evidence impacts still need analysis.\n\nSchedule and field-return costs are excluded and must be declared."}},"exam_04_A_case3_decision":{"answer":{"choice_id":"exam_04_A_case3_decision_c1"},"rubric":{},"explanation":{"fr":"Décider après analyse technique, puis fixer effectivité, non-régression et fermeture documentée. Pas de coût délai ni de retour terrain inclus ; annoncer clairement ces exclusions.","en":"Decide after technical analysis, then set effectivity, regression evidence and documented closure. Schedule and field-return costs are excluded and must be declared."}}}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_04','B','[{"id":"exam_04_B_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 125000 €, EV 104000 €, AC 135000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule le CPI.","en":"At status date: PV €125000, EV €104000, AC €135000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate CPI."},"choices":[],"settings":{"unit":"ratio","toleranceLabel":{"fr":"Tolérance absolue ±0.00231111 ratio.","en":"Absolute tolerance ±0.00231111 ratio."}},"blockId":"exam_04_B_case1"},{"id":"exam_04_B_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 125000 €, EV 104000 €, AC 135000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule le SPI.","en":"At status date: PV €125000, EV €104000, AC €135000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate SPI."},"choices":[],"settings":{"unit":"ratio","toleranceLabel":{"fr":"Tolérance absolue ±0.002496 ratio.","en":"Absolute tolerance ±0.002496 ratio."}},"blockId":"exam_04_B_case1"},{"id":"exam_04_B_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 125000 €, EV 104000 €, AC 135000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule EAC avec la méthode imposée.","en":"At status date: PV €125000, EV €104000, AC €135000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate EAC with the stated method."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±2336.54 €.","en":"Absolute tolerance ±2336.54 €."}},"blockId":"exam_04_B_case1"},{"id":"exam_04_B_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"promp