INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_06','A','[{"id":"exam_06_A_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Segment 500 kbit/s ; trois trames périodiques de 130 bits chacune (surcoûts inclus par hypothèse) ; périodes 13, 20 et 50 ms. Nouveau flux éventuel : 130 bits toutes les 5 ms. Pas d’erreurs ni retransmissions.\n\nCalcule la charge moyenne initiale.","en":"500 kbit/s segment; three periodic 130-bit frames each (overhead included by assumption); periods 13, 20 and 50 ms. Proposed extra flow: 130 bits every 5 ms. No errors or retransmissions.\n\nCalculate initial average load."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.02 %.","en":"Absolute tolerance ±0.02 %."}},"blockId":"exam_06_A_case1"},{"id":"exam_06_A_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Segment 500 kbit/s ; trois trames périodiques de 130 bits chacune (surcoûts inclus par hypothèse) ; périodes 13, 20 et 50 ms. Nouveau flux éventuel : 130 bits toutes les 5 ms. Pas d’erreurs ni retransmissions.\n\nCalcule la charge avec le nouveau flux.","en":"500 kbit/s segment; three periodic 130-bit frames each (overhead included by assumption); periods 13, 20 and 50 ms. Proposed extra flow: 130 bits every 5 ms. No errors or retransmissions.\n\nCalculate load with the new flow."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.02706 %.","en":"Absolute tolerance ±0.02706 %."}},"blockId":"exam_06_A_case1"},{"id":"exam_06_A_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Segment 500 kbit/s ; trois trames périodiques de 130 bits chacune (surcoûts inclus par hypothèse) ; périodes 13, 20 et 50 ms. Nouveau flux éventuel : 130 bits toutes les 5 ms. Pas d’erreurs ni retransmissions.\n\nCalcule le débit initial.","en":"500 kbit/s segment; three periodic 130-bit frames each (overhead included by assumption); periods 13, 20 and 50 ms. Proposed extra flow: 130 bits every 5 ms. No errors or retransmissions.\n\nCalculate initial throughput."},"choices":[],"settings":{"unit":"bit/s","toleranceLabel":{"fr":"Tolérance absolue ±57.3 bit/s.","en":"Absolute tolerance ±57.3 bit/s."}},"blockId":"exam_06_A_case1"},{"id":"exam_06_A_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Segment 500 kbit/s ; trois trames périodiques de 130 bits chacune (surcoûts inclus par hypothèse) ; périodes 13, 20 et 50 ms. Nouveau flux éventuel : 130 bits toutes les 5 ms. Pas d’erreurs ni retransmissions.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"500 kbit/s segment; three periodic 130-bit frames each (overhead included by assumption); periods 13, 20 and 50 ms. Proposed extra flow: 130 bits every 5 ms. No errors or retransmissions.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_06_A_case1_decision_c1","position":1,"labels":{"fr":"Compléter la moyenne par priorités, rafales, blocage, erreurs et délais de gateway.","en":"Complement average load with priorities, bursts, blocking, errors and gateway delays."}},{"id":"exam_06_A_case1_decision_c2","position":2,"labels":{"fr":"Garantir toutes les deadlines parce que la charge moyenne est inférieure à 50 %.","en":"Guarantee every deadline because average load is below 50%."}},{"id":"exam_06_A_case1_decision_c3","position":3,"labels":{"fr":"Assimiler les 130 bits au payload maximal universel de toute trame CAN FD.","en":"Treat 130 bits as universal maximum CAN FD payload."}}],"settings":{},"blockId":"exam_06_A_case1"},{"id":"exam_06_A_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Tâches périodiques : C1=3.2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Ajout envisagé C4=2 ms/T4=10 ms. Un cœur ; pas de surcoût dans cette estimation.\n\nCalcule l’utilisation initiale.","en":"Periodic tasks: C1=3.2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Proposed task C4=2 ms/T4=10 ms. One core; no overhead in this estimate.\n\nCalculate initial utilisation."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.171 %.","en":"Absolute tolerance ±0.171 %."}},"blockId":"exam_06_A_case2"},{"id":"exam_06_A_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Tâches périodiques : C1=3.2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Ajout envisagé C4=2 ms/T4=10 ms. Un cœur ; pas de surcoût dans cette estimation.\n\nCalcule l’utilisation après ajout.","en":"Periodic tasks: C1=3.2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Proposed task C4=2 ms/T4=10 ms. One core; no overhead in this estimate.\n\nCalculate utilisation after addition."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.231 %.","en":"Absolute tolerance ±0.231 %."}},"blockId":"exam_06_A_case2"},{"id":"exam_06_A_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Tâches périodiques : C1=3.2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Ajout envisagé C4=2 ms/T4=10 ms. Un cœur ; pas de surcoût dans cette estimation.\n\nCalcule la réserve moyenne après ajout.","en":"Periodic tasks: C1=3.2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Proposed task C4=2 ms/T4=10 ms. One core; no overhead in this estimate.\n\nCalculate remaining average capacity."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.069 %.","en":"Absolute tolerance ±0.069 %."}},"blockId":"exam_06_A_case2"},{"id":"exam_06_A_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Tâches périodiques : C1=3.2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Ajout envisagé C4=2 ms/T4=10 ms. Un cœur ; pas de surcoût dans cette estimation.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Periodic tasks: C1=3.2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Proposed task C4=2 ms/T4=10 ms. One core; no overhead in this estimate.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_06_A_case2_decision_c1","position":1,"labels":{"fr":"Prouver toutes les deadlines avec U < 100 % seulement.","en":"Prove every deadline using U < 100% alone."}},{"id":"exam_06_A_case2_decision_c2","position":2,"labels":{"fr":"Utiliser le temps moyen d’une tâche comme pire temps d’exécution sans justification.","en":"Use average task time as worst-case execution without justification."}},{"id":"exam_06_A_case2_decision_c3","position":3,"labels":{"fr":"Faire une analyse de réponse avec deadlines, priorités et blocages, puis tester la baseline logicielle.","en":"Analyse response using deadlines, priorities and blocking, then test the software baseline."}}],"settings":{},"blockId":"exam_06_A_case2"},{"id":"exam_06_A_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Échantillonnage toutes les 12 ms ; défaut présent juste avant ou juste après une observation ; confirmation à la 3e observation invalide consécutive. Une observation valide remet le compteur à zéro. Récupération après 2 observations valides.\n\nDonne la borne basse approchée de détection.","en":"Sampling every 12 ms; fault appears just before or after an observation; confirm at the third consecutive invalid sample. A valid sample resets the counter. Recovery requires two valid observations.\n\nGive the approximate lower detection bound."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.072 ms.","en":"Absolute tolerance ±0.072 ms."}},"blockId":"exam_06_A_case3"},{"id":"exam_06_A_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Échantillonnage toutes les 12 ms ; défaut présent juste avant ou juste après une observation ; confirmation à la 3e observation invalide consécutive. Une observation valide remet le compteur à zéro. Récupération après 2 observations valides.\n\nDonne la borne haute approchée de détection.","en":"Sampling every 12 ms; fault appears just before or after an observation; confirm at the third consecutive invalid sample. A valid sample resets the counter. Recovery requires two valid observations.\n\nGive the approximate upper detection bound."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.108 ms.","en":"Absolute tolerance ±0.108 ms."}},"blockId":"exam_06_A_case3"},{"id":"exam_06_A_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Échantillonnage toutes les 12 ms ; défaut présent juste avant ou juste après une observation ; confirmation à la 3e observation invalide consécutive. Une observation valide remet le compteur à zéro. Récupération après 2 observations valides.\n\nDonne la récupération au pire déphasage.","en":"Sampling every 12 ms; fault appears just before or after an observation; confirm at the third consecutive invalid sample. A valid sample resets the counter. Recovery requires two valid observations.\n\nGive worst-phase recovery time."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.072 ms.","en":"Absolute tolerance ±0.072 ms."}},"blockId":"exam_06_A_case3"},{"id":"exam_06_A_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Échantillonnage toutes les 12 ms ; défaut présent juste avant ou juste après une observation ; confirmation à la 3e observation invalide consécutive. Une observation valide remet le compteur à zéro. Récupération après 2 observations valides.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Sampling every 12 ms; fault appears just before or after an observation; confirm at the third consecutive invalid sample. A valid sample resets the counter. Recovery requires two valid observations.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_06_A_case3_decision_c1","position":1,"labels":{"fr":"Accumuler les invalides non consécutifs même si le contrat impose une remise à zéro.","en":"Accumulate nonconsecutive invalid samples despite the reset contract."}},{"id":"exam_06_A_case3_decision_c2","position":2,"labels":{"fr":"Tester déphasage, intermittence, réinitialisation et reprise, en séparant diagnostic et réaction fonctionnelle.","en":"Test phase, intermittency, reset and recovery while separating diagnosis from functional response."}},{"id":"exam_06_A_case3_decision_c3","position":3,"labels":{"fr":"Confirmer en exactement une période quelle que soit la règle des trois observations.","en":"Confirm in exactly one period regardless of the three-sample rule."}}],"settings":{},"blockId":"exam_06_A_case3"}]'::jsonb,'{"exam_06_A_case1_q1":{"answer":{"value":3.819999999999999,"unit":"%","abs_tolerance":0.02},"rubric":{},"explanation":{"fr":"1. Fréquence totale = 1000/13+1000/20+1000/50 = 146.9231 trames/s.\n2. Débit = 130×146.9231 = 19100 bit/s.\n3. Charge = 3.82 %.\n4. Ajout = 5.2 points de pourcentage ; charge totale 9.02 %.\n5. Aucun de ces résultats ne démontre une deadline.\n\nTaille de trame simplifiée ; ne pas appliquer telle quelle aux phases CAN FD.","en":"1. Total frequency = 1000/13+1000/20+1000/50 = 146.9231 frames/s.\n2. Throughput = 130×146.9231 = 19100 bit/s.\n3. Load = 3.82%.\n4. Extra flow adds 5.2 percentage points; total 9.02%.\n5. None of these results establishes a deadline.\n\nSimplified frame size; do not apply unchanged to CAN FD phases."}},"exam_06_A_case1_q2":{"answer":{"value":9.02,"unit":"%","abs_tolerance":0.02706},"rubric":{},"explanation":{"fr":"1. Fréquence totale = 1000/13+1000/20+1000/50 = 146.9231 trames/s.\n2. Débit = 130×146.9231 = 19100 bit/s.\n3. Charge = 3.82 %.\n4. Ajout = 5.2 points de pourcentage ; charge totale 9.02 %.\n5. Aucun de ces résultats ne démontre une deadline.\n\nTaille de trame simplifiée ; ne pas appliquer telle quelle aux phases CAN FD.","en":"1. Total frequency = 1000/13+1000/20+1000/50 = 146.9231 frames/s.\n2. Throughput = 130×146.9231 = 19100 bit/s.\n3. Load = 3.82%.\n4. Extra flow adds 5.2 percentage points; total 9.02%.\n5. None of these results establishes a deadline.\n\nSimplified frame size; do not apply unchanged to CAN FD phases."}},"exam_06_A_case1_q3":{"answer":{"value":19099.999999999996,"unit":"bit/s","abs_tolerance":57.29999999999999},"rubric":{},"explanation":{"fr":"1. Fréquence totale = 1000/13+1000/20+1000/50 = 146.9231 trames/s.\n2. Débit = 130×146.9231 = 19100 bit/s.\n3. Charge = 3.82 %.\n4. Ajout = 5.2 points de pourcentage ; charge totale 9.02 %.\n5. Aucun de ces résultats ne démontre une deadline.\n\nTaille de trame simplifiée ; ne pas appliquer telle quelle aux phases CAN FD.","en":"1. Total frequency = 1000/13+1000/20+1000/50 = 146.9231 frames/s.\n2. Throughput = 130×146.9231 = 19100 bit/s.\n3. Load = 3.82%.\n4. Extra flow adds 5.2 percentage points; total 9.02%.\n5. None of these results establishes a deadline.\n\nSimplified frame size; do not apply unchanged to CAN FD phases."}},"exam_06_A_case1_decision":{"answer":{"choice_id":"exam_06_A_case1_decision_c1"},"rubric":{},"explanation":{"fr":"Compléter la moyenne par priorités, rafales, blocage, erreurs et délais de gateway. Taille de trame simplifiée ; ne pas appliquer telle quelle aux phases CAN FD.","en":"Complement average load with priorities, bursts, blocking, errors and gateway delays. Simplified frame size; do not apply unchanged to CAN FD phases."}},"exam_06_A_case2_q1":{"answer":{"value":56.99999999999999,"unit":"%","abs_tolerance":0.17099999999999999},"rubric":{},"explanation":{"fr":"1. Contributions : 32 %, 15 %, 10 %.\n2. Utilisation initiale = 57 %.\n3. Nouvelle tâche = 20 points ; total 77 %.\n4. Réserve moyenne = 23 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 32%, 15%, 10%.\n2. Initial utilisation = 57%.\n3. Extra task adds 20 points; total 77%.\n4. Average reserve = 23%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}},"exam_06_A_case2_q2":{"answer":{"value":77.0,"unit":"%","abs_tolerance":0.231},"rubric":{},"explanation":{"fr":"1. Contributions : 32 %, 15 %, 10 %.\n2. Utilisation initiale = 57 %.\n3. Nouvelle tâche = 20 points ; total 77 %.\n4. Réserve moyenne = 23 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 32%, 15%, 10%.\n2. Initial utilisation = 57%.\n3. Extra task adds 20 points; total 77%.\n4. Average reserve = 23%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}},"exam_06_A_case2_q3":{"answer":{"value":23.0,"unit":"%","abs_tolerance":0.069},"rubric":{},"explanation":{"fr":"1. Contributions : 32 %, 15 %, 10 %.\n2. Utilisation initiale = 57 %.\n3. Nouvelle tâche = 20 points ; total 77 %.\n4. Réserve moyenne = 23 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 32%, 15%, 10%.\n2. Initial utilisation = 57%.\n3. Extra task adds 20 points; total 77%.\n4. Average reserve = 23%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}},"exam_06_A_case2_decision":{"answer":{"choice_id":"exam_06_A_case2_decision_c3"},"rubric":{},"explanation":{"fr":"Faire une analyse de réponse avec deadlines, priorités et blocages, puis tester la baseline logicielle. Le calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"Analyse response using deadlines, priorities and blocking, then test the software baseline. This is a capacity filter, not a universal schedulability test."}},"exam_06_A_case3_q1":{"answer":{"value":24,"unit":"ms","abs_tolerance":0.07200000000000001},"rubric":{},"explanation":{"fr":"1. Défaut juste avant observation : première observation presque immédiate ; troisième après environ 2T = 24 ms.\n2. Défaut juste après : troisième après presque 3T = 36 ms.\n3. Récupération pire phase ≈ 2T = 24 ms.\n4. Les bornes sont approchées par phase ; l’exécution et la gigue ne sont pas ajoutées.\n\nPas de gigue ni temps de traitement ; les intervalles réels dépendent des points de mesure.","en":"1. Fault just before sampling: first sample almost immediate, third after about 2T = 24 ms.\n2. Fault just after: third sample after almost 3T = 36 ms.\n3. Worst-phase recovery ≈ 2T = 24 ms.\n4. Bounds reflect sampling phase; execution and jitter are excluded.\n\nNo jitter or processing time; actual intervals depend on measurement endpoints."}},"exam_06_A_case3_q2":{"answer":{"value":36,"unit":"ms","abs_tolerance":0.108},"rubric":{},"explanation":{"fr":"1. Défaut juste avant observation : première observation presque immédiate ; troisième après environ 2T = 24 ms.\n2. Défaut juste après : troisième après presque 3T = 36 ms.\n3. Récupération pire phase ≈ 2T = 24 ms.\n4. Les bornes sont approchées par phase ; l’exécution et la gigue ne sont pas ajoutées.\n\nPas de gigue ni temps de traitement ; les intervalles réels dépendent des points de mesure.","en":"1. Fault just before sampling: first sample almost immediate, third after about 2T = 24 ms.\n2. Fault just after: third sample after almost 3T = 36 ms.\n3. Worst-phase recovery ≈ 2T = 24 ms.\n4. Bounds reflect sampling phase; execution and jitter are excluded.\n\nNo jitter or processing time; actual intervals depend on measurement endpoints."}},"exam_06_A_case3_q3":{"answer":{"value":24,"unit":"ms","abs_tolerance":0.07200000000000001},"rubric":{},"explanation":{"fr":"1. Défaut juste avant observation : première observation presque immédiate ; troisième après environ 2T = 24 ms.\n2. Défaut juste après : troisième après presque 3T = 36 ms.\n3. Récupération pire phase ≈ 2T = 24 ms.\n4. Les bornes sont approchées par phase ; l’exécution et la gigue ne sont pas ajoutées.\n\nPas de gigue ni temps de traitement ; les intervalles réels dépendent des points de mesure.","en":"1. Fault just before sampling: first sample almost immediate, third after about 2T = 24 ms.\n2. Fault just after: third sample after almost 3T = 36 ms.\n3. Worst-phase recovery ≈ 2T = 24 ms.\n4. Bounds reflect sampling phase; execution and jitter are excluded.\n\nNo jitter or processing time; actual intervals depend on measurement endpoints."}},"exam_06_A_case3_decision":{"answer":{"choice_id":"exam_06_A_case3_decision_c2"},"rubric":{},"explanation":{"fr":"Tester déphasage, intermittence, réinitialisation et reprise, en séparant diagnostic et réaction fonctionnelle. Pas de gigue ni temps de traitement ; les intervalles réels dépendent des points de mesure.","en":"Test phase, intermittency, reset and recovery while separating diagnosis from functional response. No jitter or processing time; actual intervals depend on measurement endpoints."}}}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_06','B','[{"id":"exam_06_B_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Tâches périodiques : C1=2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Ajout envisagé C4=2 ms/T4=10 ms. Un cœur ; pas de surcoût dans cette estimation.\n\nCalcule l’utilisation initiale.","en":"Periodic tasks: C1=2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Proposed task C4=2 ms/T4=10 ms. One core; no overhead in this estimate.\n\nCalculate initial utilisation."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.135 %.","en":"Absolute tolerance ±0.135 %."}},"blockId":"exam_06_B_case1"},{"id":"exam_06_B_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Tâches périodiques : C1=2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Ajout envisagé C4=2 ms/T4=10 ms. Un cœur ; pas de surcoût dans cette estimation.\n\nCalcule l’utilisation après ajout.","en":"Periodic tasks: C1=2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Proposed task C4=2 ms/T4=10 ms. One core; no overhead in this estimate.\n\nCalculate utilisation after addition."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.195 %.","en":"Absolute tolerance ±0.195 %."}},"blockId":"exam_06_B_case1"},{"id":"exam_06_B_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Tâches périodiques : C1=2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Ajout envisagé C4=2 ms/T4=10 ms. Un cœur ; pas de surcoût dans cette estimation.\n\nCalcule la réserve moyenne après ajout.","en":"Periodic tasks: C1=2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Proposed task C4=2 ms/T4=10 ms. One core; no overhead in this estimate.\n\nCalculate remaining average capacity."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.105 %.","en":"Absolute tolerance ±0.105 %."}},"blockId":"exam_06_B_case1"},{"id":"exam_06_B_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Tâches périodiques : C1=2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Ajout envisagé C4=2 ms/T4=10 ms. Un cœur ; pas de surcoût dans cette estimation.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Periodic tasks: C1=2 ms/T1=10 ms, C2=3 ms/T2=20 ms, C3=5 ms/T3=50 ms. Proposed task C4=2 ms/T4=10 ms. One core; no overhead in this estimate.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_06_B_case1_decision_c1","position":1,"labels":{"fr":"Prouver toutes les deadlines avec U < 100 % seulement.","en":"Prove every deadline using U < 100% alone."}},{"id":"exam_06_B_case1_decision_c2","position":2,"labels":{"fr":"Utiliser le temps moyen d’une tâche comme pire temps d’exécution sans justification.","en":"Use average task time as worst-case execution without justification."}},{"id":"exam_06_B_case1_decision_c3","position":3,"labels":{"fr":"Faire une analyse de réponse avec deadlines, priorités et blocages, puis tester la baseline logicielle.","en":"Analyse response using deadlines, priorities and blocking, then test the software baseline."}}],"settings":{},"blockId":"exam_06_B_case1"},{"id":"exam_06_B_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Échantillonnage toutes les 13 ms ; défaut présent juste avant ou juste après une observation ; confirmation à la 3e observation invalide consécutive. Une observation valide remet le compteur à zéro. Récupération après 2 observations valides.\n\nDonne la borne basse approchée de détection.","en":"Sampling every 13 ms; fault appears just before or after an observation; confirm at the third consecutive invalid sample. A valid sample resets the counter. Recovery requires two valid observations.\n\nGive the approximate lower detection bound."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.078 ms.","en":"Absolute tolerance ±0.078 ms."}},"blockId":"exam_06_B_case2"},{"id":"exam_06_B_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Échantillonnage toutes les 13 ms ; défaut présent juste avant ou juste après une observation ; confirmation à la 3e observation invalide consécutive. Une observation valide remet le compteur à zéro. Récupération après 2 observations valides.\n\nDonne la borne haute approchée de détection.","en":"Sampling every 13 ms; fault appears just before or after an observation; confirm at the third consecutive invalid sample. A valid sample resets the counter. Recovery requires two valid observations.\n\nGive the approximate upper detection bound."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.117 ms.","en":"Absolute tolerance ±0.117 ms."}},"blockId":"exam_06_B_case2"},{"id":"exam_06_B_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Échantillonnage toutes les 13 ms ; défaut présent juste avant ou juste après une observation ; confirmation à la 3e observation invalide consécutive. Une observation valide remet le compteur à zéro. Récupération après 2 observations valides.\n\nDonne la récupération au pire déphasage.","en":"Sampling every 13 ms; fault appears just before or after an observation; confirm at the third consecutive invalid sample. A valid sample resets the counter. Recovery requires two valid observations.\n\nGive worst-phase recovery time."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.078 ms.","en":"Absolute tolerance ±0.078 ms."}},"blockId":"exam_06_B_case2"},{"id":"exam_06_B_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Échantillonnage toutes les 13 ms ; défaut présent juste avant ou juste après une observation ; confirmation à la 3e observation invalide consécutive. Une observation valide remet le compteur à zéro. Récupération après 2 observations valides.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Sampling every 13 ms; fault appears just before or after an observation; confirm at the third consecutive invalid sample. A valid sample resets the counter. Recovery requires two valid observations.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_06_B_case2_decision_c1","position":1,"labels":{"fr":"Accumuler les invalides non consécutifs même si le contrat impose une remise à zéro.","en":"Accumulate nonconsecutive invalid samples despite the reset contract."}},{"id":"exam_06_B_case2_decision_c2","position":2,"labels":{"fr":"Tester déphasage, intermittence, réinitialisation et reprise, en séparant diagnostic et réaction fonctionnelle.","en":"Test phase, intermittency, reset and recovery while separating diagnosis from functional response."}},{"id":"exam_06_B_case2_decision_c3","position":3,"labels":{"fr":"Confirmer en exactement une période quelle que soit la règle des trois observations.","en":"Confirm in exactly one period regardless of the three-sample rule."}}],"settings":{},"blockId":"exam_06_B_case2"},{"id":"exam_06_B_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Demande de couple 22 N·m ; codage entier non signé uint16, résolution 0,1 N·m/bit, offset zéro, little-endian. Le décodage inversé utilise aussi uint16.\n\nCalcule la valeur entière brute.","en":"Torque demand 22 N·m; unsigned uint16 integer, resolution 0.1 N·m/bit, zero offset, little-endian. Reversed decoding also uses uint16.\n\nCalculate raw integer value."},"choices":[],"settings":{"unit":"code","toleranceLabel":{"fr":"Tolérance absolue ±0.01 code.","en":"Absolute tolerance ±0.01 code."}},"blockId":"exam_06_B_case3"},{"id":"exam_06_B_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Demande de couple 22 N·m ; codage entier non signé uint16, résolution 0,1 N·m/bit, offset zéro, little-endian. Le décodage inversé utilise aussi uint16.\n\nCalcule le couple obtenu par lecture inversée.","en":"Torque demand 22 N·m; unsigned uint16 integer, resolution 0.1 N·m/bit, zero offset, little-endian. Reversed decoding also uses uint16.\n\nCalculate torque after reversed-byte decoding."},"choices":[],"settings":{"unit":"N·m","toleranceLabel":{"fr":"Tolérance absolue ±16.896 N·m.","en":"Absolute tolerance ±16.896 N·m."}},"blockId":"exam_06_B_case3"},{"id":"exam_06_B_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Demande de couple 22 N·m ; codage entier non signé uint16, résolution 0,1 N·m/bit, offset zéro, little-endian. Le décodage inversé utilise aussi uint16.\n\nDonne la valeur décimale du premier octet transmis.","en":"Torque demand 22 N·m; unsigned uint16 integer, resolution 0.1 N·m/bit, zero offset, little-endian. Reversed decoding also uses uint16.\n\nGive the decimal value of the first transmitted byte."},"choices":[],"settings":{"unit":"octet","toleranceLabel":{"fr":"Tolérance absolue ±0.01 octet.","en":"Absolute tolerance ±0.01 octet."}},"blockId":"exam_06_B_case3"},{"id":"exam_06_B_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Demande de couple 22 N·m ; codage entier non signé uint16, résolution 0,1 N·m/bit, offset zéro, little-endian. Le décodage inversé utilise aussi uint16.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Torque demand 22 N·m; unsigned uint16 integer, resolution 0.1 N·m/bit, zero offset, little-endian. Reversed decoding also uses uint16.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_06_B_case3_decision_c1","position":1,"labels":{"fr":"Fixer et tester unité, signe, ordre des octets, domaine et réaction au défaut dans l’ICD.","en":"Specify and test unit, sign, byte order, range and fault response in the ICD."}},{"id":"exam_06_B_case3_decision_c2","position":2,"labels":{"fr":"Corriger par un gain de calibration sans modifier le contrat d’interface ni tester les limites.","en":"Apply a calibration gain without fixing the interface contract or testing limits."}},{"id":"exam_06_B_case3_decision_c3","position":3,"labels":{"fr":"Accepter l’échange parce que les deux équipements sont conformes à leurs spécifications locales.","en":"Accept the exchange because both devices meet their local specifications."}}],"settings":{},"blockId":"exam_06_B_case3"}]'::jsonb,'{"exam_06_B_case1_q1":{"answer":{"value":44.99999999999999,"unit":"%","abs_tolerance":0.13499999999999998},"rubric":{},"explanation":{"fr":"1. Contributions : 20 %, 15 %, 10 %.\n2. Utilisation initiale = 45 %.\n3. Nouvelle tâche = 20 points ; total 65 %.\n4. Réserve moyenne = 35 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 20%, 15%, 10%.\n2. Initial utilisation = 45%.\n3. Extra task adds 20 points; total 65%.\n4. Average reserve = 35%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}},"exam_06_B_case1_q2":{"answer":{"value":65.0,"unit":"%","abs_tolerance":0.195},"rubric":{},"explanation":{"fr":"1. Contributions : 20 %, 15 %, 10 %.\n2. Utilisation initiale = 45 %.\n3. Nouvelle tâche = 20 points ; total 65 %.\n4. Réserve moyenne = 35 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 20%, 15%, 10%.\n2. Initial utilisation = 45%.\n3. Extra task adds 20 points; total 65%.\n4. Average reserve = 35%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}},"exam_06_B_case1_q3":{"answer":{"value":35.0,"unit":"%","abs_tolerance":0.105},"rubric":{},"explanation":{"fr":"1. Contributions : 20 %, 15 %, 10 %.\n2. Utilisation initiale = 45 %.\n3. Nouvelle tâche = 20 points ; total 65 %.\n4. Réserve moyenne = 35 %.\n5. Priorités, deadlines et blocage restent à analyser.\n\nLe calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"1. Contributions: 20%, 15%, 10%.\n2. Initial utilisation = 45%.\n3. Extra task adds 20 points; total 65%.\n4. Average reserve = 35%.\n5. Priorities, deadlines and blocking still require analysis.\n\nThis is a capacity filter, not a universal schedulability test."}},"exam_06_B_case1_decision":{"answer":{"choice_id":"exam_06_B_case1_decision_c3"},"rubric":{},"explanation":{"fr":"Faire une analyse de réponse avec deadlines, priorités et blocages, puis tester la baseline logicielle. Le calcul n’est qu’un filtre de capacité, pas un test universel d’ordonnançabilité.","en":"Analyse response using deadlines, priorities and blocking, then test the software baseline. This is a capacity filter, not a universal schedulability test."}},"exam_06_B_case2_q1":{"answer":{"value":26,"unit":"ms","abs_tolerance":0.078},"rubric":{},"explanation":{"fr":"1. Défaut juste avant observation : première observation presque immédiate ; troisième après environ 2T = 26 ms.\n2. Défaut juste après : troisième après presque 3T = 39 ms.\n3. Récupération pire phase ≈ 2T = 26 ms.\n4. Les bornes sont approchées par phase ; l’exécution et la gigue ne sont pas ajoutées.\n\nPas de gigue ni temps de traitement ; les intervalles réels dépendent des points de mesure.","en":"1. Fault just before sampling: first sample almost immediate, third after about 2T = 26 ms.\n2. Fault just after: third sample after almost 3T = 39 ms.\n3. Worst-phase recovery ≈ 2T = 26 ms.\n4. Bounds reflect sampling phase; execution and jitter are excluded.\n\nNo jitter or processing time; actual intervals depend on measurement endpoints."}},"exam_06_B_case2_q2":{"answer":{"value":39,"unit":"ms","abs_tolerance":0.117},"rubric":{},"explanation":{"fr":"1. Défaut juste avant observation : première observation presque immédiate ; troisième après environ 2T = 26 ms.\n2. Défaut juste après : troisième après presque 3T = 39 ms.\n3. Récupération pire phase ≈ 2T = 26 ms.\n4. Les bornes sont approchées par phase ; l’exécution et la gigue ne sont pas ajoutées.\n\nPas de gigue ni temps de traitement ; les intervalles réels dépendent des points de mesure.","en":"1. Fault just before sampling: first sample almost immediate, third after about 2T = 26 ms.\n2. Fault just after: third sample after almost 3T = 39 ms.\n3. Worst-phase recovery ≈ 2T = 26 ms.\n4. Bounds reflect sampling phase; execution and jitter are excluded.\n\nNo jitter or processing time; actual intervals depend on measurement endpoints."}},"exam_06_B_case2_q3":{"answer":{"value":26,"unit":"ms","abs_tolerance":0.078},"rubric":{},"explanation":{"fr":"1. Défaut juste avant observation : première observation presque immédiate ; troisième après environ 2T = 26 ms.\n2. Défaut juste après : troisième après presque 3T = 39 ms.\n3. Récupération pire phase ≈ 2T = 26 ms.\n4. Les bornes sont approchées par phase ; l’exécution et la gigue ne sont pas ajoutées.\n\nPas de gigue ni temps de traitement ; les intervalles réels dépendent des points de mesure.","en":"1. Fault just before sampling: first sample almost immediate, third after about 2T = 26 ms.\n2. Fault just after: third sample after almost 3T = 39 ms.\n3. Worst-phase recovery ≈ 2T = 26 ms.\n4. Bounds reflect sampling phase; execution and jitter are excluded.\n\nNo jitter or processing time; actual intervals depend on measurement endpoints."}},"exam_06_B_case2_decision":{"answer":{"choice_id":"exam_06_B_case2_decision_c2"},"rubric":{},"explanation":{"fr":"Tester déphasage, intermittence, réinitialisation et reprise, en séparant diagnostic et réaction fonctionnelle. Pas de gigue ni temps de traitement ; les intervalles réels dépendent des points de mesure.","en":"Test phase, intermittency, reset and recovery while separating diagnosis from functional response. No jitter or processing time; actual intervals depend on measurement endpoints."}},"exam_06_B_case3_q1":{"answer":{"value":220,"unit":"code","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Valeur entière = 22/0,1 = 220.\n2. Octets décimaux little-endian : [220, 0] ; hex : [DC, 00].\n3. Lecture inversée : 256×220+0 = 56320 pas ; couple apparent 5632 N·m.\n4. Un aller-retour indépendant vérifie le codage ; domaine, validité et timeout demandent d’autres tests.\n\nLe contrat de cet exercice est uint16. Domaine, saturation et validité demandent des tests supplémentaires.","en":"1. Integer = 22/0.1 = 220.\n2. Little-endian decimal bytes: [220, 0]; hex: [DC, 00].\n3. Reversed decoding: 256×220+0 = 56320 counts; apparent torque 5632 N·m.\n4. An independent round trip checks encoding; range, validity and timeout require additional tests.\n\nThis exercise uses uint16. Range, saturation and validity need additional tests."}},"exam_06_B_case3_q2":{"answer":{"value":5632.0,"unit":"N·m","abs_tolerance":16.896},"rubric":{},"explanation":{"fr":"1. Valeur entière = 22/0,1 = 220.\n2. Octets décimaux little-endian : [220, 0] ; hex : [DC, 00].\n3. Lecture inversée : 256×220+0 = 56320 pas ; couple apparent 5632 N·m.\n4. Un aller-retour indépendant vérifie le codage ; domaine, validité et timeout demandent d’autres tests.\n\nLe contrat de cet exercice est uint16. Domaine, saturation et validité demandent des tests supplémentaires.","en":"1. Integer = 22/0.1 = 220.\n2. Little-endian decimal bytes: [220, 0]; hex: [DC, 00].\n3. Reversed decoding: 256×220+0 = 56320 counts; apparent torque 5632 N·m.\n4. An independent round trip checks encoding; range, validity and timeout require additional tests.\n\nThis exercise uses uint16. Range, saturation and validity need additional tests."}},"exam_06_B_case3_q3":{"answer":{"value":220,"unit":"octet","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Valeur entière = 22/0,1 = 220.\n2. Octets décimaux little-endian : [220, 0] ; hex : [DC, 00].\n3. Lecture inversée : 256×220+0 = 56320 pas ; couple apparent 5632 N·m.\n4. Un aller-retour indépendant vérifie le codage ; domaine, validité et timeout demandent d’autres tests.\n\nLe contrat de cet exercice est uint16. Domaine, saturation et validité demandent des tests supplémentaires.","en":"1. Integer = 22/0.1 = 220.\n2. Little-endian decimal bytes: [220, 0]; hex: [DC, 00].\n3. Reversed decoding: 256×220+0 = 56320 counts; apparent torque 5632 N·m.\n4. An independent round trip checks encoding; range, validity and timeout require additional tests.\n\nThis exercise uses uint16. Range, saturation and validity need additional tests."}},"exam_06_B_case3_decision":{"answer":{"choice_id":"exam_06_B_case3_decision_c1"},"rubric":{},"explanation":{"fr":"Fixer et tester unité, signe, ordre des octets, domaine et réaction au défaut dans l’ICD. Le contrat de cet exercice est uint16. Domaine, saturation et validité demandent des tests supplémentaires.","en":"Specify and test unit, sign, byte order, range and fault response in the ICD. This exercise uses uint16. Range, saturation and validity need additional tests."}}}'::jsonb) ON CONFLICT DO NOTHING;
