INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_07','A','[{"id":"exam_07_A_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Événements A et B supposés indépendants sur la même mission : pA=0.016, pB=0,02. Variante avec cause commune C indépendante du résidu A∩B : pC=0,005 ; sommet C OU (A ET B).\n\nCalcule la probabilité AND indépendante.","en":"Events A and B assumed independent over the same mission: pA=0.016, pB=0.02. Variant adds common cause C independent of residual A∩B: pC=0.005; top event C OR (A AND B).\n\nCalculate independent AND probability."},"choices":[],"settings":{"unit":"probabilité","toleranceLabel":{"fr":"Tolérance absolue ±3.2e-07 probabilité.","en":"Absolute tolerance ±3.2e-07 probabilité."}},"blockId":"exam_07_A_case1"},{"id":"exam_07_A_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Événements A et B supposés indépendants sur la même mission : pA=0.016, pB=0,02. Variante avec cause commune C indépendante du résidu A∩B : pC=0,005 ; sommet C OU (A ET B).\n\nCalcule la probabilité OR indépendante.","en":"Events A and B assumed independent over the same mission: pA=0.016, pB=0.02. Variant adds common cause C independent of residual A∩B: pC=0.005; top event C OR (A AND B).\n\nCalculate independent OR probability."},"choices":[],"settings":{"unit":"probabilité","toleranceLabel":{"fr":"Tolérance absolue ±3.568e-05 probabilité.","en":"Absolute tolerance ±3.568e-05 probabilité."}},"blockId":"exam_07_A_case1"},{"id":"exam_07_A_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Événements A et B supposés indépendants sur la même mission : pA=0.016, pB=0,02. Variante avec cause commune C indépendante du résidu A∩B : pC=0,005 ; sommet C OU (A ET B).\n\nCalcule le sommet avec la cause commune.","en":"Events A and B assumed independent over the same mission: pA=0.016, pB=0.02. Variant adds common cause C independent of residual A∩B: pC=0.005; top event C OR (A AND B).\n\nCalculate top-event probability including common cause."},"choices":[],"settings":{"unit":"probabilité","toleranceLabel":{"fr":"Tolérance absolue ±5.3184e-06 probabilité.","en":"Absolute tolerance ±5.3184e-06 probabilité."}},"blockId":"exam_07_A_case1"},{"id":"exam_07_A_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Événements A et B supposés indépendants sur la même mission : pA=0.016, pB=0,02. Variante avec cause commune C indépendante du résidu A∩B : pC=0,005 ; sommet C OU (A ET B).\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Events A and B assumed independent over the same mission: pA=0.016, pB=0.02. Variant adds common cause C independent of residual A∩B: pC=0.005; top event C OR (A AND B).\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_07_A_case1_decision_c1","position":1,"labels":{"fr":"Attribuer automatiquement un ASIL à partir de pA×pB.","en":"Assign ASIL automatically from pA×pB."}},{"id":"exam_07_A_case1_decision_c2","position":2,"labels":{"fr":"Ignorer la cause commune parce que les deux composants ont des références différentes.","en":"Ignore common cause because components have different part numbers."}},{"id":"exam_07_A_case1_decision_c3","position":3,"labels":{"fr":"Vérifier définition des événements et causes communes ; garder cette analyse distincte de la classification HARA.","en":"Check event definitions and common causes; keep this calculation distinct from HARA classification."}}],"settings":{},"blockId":"exam_07_A_case1"},{"id":"exam_07_A_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Exercice financier fictif uniquement : impact  220000 € ; probabilité annuelle supposée avant contrôle 0,08, après contrôle 0,03 ; contrôle 5 000 €/an. Même population et horizon.\n\nCalcule l’exposition annuelle initiale.","en":"Fictional financial exercise only: impact €220000; assumed annual probability before control 0.08, after control 0.03; control €5,000/year. Same population and horizon.\n\nCalculate initial annual exposure."},"choices":[],"settings":{"unit":"€/an","toleranceLabel":{"fr":"Tolérance absolue ±52.8 €/an.","en":"Absolute tolerance ±52.8 €/an."}},"blockId":"exam_07_A_case2"},{"id":"exam_07_A_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Exercice financier fictif uniquement : impact  220000 € ; probabilité annuelle supposée avant contrôle 0,08, après contrôle 0,03 ; contrôle 5 000 €/an. Même population et horizon.\n\nCalcule l’exposition annuelle résiduelle supposée.","en":"Fictional financial exercise only: impact €220000; assumed annual probability before control 0.08, after control 0.03; control €5,000/year. Same population and horizon.\n\nCalculate assumed residual annual exposure."},"choices":[],"settings":{"unit":"€/an","toleranceLabel":{"fr":"Tolérance absolue ±19.8 €/an.","en":"Absolute tolerance ±19.8 €/an."}},"blockId":"exam_07_A_case2"},{"id":"exam_07_A_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Exercice financier fictif uniquement : impact  220000 € ; probabilité annuelle supposée avant contrôle 0,08, après contrôle 0,03 ; contrôle 5 000 €/an. Même population et horizon.\n\nCalcule la réduction nette annuelle espérée.","en":"Fictional financial exercise only: impact €220000; assumed annual probability before control 0.08, after control 0.03; control €5,000/year. Same population and horizon.\n\nCalculate expected annual net reduction."},"choices":[],"settings":{"unit":"€/an","toleranceLabel":{"fr":"Tolérance absolue ±18 €/an.","en":"Absolute tolerance ±18 €/an."}},"blockId":"exam_07_A_case2"},{"id":"exam_07_A_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Exercice financier fictif uniquement : impact  220000 € ; probabilité annuelle supposée avant contrôle 0,08, après contrôle 0,03 ; contrôle 5 000 €/an. Même population et horizon.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Fictional financial exercise only: impact €220000; assumed annual probability before control 0.08, after control 0.03; control €5,000/year. Same population and horizon.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_07_A_case2_decision_c1","position":1,"labels":{"fr":"Assimiler chiffrement et autorisation de toutes les opérations.","en":"Treat encryption as authorisation for every operation."}},{"id":"exam_07_A_case2_decision_c2","position":2,"labels":{"fr":"Traiter les probabilités comme hypothèses et vérifier efficacité, autorisation, logs et récupération du contrôle.","en":"Treat probabilities as assumptions and verify control effectiveness, authorisation, logs and recovery."}},{"id":"exam_07_A_case2_decision_c3","position":3,"labels":{"fr":"Déclarer le système sûr dès que le gain financier espéré est positif.","en":"Declare the system secure whenever expected financial benefit is positive."}}],"settings":{},"blockId":"exam_07_A_case2"},{"id":"exam_07_A_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"1500 unités entrantes ; 1420 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nCalcule le rendement de premier passage.","en":"1500 incoming units; 1420 good without rework; 50 additional units recovered by rework; remainder scrapped. Groups are disjoint.\n\nCalculate first-pass yield."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.284 %.","en":"Absolute tolerance ±0.284 %."}},"blockId":"exam_07_A_case3"},{"id":"exam_07_A_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"1500 unités entrantes ; 1420 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nCalcule le rendement final.","en":"1500 incoming units; 1420 good without rework; 50 additional units recovered by rework; remainder scrapped. Groups are disjoint.\n\nCalculate final yield."},"choices":[],"settings":{"unit":"%","toleranceLabel":{"fr":"Tolérance absolue ±0.294 %.","en":"Absolute tolerance ±0.294 %."}},"blockId":"exam_07_A_case3"},{"id":"exam_07_A_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"1500 unités entrantes ; 1420 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nCompte les unités rebutées.","en":"1500 incoming units; 1420 good without rework; 50 additional units recovered by rework; remainder scrapped. Groups are disjoint.\n\nCount scrapped units."},"choices":[],"settings":{"unit":"unités","toleranceLabel":{"fr":"Tolérance absolue ±0.01 unités.","en":"Absolute tolerance ±0.01 unités."}},"blockId":"exam_07_A_case3"},{"id":"exam_07_A_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"1500 unités entrantes ; 1420 bonnes sans reprise ; 50 autres récupérées après retouche ; le reste est rebuté. Groupes disjoints.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"1500 incoming units; 1420 good without rework; 50 additional units recovered by rework; remainder scrapped. Groups are disjoint.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_07_A_case3_decision_c1","position":1,"labels":{"fr":"Suivre premier passage, retouches et rebuts séparément, puis démontrer une cause avant correction.","en":"Track first pass, rework and scrap separately, then demonstrate a cause before correcting."}},{"id":"exam_07_A_case3_decision_c2","position":2,"labels":{"fr":"Annoncer le rendement final comme FPY et supprimer les retouches du dashboard.","en":"Call final yield FPY and remove rework from the dashboard."}},{"id":"exam_07_A_case3_decision_c3","position":3,"labels":{"fr":"Déclarer la production maîtrisée parce qu’une unité prototype a réussi.","en":"Declare production controlled because one prototype passed."}}],"settings":{},"blockId":"exam_07_A_case3"}]'::jsonb,'{"exam_07_A_case1_q1":{"answer":{"value":0.00032,"unit":"probabilité","abs_tolerance":3.2e-07},"rubric":{},"explanation":{"fr":"1. AND indépendant = 0.0003.\n2. OR indépendant = 0.0357.\n3. Avec cause commune = 0.0053.\n4. Une cause commune rend trompeur le seul produit pA×pB ; les événements et durées doivent rester cohérents. Ces probabilités ne donnent aucun ASIL.\n\nModèle probabiliste fictif ; ni taux matériel réel ni preuve de sécurité.","en":"1. Independent AND = 0.0003.\n2. Independent OR = 0.0357.\n3. Including common cause = 0.0053.\n4. A common cause makes the bare pA×pB product misleading; event definitions and durations must match. These probabilities do not assign ASIL.\n\nFictional probability model; neither real hardware failure rates nor safety evidence."}},"exam_07_A_case1_q2":{"answer":{"value":0.03568,"unit":"probabilité","abs_tolerance":3.5680000000000004e-05},"rubric":{},"explanation":{"fr":"1. AND indépendant = 0.0003.\n2. OR indépendant = 0.0357.\n3. Avec cause commune = 0.0053.\n4. Une cause commune rend trompeur le seul produit pA×pB ; les événements et durées doivent rester cohérents. Ces probabilités ne donnent aucun ASIL.\n\nModèle probabiliste fictif ; ni taux matériel réel ni preuve de sécurité.","en":"1. Independent AND = 0.0003.\n2. Independent OR = 0.0357.\n3. Including common cause = 0.0053.\n4. A common cause makes the bare pA×pB product misleading; event definitions and durations must match. These probabilities do not assign ASIL.\n\nFictional probability model; neither real hardware failure rates nor safety evidence."}},"exam_07_A_case1_q3":{"answer":{"value":0.0053184,"unit":"probabilité","abs_tolerance":5.3184e-06},"rubric":{},"explanation":{"fr":"1. AND indépendant = 0.0003.\n2. OR indépendant = 0.0357.\n3. Avec cause commune = 0.0053.\n4. Une cause commune rend trompeur le seul produit pA×pB ; les événements et durées doivent rester cohérents. Ces probabilités ne donnent aucun ASIL.\n\nModèle probabiliste fictif ; ni taux matériel réel ni preuve de sécurité.","en":"1. Independent AND = 0.0003.\n2. Independent OR = 0.0357.\n3. Including common cause = 0.0053.\n4. A common cause makes the bare pA×pB product misleading; event definitions and durations must match. These probabilities do not assign ASIL.\n\nFictional probability model; neither real hardware failure rates nor safety evidence."}},"exam_07_A_case1_decision":{"answer":{"choice_id":"exam_07_A_case1_decision_c3"},"rubric":{},"explanation":{"fr":"Vérifier définition des événements et causes communes ; garder cette analyse distincte de la classification HARA. Modèle probabiliste fictif ; ni taux matériel réel ni preuve de sécurité.","en":"Check event definitions and common causes; keep this calculation distinct from HARA classification. Fictional probability model; neither real hardware failure rates nor safety evidence."}},"exam_07_A_case2_q1":{"answer":{"value":17600.0,"unit":"€/an","abs_tolerance":52.800000000000004},"rubric":{},"explanation":{"fr":"1. Exposition avant = 0,08×220000 = 17600 €/an.\n2. Après = 0,03×220000 = 6600 €/an.\n3. Gain net espéré = 17600−6600−5000 = 6000 €/an.\n4. Ce gain dépend d’une réduction de probabilité supposée ; la sécurité exige objectifs, tests et risque résiduel.\n\nLes probabilités d’attaque sont fictives ; aucune décision de conformité réelle n’en découle.","en":"1. Exposure before = 0.08×220000 = €17600/year.\n2. After = 0.03×220000 = €6600/year.\n3. Expected net benefit = 17600−6600−5000 = €6000/year.\n4. Benefit depends on an assumed probability reduction; security needs objectives, tests and residual-risk analysis.\n\nAttack probabilities are fictional; no actual compliance decision follows."}},"exam_07_A_case2_q2":{"answer":{"value":6600.0,"unit":"€/an","abs_tolerance":19.8},"rubric":{},"explanation":{"fr":"1. Exposition avant = 0,08×220000 = 17600 €/an.\n2. Après = 0,03×220000 = 6600 €/an.\n3. Gain net espéré = 17600−6600−5000 = 6000 €/an.\n4. Ce gain dépend d’une réduction de probabilité supposée ; la sécurité exige objectifs, tests et risque résiduel.\n\nLes probabilités d’attaque sont fictives ; aucune décision de conformité réelle n’en découle.","en":"1. Exposure before = 0.08×220000 = €17600/year.\n2. After = 0.03×220000 = €6600/year.\n3. Expected net benefit = 17600−6600−5000 = €6000/year.\n4. Benefit depends on an assumed probability reduction; security needs objectives, tests and residual-risk analysis.\n\nAttack probabilities are fictional; no actual compliance decision follows."}},"exam_07_A_case2_q3":{"answer":{"value":6000.0,"unit":"€/an","abs_tolerance":18.0},"rubric":{},"explanation":{"fr":"1. Exposition avant = 0,08×220000 = 17600 €/an.\n2. Après = 0,03×220000 = 6600 €/an.\n3. Gain net espéré = 17600−6600−5000 = 6000 €/an.\n4. Ce gain dépend d’une réduction de probabilité supposée ; la sécurité exige objectifs, tests et risque résiduel.\n\nLes probabilités d’attaque sont fictives ; aucune décision de conformité réelle n’en découle.","en":"1. Exposure before = 0.08×220000 = €17600/year.\n2. After = 0.03×220000 = €6600/year.\n3. Expected net benefit = 17600−6600−5000 = €6000/year.\n4. Benefit depends on an assumed probability reduction; security needs objectives, tests and residual-risk analysis.\n\nAttack probabilities are fictional; no actual compliance decision follows."}},"exam_07_A_case2_decision":{"answer":{"choice_id":"exam_07_A_case2_decision_c2"},"rubric":{},"explanation":{"fr":"Traiter les probabilités comme hypothèses et vérifier efficacité, autorisation, logs et récupération du contrôle. Les probabilités d’attaque sont fictives ; aucune décision de conformité réelle n’en découle.","en":"Treat probabilities as assumptions and verify control effectiveness, authorisation, logs and recovery. Attack probabilities are fictional; no actual compliance decision follows."}},"exam_07_A_case3_q1":{"answer":{"value":94.66666666666667,"unit":"%","abs_tolerance":0.28400000000000003},"rubric":{},"explanation":{"fr":"1. FPY = 1420/1500×100 = 94.6667 %.\n2. Rendement final = (1420+50)/1500×100 = 98 %.\n3. Rebuts = 1500−1420−50 = 30.\n4. Les 50 reprises coûtent du temps et des ressources, même si elles sont finalement bonnes.\n\nLe rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"1. FPY = 1420/1500×100 = 94.6667%.\n2. Final yield = (1420+50)/1500×100 = 98%.\n3. Scrap = 1500−1420−50 = 30.\n4. Rework consumes time and resources even when the units ultimately pass.\n\nYield alone establishes neither capability nor process stability."}},"exam_07_A_case3_q2":{"answer":{"value":98.0,"unit":"%","abs_tolerance":0.294},"rubric":{},"explanation":{"fr":"1. FPY = 1420/1500×100 = 94.6667 %.\n2. Rendement final = (1420+50)/1500×100 = 98 %.\n3. Rebuts = 1500−1420−50 = 30.\n4. Les 50 reprises coûtent du temps et des ressources, même si elles sont finalement bonnes.\n\nLe rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"1. FPY = 1420/1500×100 = 94.6667%.\n2. Final yield = (1420+50)/1500×100 = 98%.\n3. Scrap = 1500−1420−50 = 30.\n4. Rework consumes time and resources even when the units ultimately pass.\n\nYield alone establishes neither capability nor process stability."}},"exam_07_A_case3_q3":{"answer":{"value":30,"unit":"unités","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. FPY = 1420/1500×100 = 94.6667 %.\n2. Rendement final = (1420+50)/1500×100 = 98 %.\n3. Rebuts = 1500−1420−50 = 30.\n4. Les 50 reprises coûtent du temps et des ressources, même si elles sont finalement bonnes.\n\nLe rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"1. FPY = 1420/1500×100 = 94.6667%.\n2. Final yield = (1420+50)/1500×100 = 98%.\n3. Scrap = 1500−1420−50 = 30.\n4. Rework consumes time and resources even when the units ultimately pass.\n\nYield alone establishes neither capability nor process stability."}},"exam_07_A_case3_decision":{"answer":{"choice_id":"exam_07_A_case3_decision_c1"},"rubric":{},"explanation":{"fr":"Suivre premier passage, retouches et rebuts séparément, puis démontrer une cause avant correction. Le rendement seul ne démontre ni capabilité ni stabilité du procédé.","en":"Track first pass, rework and scrap separately, then demonstrate a cause before correcting. Yield alone establishes neither capability nor process stability."}}}'::jsonb) ON CONFLICT DO NOTHING;
