INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_08','A','[{"id":"exam_08_A_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Option A : NRE 30 000 €, coût unitaire 122 €. Option B : NRE 80 000 €, coût unitaire 109 €. Volume 4400 unités ; mêmes fonctions et admissibilité supposées ; pas d’actualisation.\n\nCalcule le coût total A.","en":"Option A: NRE €30,000, unit cost €122. Option B: NRE €80,000, unit cost €109. Volume 4400; equivalent required functions and feasibility assumed; no discounting.\n\nCalculate total A cost."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±1700.4 €.","en":"Absolute tolerance ±1700.4 €."}},"blockId":"exam_08_A_case1"},{"id":"exam_08_A_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Option A : NRE 30 000 €, coût unitaire 122 €. Option B : NRE 80 000 €, coût unitaire 109 €. Volume 4400 unités ; mêmes fonctions et admissibilité supposées ; pas d’actualisation.\n\nCalcule le coût total B.","en":"Option A: NRE €30,000, unit cost €122. Option B: NRE €80,000, unit cost €109. Volume 4400; equivalent required functions and feasibility assumed; no discounting.\n\nCalculate total B cost."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±1678.8 €.","en":"Absolute tolerance ±1678.8 €."}},"blockId":"exam_08_A_case1"},{"id":"exam_08_A_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Option A : NRE 30 000 €, coût unitaire 122 €. Option B : NRE 80 000 €, coût unitaire 109 €. Volume 4400 unités ; mêmes fonctions et admissibilité supposées ; pas d’actualisation.\n\nCalcule le volume de croisement.","en":"Option A: NRE €30,000, unit cost €122. Option B: NRE €80,000, unit cost €109. Volume 4400; equivalent required functions and feasibility assumed; no discounting.\n\nCalculate break-even volume."},"choices":[],"settings":{"unit":"unités","toleranceLabel":{"fr":"Tolérance absolue ±0.01 unités.","en":"Absolute tolerance ±0.01 unités."}},"blockId":"exam_08_A_case1"},{"id":"exam_08_A_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Option A : NRE 30 000 €, coût unitaire 122 €. Option B : NRE 80 000 €, coût unitaire 109 €. Volume 4400 unités ; mêmes fonctions et admissibilité supposées ; pas d’actualisation.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Option A: NRE €30,000, unit cost €122. Option B: NRE €80,000, unit cost €109. Volume 4400; equivalent required functions and feasibility assumed; no discounting.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_08_A_case1_decision_c1","position":1,"labels":{"fr":"Retenir une option non admissible parce que son score économique est meilleur.","en":"Choose an infeasible option because its economic score is better."}},{"id":"exam_08_A_case1_decision_c2","position":2,"labels":{"fr":"Vérifier volume, délai, capacité, qualité et coûts exclus avant de retenir le coût total le plus faible.","en":"Check volume, schedule, capacity, quality and excluded costs before choosing the lower total."}},{"id":"exam_08_A_case1_decision_c3","position":3,"labels":{"fr":"Choisir systématiquement le coût unitaire le plus faible, quel que soit le NRE et le volume.","en":"Always choose the lower unit cost regardless of NRE and volume."}}],"settings":{},"blockId":"exam_08_A_case1"},{"id":"exam_08_A_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Idée VA/VE : économie récurrente 4 €/unité, volume effectif 23000, développement et qualification fixes 25 000 €. Fonctions obligatoires supposées préservées pour le calcul, à prouver.\n\nCalcule le gain brut.","en":"VA/VE proposal: recurring saving €4/unit, effective volume 23000, fixed development and qualification €25,000. Required functions assumed preserved for calculation, still to be proven.\n\nCalculate gross saving."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±276 €.","en":"Absolute tolerance ±276 €."}},"blockId":"exam_08_A_case2"},{"id":"exam_08_A_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Idée VA/VE : économie récurrente 4 €/unité, volume effectif 23000, développement et qualification fixes 25 000 €. Fonctions obligatoires supposées préservées pour le calcul, à prouver.\n\nCalcule le gain net simple.","en":"VA/VE proposal: recurring saving €4/unit, effective volume 23000, fixed development and qualification €25,000. Required functions assumed preserved for calculation, still to be proven.\n\nCalculate simple net saving."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±201 €.","en":"Absolute tolerance ±201 €."}},"blockId":"exam_08_A_case2"},{"id":"exam_08_A_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Idée VA/VE : économie récurrente 4 €/unité, volume effectif 23000, développement et qualification fixes 25 000 €. Fonctions obligatoires supposées préservées pour le calcul, à prouver.\n\nCalcule le seuil de volume.","en":"VA/VE proposal: recurring saving €4/unit, effective volume 23000, fixed development and qualification €25,000. Required functions assumed preserved for calculation, still to be proven.\n\nCalculate break-even volume."},"choices":[],"settings":{"unit":"unités","toleranceLabel":{"fr":"Tolérance absolue ±0.01 unités.","en":"Absolute tolerance ±0.01 unités."}},"blockId":"exam_08_A_case2"},{"id":"exam_08_A_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Idée VA/VE : économie récurrente 4 €/unité, volume effectif 23000, développement et qualification fixes 25 000 €. Fonctions obligatoires supposées préservées pour le calcul, à prouver.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"VA/VE proposal: recurring saving €4/unit, effective volume 23000, fixed development and qualification €25,000. Required functions assumed preserved for calculation, still to be proven.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_08_A_case2_decision_c1","position":1,"labels":{"fr":"Valider les fonctions et les interfaces après modification, puis mesurer l’économie sur la population effective.","en":"Validate functions and interfaces after change, then measure savings on the effective population."}},{"id":"exam_08_A_case2_decision_c2","position":2,"labels":{"fr":"Compter le gain brut comme net en omettant le développement déjà connu.","en":"Count gross as net by omitting known development costs."}},{"id":"exam_08_A_case2_decision_c3","position":3,"labels":{"fr":"Supprimer une fonction obligatoire pour atteindre la réduction de coût puis déclarer une hausse de valeur.","en":"Delete a mandatory function to cut cost and claim higher value."}}],"settings":{},"blockId":"exam_08_A_case2"},{"id":"exam_08_A_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 125000 €, EV 104000 €, AC 135000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule le CPI.","en":"At status date: PV €125000, EV €104000, AC €135000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate CPI."},"choices":[],"settings":{"unit":"ratio","toleranceLabel":{"fr":"Tolérance absolue ±0.00231111 ratio.","en":"Absolute tolerance ±0.00231111 ratio."}},"blockId":"exam_08_A_case3"},{"id":"exam_08_A_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 125000 €, EV 104000 €, AC 135000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule le SPI.","en":"At status date: PV €125000, EV €104000, AC €135000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate SPI."},"choices":[],"settings":{"unit":"ratio","toleranceLabel":{"fr":"Tolérance absolue ±0.002496 ratio.","en":"Absolute tolerance ±0.002496 ratio."}},"blockId":"exam_08_A_case3"},{"id":"exam_08_A_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 125000 €, EV 104000 €, AC 135000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nCalcule EAC avec la méthode imposée.","en":"At status date: PV €125000, EV €104000, AC €135000, BAC €600,000. For EAC assume constant future CPI.\n\nCalculate EAC with the stated method."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±2336.54 €.","en":"Absolute tolerance ±2336.54 €."}},"blockId":"exam_08_A_case3"},{"id":"exam_08_A_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"À la date de référence : PV 125000 €, EV 104000 €, AC 135000 €, BAC 600 000 €. Pour EAC, supposer le CPI constant jusqu’à la fin.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"At status date: PV €125000, EV €104000, AC €135000, BAC €600,000. For EAC assume constant future CPI.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_08_A_case3_decision_c1","position":1,"labels":{"fr":"Déclarer le programme techniquement validé parce que EV est positif.","en":"Declare technical validation because EV is positive."}},{"id":"exam_08_A_case3_decision_c2","position":2,"labels":{"fr":"Utiliser SPI comme facteur de conversion certain vers une date de fin.","en":"Use SPI as a certain conversion factor to a completion date."}},{"id":"exam_08_A_case3_decision_c3","position":3,"labels":{"fr":"Analyser les livrables acquis, le chemin critique et l’hypothèse de forecast avant de décider.","en":"Examine earned deliverables, critical path and forecast assumptions before deciding."}}],"settings":{},"blockId":"exam_08_A_case3"}]'::jsonb,'{"exam_08_A_case1_q1":{"answer":{"value":566800,"unit":"€","abs_tolerance":1700.4},"rubric":{},"explanation":{"fr":"1. Total A = 30000+122×4400 = 566800 €.\n2. Total B = 80000+109×4400 = 559600 €.\n3. Croisement = (80000−30000)/(122−109) = 3846.1538 unités.\n4. Le choix économique s’inverse autour de ce seuil si les autres hypothèses tiennent.\n\nService, garantie et délai sont exclus ; les hypothèses d’admissibilité doivent être vérifiées.","en":"1. A total = 30000+122×4400 = €566800.\n2. B total = 80000+109×4400 = €559600.\n3. Break-even = (80000−30000)/(122−109) = 3846.1538 units.\n4. Economic ranking reverses around this threshold if other assumptions hold.\n\nService, warranty and schedule costs are excluded; feasibility assumptions need verification."}},"exam_08_A_case1_q2":{"answer":{"value":559600,"unit":"€","abs_tolerance":1678.8},"rubric":{},"explanation":{"fr":"1. Total A = 30000+122×4400 = 566800 €.\n2. Total B = 80000+109×4400 = 559600 €.\n3. Croisement = (80000−30000)/(122−109) = 3846.1538 unités.\n4. Le choix économique s’inverse autour de ce seuil si les autres hypothèses tiennent.\n\nService, garantie et délai sont exclus ; les hypothèses d’admissibilité doivent être vérifiées.","en":"1. A total = 30000+122×4400 = €566800.\n2. B total = 80000+109×4400 = €559600.\n3. Break-even = (80000−30000)/(122−109) = 3846.1538 units.\n4. Economic ranking reverses around this threshold if other assumptions hold.\n\nService, warranty and schedule costs are excluded; feasibility assumptions need verification."}},"exam_08_A_case1_q3":{"answer":{"value":3846.153846153846,"unit":"unités","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Total A = 30000+122×4400 = 566800 €.\n2. Total B = 80000+109×4400 = 559600 €.\n3. Croisement = (80000−30000)/(122−109) = 3846.1538 unités.\n4. Le choix économique s’inverse autour de ce seuil si les autres hypothèses tiennent.\n\nService, garantie et délai sont exclus ; les hypothèses d’admissibilité doivent être vérifiées.","en":"1. A total = 30000+122×4400 = €566800.\n2. B total = 80000+109×4400 = €559600.\n3. Break-even = (80000−30000)/(122−109) = 3846.1538 units.\n4. Economic ranking reverses around this threshold if other assumptions hold.\n\nService, warranty and schedule costs are excluded; feasibility assumptions need verification."}},"exam_08_A_case1_decision":{"answer":{"choice_id":"exam_08_A_case1_decision_c2"},"rubric":{},"explanation":{"fr":"Vérifier volume, délai, capacité, qualité et coûts exclus avant de retenir le coût total le plus faible. Service, garantie et délai sont exclus ; les hypothèses d’admissibilité doivent être vérifiées.","en":"Check volume, schedule, capacity, quality and excluded costs before choosing the lower total. Service, warranty and schedule costs are excluded; feasibility assumptions need verification."}},"exam_08_A_case2_q1":{"answer":{"value":92000.0,"unit":"€","abs_tolerance":276.0},"rubric":{},"explanation":{"fr":"1. Gain brut = 23000×4 = 92000 €.\n2. Gain net simple = 92000−25000 = 67000 €.\n3. Volume de retour simple = 25000/4 = 6250 unités.\n4. Vérifier durabilité, assemblage, service et effectivité avant de comptabiliser le gain comme acquis.\n\nPas d’actualisation, de coût délai ou de variation de taux de rebut dans ce premier calcul.","en":"1. Gross saving = 23000×4 = €92000.\n2. Simple net saving = 92000−25000 = €67000.\n3. Simple break-even volume = 25000/4 = 6250 units.\n4. Verify durability, assembly, service and effectivity before recognising realised savings.\n\nNo discounting, schedule cost or scrap-rate changes in this initial calculation."}},"exam_08_A_case2_q2":{"answer":{"value":67000.0,"unit":"€","abs_tolerance":201.0},"rubric":{},"explanation":{"fr":"1. Gain brut = 23000×4 = 92000 €.\n2. Gain net simple = 92000−25000 = 67000 €.\n3. Volume de retour simple = 25000/4 = 6250 unités.\n4. Vérifier durabilité, assemblage, service et effectivité avant de comptabiliser le gain comme acquis.\n\nPas d’actualisation, de coût délai ou de variation de taux de rebut dans ce premier calcul.","en":"1. Gross saving = 23000×4 = €92000.\n2. Simple net saving = 92000−25000 = €67000.\n3. Simple break-even volume = 25000/4 = 6250 units.\n4. Verify durability, assembly, service and effectivity before recognising realised savings.\n\nNo discounting, schedule cost or scrap-rate changes in this initial calculation."}},"exam_08_A_case2_q3":{"answer":{"value":6250.0,"unit":"unités","abs_tolerance":0.01},"rubric":{},"explanation":{"fr":"1. Gain brut = 23000×4 = 92000 €.\n2. Gain net simple = 92000−25000 = 67000 €.\n3. Volume de retour simple = 25000/4 = 6250 unités.\n4. Vérifier durabilité, assemblage, service et effectivité avant de comptabiliser le gain comme acquis.\n\nPas d’actualisation, de coût délai ou de variation de taux de rebut dans ce premier calcul.","en":"1. Gross saving = 23000×4 = €92000.\n2. Simple net saving = 92000−25000 = €67000.\n3. Simple break-even volume = 25000/4 = 6250 units.\n4. Verify durability, assembly, service and effectivity before recognising realised savings.\n\nNo discounting, schedule cost or scrap-rate changes in this initial calculation."}},"exam_08_A_case2_decision":{"answer":{"choice_id":"exam_08_A_case2_decision_c1"},"rubric":{},"explanation":{"fr":"Valider les fonctions et les interfaces après modification, puis mesurer l’économie sur la population effective. Pas d’actualisation, de coût délai ou de variation de taux de rebut dans ce premier calcul.","en":"Validate functions and interfaces after change, then measure savings on the effective population. No discounting, schedule cost or scrap-rate changes in this initial calculation."}},"exam_08_A_case3_q1":{"answer":{"value":0.7703703703703704,"unit":"ratio","abs_tolerance":0.002311111111111111},"rubric":{},"explanation":{"fr":"1. CPI = 104000/135000 = 0.7704.\n2. SPI = 104000/125000 = 0.832.\n3. EAC = 600000/0.7704 ≈ 778846.1538 €.\n4. CPI < 1 indique un coût supérieur au budget de la valeur acquise ; SPI ne prouve pas la date finale.\n\nLe forecast suppose la poursuite de l’efficacité de coût observée.","en":"1. CPI = 104000/135000 = 0.7704.\n2. SPI = 104000/125000 = 0.832.\n3. EAC = 600000/0.7704 ≈ €778846.1538.\n4. CPI < 1 indicates earned work cost more than its budget; SPI does not establish completion date.\n\nForecast assumes observed cost efficiency continues."}},"exam_08_A_case3_q2":{"answer":{"value":0.832,"unit":"ratio","abs_tolerance":0.002496},"rubric":{},"explanation":{"fr":"1. CPI = 104000/135000 = 0.7704.\n2. SPI = 104000/125000 = 0.832.\n3. EAC = 600000/0.7704 ≈ 778846.1538 €.\n4. CPI < 1 indique un coût supérieur au budget de la valeur acquise ; SPI ne prouve pas la date finale.\n\nLe forecast suppose la poursuite de l’efficacité de coût observée.","en":"1. CPI = 104000/135000 = 0.7704.\n2. SPI = 104000/125000 = 0.832.\n3. EAC = 600000/0.7704 ≈ €778846.1538.\n4. CPI < 1 indicates earned work cost more than its budget; SPI does not establish completion date.\n\nForecast assumes observed cost efficiency continues."}},"exam_08_A_case3_q3":{"answer":{"value":778846.1538461539,"unit":"€","abs_tolerance":2336.538461538462},"rubric":{},"explanation":{"fr":"1. CPI = 104000/135000 = 0.7704.\n2. SPI = 104000/125000 = 0.832.\n3. EAC = 600000/0.7704 ≈ 778846.1538 €.\n4. CPI < 1 indique un coût supérieur au budget de la valeur acquise ; SPI ne prouve pas la date finale.\n\nLe forecast suppose la poursuite de l’efficacité de coût observée.","en":"1. CPI = 104000/135000 = 0.7704.\n2. SPI = 104000/125000 = 0.832.\n3. EAC = 600000/0.7704 ≈ €778846.1538.\n4. CPI < 1 indicates earned work cost more than its budget; SPI does not establish completion date.\n\nForecast assumes observed cost efficiency continues."}},"exam_08_A_case3_decision":{"answer":{"choice_id":"exam_08_A_case3_decision_c3"},"rubric":{},"explanation":{"fr":"Analyser les livrables acquis, le chemin critique et l’hypothèse de forecast avant de décider. Le forecast suppose la poursuite de l’efficacité de coût observée.","en":"Examine earned deliverables, critical path and forecast assumptions before deciding. Forecast assumes observed cost efficiency continues."}}}'::jsonb) ON CONFLICT DO NOTHING;
