INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_10','A','[{"id":"exam_10_A_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1225 kg ; vitesse 72 km/h ; pente 8 % ; Crr 0,012 ; ρ 1,225 kg/m³ ; CdA 0,64 m² ; rayon 0,28 m ; rapport 9 ; ηréducteur 0,95 ; ηglobal batterie-roues 0,90 ; auxiliaires 0,8 kW ; a = 0 ; sans vent.\n\nCalcule la puissance mécanique machine.","en":"Mass 1225 kg; speed 72 km/h; grade 8%; Crr 0.012; ρ 1.225 kg/m³; CdA 0.64 m²; radius 0.28 m; ratio 9; gear efficiency 0.95; overall battery-wheel efficiency 0.90; auxiliaries 0.8 kW; a = 0; still air.\n\nCalculate machine mechanical power."},"choices":[],"settings":{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0795073 kW.","en":"Absolute tolerance ±0.0795073 kW."}},"blockId":"exam_10_A_case1"},{"id":"exam_10_A_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1225 kg ; vitesse 72 km/h ; pente 8 % ; Crr 0,012 ; ρ 1,225 kg/m³ ; CdA 0,64 m² ; rayon 0,28 m ; rapport 9 ; ηréducteur 0,95 ; ηglobal batterie-roues 0,90 ; auxiliaires 0,8 kW ; a = 0 ; sans vent.\n\nCalcule la puissance électrique batterie, auxiliaires compris.","en":"Mass 1225 kg; speed 72 km/h; grade 8%; Crr 0.012; ρ 1.225 kg/m³; CdA 0.64 m²; radius 0.28 m; ratio 9; gear efficiency 0.95; overall battery-wheel efficiency 0.90; auxiliaries 0.8 kW; a = 0; still air.\n\nCalculate battery electrical power including auxiliaries."},"choices":[],"settings":{"unit":"kW","toleranceLabel":{"fr":"Tolérance absolue ±0.0863244 kW.","en":"Absolute tolerance ±0.0863244 kW."}},"blockId":"exam_10_A_case1"},{"id":"exam_10_A_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1225 kg ; vitesse 72 km/h ; pente 8 % ; Crr 0,012 ; ρ 1,225 kg/m³ ; CdA 0,64 m² ; rayon 0,28 m ; rapport 9 ; ηréducteur 0,95 ; ηglobal batterie-roues 0,90 ; auxiliaires 0,8 kW ; a = 0 ; sans vent.\n\nCalcule le régime machine.","en":"Mass 1225 kg; speed 72 km/h; grade 8%; Crr 0.012; ρ 1.225 kg/m³; CdA 0.64 m²; radius 0.28 m; ratio 9; gear efficiency 0.95; overall battery-wheel efficiency 0.90; auxiliaries 0.8 kW; a = 0; still air.\n\nCalculate machine speed."},"choices":[],"settings":{"unit":"tr/min","toleranceLabel":{"fr":"Tolérance absolue ±18.4165 tr/min.","en":"Absolute tolerance ±18.4165 tr/min."}},"blockId":"exam_10_A_case1"},{"id":"exam_10_A_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Masse 1225 kg ; vitesse 72 km/h ; pente 8 % ; Crr 0,012 ; ρ 1,225 kg/m³ ; CdA 0,64 m² ; rayon 0,28 m ; rapport 9 ; ηréducteur 0,95 ; ηglobal batterie-roues 0,90 ; auxiliaires 0,8 kW ; a = 0 ; sans vent.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Mass 1225 kg; speed 72 km/h; grade 8%; Crr 0.012; ρ 1.225 kg/m³; CdA 0.64 m²; radius 0.28 m; ratio 9; gear efficiency 0.95; overall battery-wheel efficiency 0.90; auxiliaries 0.8 kW; a = 0; still air.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_10_A_case1_decision_c1","position":1,"labels":{"fr":"Valider le moteur avec sa puissance crête, même si la durée admissible est inconnue.","en":"Approve using peak power even though its admissible duration is unknown."}},{"id":"exam_10_A_case1_decision_c2","position":2,"labels":{"fr":"Diviser la puissance roues par 0,95 puis par 0,90 avant d’ajouter les auxiliaires.","en":"Divide wheel power by 0.95 and then by 0.90 before adding auxiliaries."}},{"id":"exam_10_A_case1_decision_c3","position":3,"labels":{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection."}}],"settings":{},"blockId":"exam_10_A_case1"},{"id":"exam_10_A_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 30 kWh ; fenêtre utile 80 % ; consommation nominale 158 Wh/km, scénario dégradé 178 Wh/km ; cible 150 km.\n\nCalcule l’autonomie nominale.","en":"Gross battery 30 kWh; usable window 80%; nominal consumption 158 Wh/km, degraded case 178 Wh/km; target 150 km.\n\nCalculate nominal range."},"choices":[],"settings":{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.455696 km.","en":"Absolute tolerance ±0.455696 km."}},"blockId":"exam_10_A_case2"},{"id":"exam_10_A_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 30 kWh ; fenêtre utile 80 % ; consommation nominale 158 Wh/km, scénario dégradé 178 Wh/km ; cible 150 km.\n\nCalcule l’autonomie dans le scénario dégradé.","en":"Gross battery 30 kWh; usable window 80%; nominal consumption 158 Wh/km, degraded case 178 Wh/km; target 150 km.\n\nCalculate degraded-case range."},"choices":[],"settings":{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.404494 km.","en":"Absolute tolerance ±0.404494 km."}},"blockId":"exam_10_A_case2"},{"id":"exam_10_A_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 30 kWh ; fenêtre utile 80 % ; consommation nominale 158 Wh/km, scénario dégradé 178 Wh/km ; cible 150 km.\n\nCalcule l’énergie utile nécessaire pour 150 km dégradés.","en":"Gross battery 30 kWh; usable window 80%; nominal consumption 158 Wh/km, degraded case 178 Wh/km; target 150 km.\n\nCalculate usable energy needed for 150 degraded kilometres."},"choices":[],"settings":{"unit":"kWh","toleranceLabel":{"fr":"Tolérance absolue ±0.0801 kWh.","en":"Absolute tolerance ±0.0801 kWh."}},"blockId":"exam_10_A_case2"},{"id":"exam_10_A_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 30 kWh ; fenêtre utile 80 % ; consommation nominale 158 Wh/km, scénario dégradé 178 Wh/km ; cible 150 km.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Gross battery 30 kWh; usable window 80%; nominal consumption 158 Wh/km, degraded case 178 Wh/km; target 150 km.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_10_A_case2_decision_c1","position":1,"labels":{"fr":"Moyenner les deux autonomies pour déclarer la cible satisfaite dans les deux cas.","en":"Average both ranges to declare that both scenarios meet the target."}},{"id":"exam_10_A_case2_decision_c2","position":2,"labels":{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity."}},{"id":"exam_10_A_case2_decision_c3","position":3,"labels":{"fr":"Utiliser l’énergie brute pour tous les scénarios, puisque la fenêtre ne change que la recharge.","en":"Use gross energy in every scenario because the window only affects charging."}}],"settings":{},"blockId":"exam_10_A_case2"},{"id":"exam_10_A_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 60 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule le délai de chaîne.","en":"Camera 60 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate chain delay."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.75 ms.","en":"Absolute tolerance ±0.75 ms."}},"blockId":"exam_10_A_case3"},{"id":"exam_10_A_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 60 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule la marge nominale.","en":"Camera 60 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate nominal margin."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.15 ms.","en":"Absolute tolerance ±0.15 ms."}},"blockId":"exam_10_A_case3"},{"id":"exam_10_A_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 60 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule le budget fusion maximal.","en":"Camera 60 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate maximum fusion budget."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.225 ms.","en":"Absolute tolerance ±0.225 ms."}},"blockId":"exam_10_A_case3"},{"id":"exam_10_A_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 60 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Camera 60 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_10_A_case3_decision_c1","position":1,"labels":{"fr":"Définir endpoints et pire cas avant de considérer la marge nominale comme une preuve de deadline.","en":"Define endpoints and worst case before treating nominal margin as deadline evidence."}},{"id":"exam_10_A_case3_decision_c2","position":2,"labels":{"fr":"Additionner caméra et radar même si les acquisitions sont parallèles dans le modèle donné.","en":"Add camera and radar times even though acquisition is parallel in this model."}},{"id":"exam_10_A_case3_decision_c3","position":3,"labels":{"fr":"Utiliser seulement le maximum de tous les temps, y compris ceux en série.","en":"Use only the maximum of all delays, including sequential stages."}}],"settings":{},"blockId":"exam_10_A_case3"}]'::jsonb,'{"exam_10_A_case1_q1":{"answer":{"value":26.502442386335133,"unit":"kW","abs_tolerance":0.0795073271590054},"rubric":{},"explanation":{"fr":"1. v = 20 m/s ; θ = 0.0798 rad.\n2. Roulement 143.7477 N ; aéro 156.8 N ; pente 958.3183 N.\n3. Total 1258.866 N ; roues 25.1773 kW.\n4. Machine 26.5024 kW ; batterie 28.7748 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6138.8335 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 20 m/s; θ = 0.0798 rad.\n2. Rolling 143.7477 N; drag 156.8 N; grade 958.3183 N.\n3. Total 1258.866 N; wheel power 25.1773 kW.\n4. Machine 26.5024 kW; battery 28.7748 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6138.8335 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}},"exam_10_A_case1_q2":{"answer":{"value":28.774800296687083,"unit":"kW","abs_tolerance":0.08632440089006126},"rubric":{},"explanation":{"fr":"1. v = 20 m/s ; θ = 0.0798 rad.\n2. Roulement 143.7477 N ; aéro 156.8 N ; pente 958.3183 N.\n3. Total 1258.866 N ; roues 25.1773 kW.\n4. Machine 26.5024 kW ; batterie 28.7748 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6138.8335 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 20 m/s; θ = 0.0798 rad.\n2. Rolling 143.7477 N; drag 156.8 N; grade 958.3183 N.\n3. Total 1258.866 N; wheel power 25.1773 kW.\n4. Machine 26.5024 kW; battery 28.7748 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6138.8335 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}},"exam_10_A_case1_q3":{"answer":{"value":6138.833519258819,"unit":"tr/min","abs_tolerance":18.41650055777646},"rubric":{},"explanation":{"fr":"1. v = 20 m/s ; θ = 0.0798 rad.\n2. Roulement 143.7477 N ; aéro 156.8 N ; pente 958.3183 N.\n3. Total 1258.866 N ; roues 25.1773 kW.\n4. Machine 26.5024 kW ; batterie 28.7748 kW. Les deux rendements ne se divisent pas successivement : le global inclut la chaîne.\n5. Régime machine 60vi/(2πr) = 6138.8335 tr/min.\n\nRendements constants, inerties tournantes et transitoires omis.","en":"1. v = 20 m/s; θ = 0.0798 rad.\n2. Rolling 143.7477 N; drag 156.8 N; grade 958.3183 N.\n3. Total 1258.866 N; wheel power 25.1773 kW.\n4. Machine 26.5024 kW; battery 28.7748 kW. Do not divide sequentially by both efficiencies: the overall value already covers the chain.\n5. Machine speed 60vi/(2πr) = 6138.8335 rpm.\n\nConstant efficiencies; rotating inertia and transients omitted."}},"exam_10_A_case1_decision":{"answer":{"choice_id":"exam_10_A_case1_decision_c3"},"rubric":{},"explanation":{"fr":"Vérifier puissance continue, couple-régime et thermique ; le seul calcul de puissance ne clôture pas le choix moteur. Rendements constants, inerties tournantes et transitoires omis.","en":"Check continuous power, torque-speed envelope and thermal behaviour; power alone cannot close motor selection. Constant efficiencies; rotating inertia and transients omitted."}},"exam_10_A_case2_q1":{"answer":{"value":151.8987341772152,"unit":"km","abs_tolerance":0.4556962025316456},"rubric":{},"explanation":{"fr":"1. Énergie utile : 30 × 0,80 = 24 kWh.\n2. Convertir en Wh : 24000 Wh.\n3. Autonomie nominale : 24000 / 158 = 151.8987 km.\n4. Autonomie dégradée : 24000 / 178 = 134.8315 km.\n5. Besoin utile pour 150 km dégradés : 150 × 178/1000 = 26.7 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 30 × 0.80 = 24 kWh.\n2. Convert to Wh: 24000 Wh.\n3. Nominal range: 24000 / 158 = 151.8987 km.\n4. Degraded range: 24000 / 178 = 134.8315 km.\n5. Usable energy for 150 degraded kilometres: 150 × 178/1000 = 26.7 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}},"exam_10_A_case2_q2":{"answer":{"value":134.8314606741573,"unit":"km","abs_tolerance":0.40449438202247195},"rubric":{},"explanation":{"fr":"1. Énergie utile : 30 × 0,80 = 24 kWh.\n2. Convertir en Wh : 24000 Wh.\n3. Autonomie nominale : 24000 / 158 = 151.8987 km.\n4. Autonomie dégradée : 24000 / 178 = 134.8315 km.\n5. Besoin utile pour 150 km dégradés : 150 × 178/1000 = 26.7 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 30 × 0.80 = 24 kWh.\n2. Convert to Wh: 24000 Wh.\n3. Nominal range: 24000 / 158 = 151.8987 km.\n4. Degraded range: 24000 / 178 = 134.8315 km.\n5. Usable energy for 150 degraded kilometres: 150 × 178/1000 = 26.7 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}},"exam_10_A_case2_q3":{"answer":{"value":26.7,"unit":"kWh","abs_tolerance":0.0801},"rubric":{},"explanation":{"fr":"1. Énergie utile : 30 × 0,80 = 24 kWh.\n2. Convertir en Wh : 24000 Wh.\n3. Autonomie nominale : 24000 / 158 = 151.8987 km.\n4. Autonomie dégradée : 24000 / 178 = 134.8315 km.\n5. Besoin utile pour 150 km dégradés : 150 × 178/1000 = 26.7 kWh. Comparer séparément chaque scénario à 150 km.\n\nLa consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"1. Usable energy: 30 × 0.80 = 24 kWh.\n2. Convert to Wh: 24000 Wh.\n3. Nominal range: 24000 / 158 = 151.8987 km.\n4. Degraded range: 24000 / 178 = 134.8315 km.\n5. Usable energy for 150 degraded kilometres: 150 × 178/1000 = 26.7 kWh. Compare each scenario separately with 150 km.\n\nConsumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}},"exam_10_A_case2_decision":{"answer":{"choice_id":"exam_10_A_case2_decision_c2"},"rubric":{},"explanation":{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie. La consommation est supposée constante et indépendante de la masse ; le résultat ne prouve pas une autonomie sur cycle réel.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity. Consumption is assumed constant and independent of mass; this does not establish actual drive-cycle range."}},"exam_10_A_case3_q1":{"answer":{"value":250,"unit":"ms","abs_tolerance":0.75},"rubric":{},"explanation":{"fr":"1. Acquisition limitante : max(60,40) = 60 ms.\n2. Chaîne = 60+20+25+15+10+120 = 250 ms.\n3. Marge nominale = 300−250 = 50 ms.\n4. Budget fusion maximal, autres temps inchangés : 75 ms.\n5. Un délai de file ou une donnée déjà âgée exige une extension du modèle.\n\nPas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"1. Limiting acquisition: max(60,40) = 60 ms.\n2. Chain = 60+20+25+15+10+120 = 250 ms.\n3. Nominal margin = 300−250 = 50 ms.\n4. Maximum fusion budget with other times fixed: 75 ms.\n5. Queue delay or already-old data requires extending the model.\n\nNo jitter, queues or asynchronous effects modelled; educational target only."}},"exam_10_A_case3_q2":{"answer":{"value":50,"unit":"ms","abs_tolerance":0.15},"rubric":{},"explanation":{"fr":"1. Acquisition limitante : max(60,40) = 60 ms.\n2. Chaîne = 60+20+25+15+10+120 = 250 ms.\n3. Marge nominale = 300−250 = 50 ms.\n4. Budget fusion maximal, autres temps inchangés : 75 ms.\n5. Un délai de file ou une donnée déjà âgée exige une extension du modèle.\n\nPas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"1. Limiting acquisition: max(60,40) = 60 ms.\n2. Chain = 60+20+25+15+10+120 = 250 ms.\n3. Nominal margin = 300−250 = 50 ms.\n4. Maximum fusion budget with other times fixed: 75 ms.\n5. Queue delay or already-old data requires extending the model.\n\nNo jitter, queues or asynchronous effects modelled; educational target only."}},"exam_10_A_case3_q3":{"answer":{"value":75,"unit":"ms","abs_tolerance":0.225},"rubric":{},"explanation":{"fr":"1. Acquisition limitante : max(60,40) = 60 ms.\n2. Chaîne = 60+20+25+15+10+120 = 250 ms.\n3. Marge nominale = 300−250 = 50 ms.\n4. Budget fusion maximal, autres temps inchangés : 75 ms.\n5. Un délai de file ou une donnée déjà âgée exige une extension du modèle.\n\nPas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"1. Limiting acquisition: max(60,40) = 60 ms.\n2. Chain = 60+20+25+15+10+120 = 250 ms.\n3. Nominal margin = 300−250 = 50 ms.\n4. Maximum fusion budget with other times fixed: 75 ms.\n5. Queue delay or already-old data requires extending the model.\n\nNo jitter, queues or asynchronous effects modelled; educational target only."}},"exam_10_A_case3_decision":{"answer":{"choice_id":"exam_10_A_case3_decision_c1"},"rubric":{},"explanation":{"fr":"Définir endpoints et pire cas avant de considérer la marge nominale comme une preuve de deadline. Pas de gigue, file ou désynchronisation modélisée ; cible purement pédagogique.","en":"Define endpoints and worst case before treating nominal margin as deadline evidence. No jitter, queues or asynchronous effects modelled; educational target only."}}}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO autoquest_private.exam_forms (exam_id,form,questions,solutions) VALUES ('exam_10','B','[{"id":"exam_10_B_case1_q1","lessonId":"","position":1,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 31 kWh ; fenêtre utile 80 % ; consommation nominale 165 Wh/km, scénario dégradé 185 Wh/km ; cible 150 km.\n\nCalcule l’autonomie nominale.","en":"Gross battery 31 kWh; usable window 80%; nominal consumption 165 Wh/km, degraded case 185 Wh/km; target 150 km.\n\nCalculate nominal range."},"choices":[],"settings":{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.450909 km.","en":"Absolute tolerance ±0.450909 km."}},"blockId":"exam_10_B_case1"},{"id":"exam_10_B_case1_q2","lessonId":"","position":2,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 31 kWh ; fenêtre utile 80 % ; consommation nominale 165 Wh/km, scénario dégradé 185 Wh/km ; cible 150 km.\n\nCalcule l’autonomie dans le scénario dégradé.","en":"Gross battery 31 kWh; usable window 80%; nominal consumption 165 Wh/km, degraded case 185 Wh/km; target 150 km.\n\nCalculate degraded-case range."},"choices":[],"settings":{"unit":"km","toleranceLabel":{"fr":"Tolérance absolue ±0.402162 km.","en":"Absolute tolerance ±0.402162 km."}},"blockId":"exam_10_B_case1"},{"id":"exam_10_B_case1_q3","lessonId":"","position":3,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 31 kWh ; fenêtre utile 80 % ; consommation nominale 165 Wh/km, scénario dégradé 185 Wh/km ; cible 150 km.\n\nCalcule l’énergie utile nécessaire pour 150 km dégradés.","en":"Gross battery 31 kWh; usable window 80%; nominal consumption 165 Wh/km, degraded case 185 Wh/km; target 150 km.\n\nCalculate usable energy needed for 150 degraded kilometres."},"choices":[],"settings":{"unit":"kWh","toleranceLabel":{"fr":"Tolérance absolue ±0.08325 kWh.","en":"Absolute tolerance ±0.08325 kWh."}},"blockId":"exam_10_B_case1"},{"id":"exam_10_B_case1_decision","lessonId":"","position":4,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Batterie brute 31 kWh ; fenêtre utile 80 % ; consommation nominale 165 Wh/km, scénario dégradé 185 Wh/km ; cible 150 km.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Gross battery 31 kWh; usable window 80%; nominal consumption 165 Wh/km, degraded case 185 Wh/km; target 150 km.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_10_B_case1_decision_c1","position":1,"labels":{"fr":"Moyenner les deux autonomies pour déclarer la cible satisfaite dans les deux cas.","en":"Average both ranges to declare that both scenarios meet the target."}},{"id":"exam_10_B_case1_decision_c2","position":2,"labels":{"fr":"Conserver deux verdicts conditionnels et étudier masse, thermique et consommation avant d’augmenter la batterie.","en":"Keep separate conditional verdicts and examine mass, thermal limits and consumption before increasing battery capacity."}},{"id":"exam_10_B_case1_decision_c3","position":3,"labels":{"fr":"Utiliser l’énergie brute pour tous les scénarios, puisque la fenêtre ne change que la recharge.","en":"Use gross energy in every scenario because the window only affects charging."}}],"settings":{},"blockId":"exam_10_B_case1"},{"id":"exam_10_B_case2_q1","lessonId":"","position":5,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 65 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule le délai de chaîne.","en":"Camera 65 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate chain delay."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.765 ms.","en":"Absolute tolerance ±0.765 ms."}},"blockId":"exam_10_B_case2"},{"id":"exam_10_B_case2_q2","lessonId":"","position":6,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 65 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule la marge nominale.","en":"Camera 65 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate nominal margin."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.135 ms.","en":"Absolute tolerance ±0.135 ms."}},"blockId":"exam_10_B_case2"},{"id":"exam_10_B_case2_q3","lessonId":"","position":7,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 65 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nCalcule le budget fusion maximal.","en":"Camera 65 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nCalculate maximum fusion budget."},"choices":[],"settings":{"unit":"ms","toleranceLabel":{"fr":"Tolérance absolue ±0.21 ms.","en":"Absolute tolerance ±0.21 ms."}},"blockId":"exam_10_B_case2"},{"id":"exam_10_B_case2_decision","lessonId":"","position":8,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Caméra 65 ms et radar 40 ms en parallèle ; ensuite alignement 20, fusion 25, décision 15, réseau 10 et actionneur 120 ms en série. Cible fictive : 300 ms.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Camera 65 ms and radar 40 ms in parallel; then alignment 20, fusion 25, decision 15, network 10 and actuator 120 ms sequentially. Fictional target: 300 ms.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_10_B_case2_decision_c1","position":1,"labels":{"fr":"Définir endpoints et pire cas avant de considérer la marge nominale comme une preuve de deadline.","en":"Define endpoints and worst case before treating nominal margin as deadline evidence."}},{"id":"exam_10_B_case2_decision_c2","position":2,"labels":{"fr":"Additionner caméra et radar même si les acquisitions sont parallèles dans le modèle donné.","en":"Add camera and radar times even though acquisition is parallel in this model."}},{"id":"exam_10_B_case2_decision_c3","position":3,"labels":{"fr":"Utiliser seulement le maximum de tous les temps, y compris ceux en série.","en":"Use only the maximum of all delays, including sequential stages."}}],"settings":{},"blockId":"exam_10_B_case2"},{"id":"exam_10_B_case3_q1","lessonId":"","position":9,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Option A : NRE 30 000 €, coût unitaire 124 €. Option B : NRE 80 000 €, coût unitaire 113 €. Volume 5800 unités ; mêmes fonctions et admissibilité supposées ; pas d’actualisation.\n\nCalcule le coût total A.","en":"Option A: NRE €30,000, unit cost €124. Option B: NRE €80,000, unit cost €113. Volume 5800; equivalent required functions and feasibility assumed; no discounting.\n\nCalculate total A cost."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±2247.6 €.","en":"Absolute tolerance ±2247.6 €."}},"blockId":"exam_10_B_case3"},{"id":"exam_10_B_case3_q2","lessonId":"","position":10,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Option A : NRE 30 000 €, coût unitaire 124 €. Option B : NRE 80 000 €, coût unitaire 113 €. Volume 5800 unités ; mêmes fonctions et admissibilité supposées ; pas d’actualisation.\n\nCalcule le coût total B.","en":"Option A: NRE €30,000, unit cost €124. Option B: NRE €80,000, unit cost €113. Volume 5800; equivalent required functions and feasibility assumed; no discounting.\n\nCalculate total B cost."},"choices":[],"settings":{"unit":"€","toleranceLabel":{"fr":"Tolérance absolue ±2206.2 €.","en":"Absolute tolerance ±2206.2 €."}},"blockId":"exam_10_B_case3"},{"id":"exam_10_B_case3_q3","lessonId":"","position":11,"kind":"numeric","points":0,"required":true,"revision":1,"prompt":{"fr":"Option A : NRE 30 000 €, coût unitaire 124 €. Option B : NRE 80 000 €, coût unitaire 113 €. Volume 5800 unités ; mêmes fonctions et admissibilité supposées ; pas d’actualisation.\n\nCalcule le volume de croisement.","en":"Option A: NRE €30,000, unit cost €124. Option B: NRE €80,000, unit cost €113. Volume 5800; equivalent required functions and feasibility assumed; no discounting.\n\nCalculate break-even volume."},"choices":[],"settings":{"unit":"unités","toleranceLabel":{"fr":"Tolérance absolue ±0.01 unités.","en":"Absolute tolerance ±0.01 unités."}},"blockId":"exam_10_B_case3"},{"id":"exam_10_B_case3_decision","lessonId":"","position":12,"kind":"single_choice","points":0,"required":true,"revision":1,"prompt":{"fr":"Option A : NRE 30 000 €, coût unitaire 124 €. Option B : NRE 80 000 €, coût unitaire 113 €. Volume 5800 unités ; mêmes fonctions et admissibilité supposées ; pas d’actualisation.\n\nRevue technique : quelle décision est défendable avec les données et les limites du cas ?","en":"Option A: NRE €30,000, unit cost €124. Option B: NRE €80,000, unit cost €113. Volume 5800; equivalent required functions and feasibility assumed; no discounting.\n\nTechnical review: which decision is defensible given the case data and limitations?"},"choices":[{"id":"exam_10_B_case3_decision_c1","position":1,"labels":{"fr":"Choisir systématiquement le coût unitaire le plus faible, quel que soit le NRE et le volume.","en":"Always choose the lower unit cost regardless of NRE and volume."}},{"id":"exam_10_B_case3_decision_c2","position":2,"labels":{"fr":"Retenir une option non admissible parce que son score économique est meilleur.","en":"Choose an infeasible option because its economic score is 